const books = [
    { title: "The History of the Standard Oil Company", author: "Ida Tarbell", category: "Historia / Economía", coverId: 313809, description: "Pioneering 1904 muckraking investigation that exposes the predatory tactics by which Standard Oil was built into an industrial monopoly: railroad rebates, predatory pricing, espionage and the systematic destruction of competitors. The exposé helped trigger the antitrust laws that broke up the trust seven years later and set the template for investigative business journalism for the rest of the twentieth century.", descriptionAi: true },
    { title: "La isla misteriosa", author: "Julio Verne", category: "Aventura", coverId: 419656, description: "Cinco prisioneros de guerra huyen en globo durante la guerra de Secesión estadounidense y caen en una isla desierta del Pacífico Sur. Allí, con la pura razón, fabrican herramientas, cultivos, hogares y una pequeña civilización autosuficiente —siempre vigilados, en la sombra, por un misterioso protector cuya identidad la novela revela en el final.", descriptionAi: true },
    { title: "De la Tierra a la Luna", author: "Julio Verne", category: "Ciencia Ficción", coverId: 13478412, description: "Tras el fin de la Guerra Civil estadounidense, los miembros del Gun Club de Baltimore se aburren sin nuevas armas que diseñar y proyectan un cañón gigantesco capaz de enviar un proyectil tripulado hasta la Luna. La novela combina cálculos balísticos plausibles, humor gentil sobre la cultura técnica norteamericana y la apertura de un imaginario espacial al alcance de la imaginación decimonónica.", descriptionAi: true },
    { title: "Antifrágil", author: "Nassim Nicholas Taleb", category: "Filosofía / Economía", coverId: 9180157, status: "read", rating: 5, description: "Más allá de la resistencia y la resiliencia existen sistemas que se benefician del estrés, el caos y la volatilidad: se vuelven más fuertes cuanto más son sacudidos. Tercera entrega del Incerto, propone estrategias concretas para diseñar instituciones, decisiones financieras y proyectos personales que prosperen en la incertidumbre en lugar de ser destruidos por ella. Mezcla anécdotas históricas, mitología y matemáticas para defender una ética opuesta al optimizar y al planificar a toda costa.", descriptionAi: true },
    { title: "El cisne negro", author: "Nassim Nicholas Taleb", category: "Filosofía / Economía", coverId: 12344090, status: "read", rating: 5, description: "Los hechos de gran impacto y probabilidad mínima dominan la historia, la economía y la vida personal mucho más de lo que sospechamos. La tesis recorre los mercados financieros, la ciencia y la guerra para mostrar cómo construimos relatos retrospectivos que disfrazan la aleatoriedad de causalidad. Un libro fundamental sobre los límites del conocimiento y sobre lo que las distribuciones de cola larga implican para tomar decisiones.", descriptionAi: true },
    { title: "Superfreakonomics", author: "Stephen J. Dubner y Steven D. Levitt", category: "Economía", coverId: 6304875, status: "read", rating: 3, description: "Sequel to the original microeconomic experiment, now applied to prostitutes, drunk walking, climate engineering, hospital data and altruism. Brings the same trademark mix of clever empirical research and contrarian punch line, with chapters that work as self-contained essays. The argument is that incentives, properly identified, explain more behaviour than morality.", descriptionAi: true },
    { title: "Las aventuras de Sherlock Holmes", author: "Arthur Conan Doyle", category: "Misterio", coverId: 10547050, description: "Doce relatos publicados en 1892 que reúnen los casos más célebres del detective de Baker Street y de su amigo el doctor Watson. Cada cuento es una pieza autónoma —desde «Escándalo en Bohemia» hasta «La banda de lunares»— que combina deducción, atmósfera victoriana y un humor seco a partes iguales. La colección fija el molde del relato policial moderno y consolida la figura del detective consultor.", descriptionAi: true },
    { title: "La loca de Gandoca", author: "Anacristina Rossi", category: "Novela", coverId: 5085541, description: "Daniela, joven funcionaria del Ministerio de Recursos Naturales, denuncia la complicidad del Estado con el desarrollo turístico depredador en el Refugio Gandoca-Manzanillo, en el Caribe sur de Costa Rica. La novela mezcla los apuntes del diario, los oficios administrativos y las cartas para retratar la lucha por un trozo de costa contra la connivencia de empresarios e instituciones.", descriptionAi: true },
    { title: "Gestión del desarrollo sostenible en territorios rurales: Métodos para la planificación", author: "Varios autores", category: "Desarrollo rural", coverUrl: "https://repositorio.iica.int/server/api/core/bitstreams/c3daae59-a3c9-4f76-8507-0637edd408ef/content", description: "Manual técnico publicado por el IICA: ofrece métodos participativos y herramientas analíticas para diseñar planes de desarrollo rural sostenible a escala territorial. Cubre el diagnóstico socioeconómico, el ordenamiento de cuencas, la priorización de inversiones y los mecanismos de gobernanza local. Útil para extensionistas, alcaldes y técnicos que necesitan articular comunidades, ambiente y economía agraria.", descriptionAi: true },
    { title: "Lo rural es diverso: Evidencia para el caso de Costa Rica", author: "Varios autores", category: "Desarrollo rural", coverUrl: "https://repositorio.iica.int/server/api/core/bitstreams/5346654a-741f-41c4-a21d-9d0ae37feb3f/content", description: "Investigación que cuestiona la imagen monolítica del campo costarricense y documenta su pluralidad de territorios, actividades económicas, formas de tenencia, perfiles demográficos y modos de vida. Aporta evidencia empírica para diseñar políticas rurales que no traten a «el campo» como un solo cliente.", descriptionAi: true },
    { title: "Cultivando mejor para alimentar a todos", author: "Varios autores", category: "Agricultura", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1685972894i/173724991.jpg", description: "Compilación de prácticas y políticas para fortalecer la agricultura familiar en América Latina, con casos de extensión técnica, asociatividad campesina, encadenamientos productivos y mercados locales. Pensado para personas decisoras y técnicos del IICA y de los ministerios agropecuarios de la región.", descriptionAi: true },
    { title: "The 99% Invisible City: A Field Guide to the Hidden World of Everyday Design", author: "Roman Mars y Kurt Kohlstedt", category: "Diseño / Urbanismo", coverId: 10391260, description: "Companion volume to the long-running podcast on the unseen design choices behind cities: fire hydrants, manhole covers, sidewalk markings, traffic lights, building setbacks and even paint on curbs. Each short chapter takes a small object and explains how it shapes daily life, who decided it should look that way and what it would mean to design it differently. Reads like a stroll through urban history with a hand lens.", descriptionAi: true },
    { title: "The Name of the Wind", author: "Patrick Rothfuss", category: "Fantasía", coverId: 11480483, status: "read", rating: 5, description: "First volume of the Kingkiller Chronicle. Kvothe, now a quiet innkeeper at the Waystone Inn, agrees to tell a Chronicler his life story over three days: childhood in a troupe of itinerant performers, the massacre of his family by the legendary Chandrian, years of beggary in the streets of Tarbean, and his admission to the secretive University. A coming-of-age in a richly imagined world, with prose as musical as the lute its protagonist plays.", descriptionAi: true },
    { title: "Creativity, Inc.", author: "Ed Catmull con Amy Wallace", category: "Negocios / Creatividad", coverId: 13124793, status: "read", rating: 5, description: "Behind-the-scenes account of how Pixar Animation Studios was built and kept innovative across two decades. Rather than a how-to manual, the book offers principles about candor, fear, mistakes, and the rituals —the Braintrust, the postmortem— that allow a creative team to keep producing breakthrough work. Filled with anecdotes from the making of Toy Story, Up, Wall-E and others.", descriptionAi: true },
    { title: "Alchemy: The Dark Art and Curious Science of Creating Magic in Brands, Business, and Life", author: "Rory Sutherland", category: "Marketing", coverId: 10184444, description: "Argues that the most powerful business and policy ideas are usually irrational, counter-intuitive and untestable. Drawing on behavioral economics, design and decades inside an ad agency, it urges decision-makers to embrace psychology over spreadsheets and to value «psycho-logic» that produces real-world results, even when nobody can prove why it worked. Equal parts manifesto and entertainment.", descriptionAi: true },
    { title: "El fin de Mr. Y", author: "Scarlett Thomas", category: "Novela", coverId: 115878, description: "Una estudiante de doctorado tropieza con la única copia conocida de un libro maldito del siglo XIX que abre la puerta a la troposfera: un plano interior donde es posible saltar de mente en mente. Lo que empieza como curiosidad académica se convierte en una persecución internacional entre físicos teóricos, agentes secretos y filósofos del lenguaje. La novela mezcla metafísica, mecánica cuántica y suspense con una protagonista insomne y memorable.", descriptionAi: true },
    { title: "Una breve historia de casi todo", author: "Bill Bryson", category: "Divulgación científica", coverId: 14058009, status: "read", rating: 4, description: "Recorrido sin ínfulas por la historia de la ciencia: del Big Bang a la tabla periódica, de la deriva continental al ADN, pasando por las extinciones masivas y la lluvia de polvo cósmico. La voz narradora —curiosa, autoirónica, profundamente legible— acompaña al lector hasta los confines del conocimiento contemporáneo y muestra el quién y el cómo detrás de cada descubrimiento. Una de las introducciones más cariñosas a la curiosidad científica.", descriptionAi: true },
    { title: "Pensar rápido, pensar despacio", author: "Daniel Kahneman", category: "Psicología", coverId: 13290711, status: "read", rating: 5, description: "El cerebro funciona con dos sistemas: uno rápido, intuitivo y emocional; otro lento, deliberativo y exigente. Décadas de investigación experimental en economía conductual y psicología cognitiva sirven para mapear los sesgos sistemáticos que distorsionan nuestras decisiones cotidianas y las más importantes. Un libro denso pero accesible que ha reescrito la manera en que ahora pensamos sobre el juicio humano, la racionalidad y el bienestar.", descriptionAi: true },
    { title: "The End of Alchemy", author: "Mervyn King", category: "Economía", coverId: 8875505, description: "Diagnoses the deep flaws of modern money, banking and the global economy that produced the 2008 crisis. Written by a former Bank of England governor, it argues that the alchemy of turning illiquid loans into supposedly safe demand deposits is structurally unstable and proposes a redesign in which the central bank explicitly becomes a «pawnbroker for all seasons».", descriptionAi: true },
    { title: "Never Split the Difference", author: "Chris Voss con Tahl Raz", category: "Negociación", coverId: 8365942, status: "read", rating: 5, description: "A former FBI lead hostage negotiator distills techniques used in life-or-death situations into a practical guide for everyday negotiation: salary talks, business deals, family disputes. Key tools include mirroring, labeling, calibrated questions and the strategic use of «no». The premise: negotiation is emotional intelligence on overdrive, not a battle of logic.", descriptionAi: true },
    { title: "El teorema Katherine", author: "John Green", category: "Novela juvenil", coverId: 14559681, status: "read", rating: 4, description: "Colin Singleton, un niño prodigio obsesionado con anagramas, sale de gira en un road trip por el sur de Estados Unidos con su mejor amigo después de que su décimo-novena novia llamada Katherine lo dejara. Su misión: convertir las relaciones rotas en una fórmula matemática que prediga toda historia de amor. Una novela juvenil que cruza humor, matemática informal y una reflexión sutil sobre la identidad y la diferencia entre ser único y ser interesante.", descriptionAi: true },
    { title: "The Wasp That Brainwashed the Caterpillar", author: "Matt Simon", category: "Divulgación científica", coverId: 12818938, description: "Tour of evolution's strangest experiments: the wasp that turns a caterpillar into a zombie bodyguard, the snail with eye-stalks taken over by a parasite, the flatworm with a death-spiral life cycle. Each chapter is a short, vivid portrait of an organism whose existence rewrites assumptions about how life can be lived. Curiosity-driven natural history at its most contagious.", descriptionAi: true },
    { title: "La broma infinita", author: "David Foster Wallace", category: "Novela", coverId: 8083760, status: "to-read", description: "Novela monumental ambientada en una academia de tenis y en un centro de rehabilitación a las afueras de Boston, en un futuro cercano donde los años llevan nombre de patrocinador. Una película llamada «La broma infinita» es tan adictiva que quien la ve no puede volver a hacer otra cosa. El libro se ramifica en cientos de notas al pie para retratar la adicción, la dependencia, el entretenimiento como castigo y la pregunta de qué nos hace seguir buscando placer cuando ya nada nos sostiene.", descriptionAi: true },
    { title: "Piénsalo otra vez", author: "Adam Grant", category: "Psicología", coverId: 13484415, status: "read", rating: 5, description: "Un argumento a favor de la duda como herramienta intelectual: cuestionar las propias certezas es un hábito que se entrena. Distingue entre los modos de razonamiento de predicador, fiscal, político y científico, y propone prácticas concretas para repensar ideas con humildad, curiosidad y rigor. Lleno de estudios y casos —de bomberos a magnates— sobre cuándo cambiar de opinión es señal de sabiduría y no de debilidad.", descriptionAi: true },
    { title: "Integrating Food into Urban Planning", author: "Yves Cabannes y Cecilia Marocchino", category: "Urbanismo", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1550976346i/43257461.jpg", description: "Edited volume that maps how cities around the world are bringing food security and urban agriculture into mainstream planning. Includes case studies on community gardens, peri-urban farming, public markets, food councils and land-use policies designed to keep food production close to consumers. A planning manual for the food-system turn in twenty-first-century urbanism.", descriptionAi: true },
    { title: "Deshaciendo errores", author: "Michael Lewis", category: "Psicología / Economía", coverId: 9595637, status: "read", rating: 5, description: "La amistad y la obra conjunta de Daniel Kahneman y Amos Tversky, los psicólogos que pusieron en evidencia los sesgos cognitivos del juicio humano y fundaron la economía conductual. La narrativa retrata a dos mentes complementarias —uno introvertido y rumiante, otro extrovertido y brillante— y sigue la trayectoria de su colaboración desde Jerusalén hasta el Nobel de Economía. Biografía intelectual y libro de divulgación al mismo tiempo.", descriptionAi: true },
    { title: "Yo contengo multitudes", author: "Ed Yong", category: "Divulgación científica", coverId: 8085300, status: "read", rating: 4, description: "Viaje al mundo microbiano que vive dentro y fuera de nuestros cuerpos: bacterias, virus y hongos cooperan, compiten y nos hacen, en buena medida, lo que somos. La narración pasa de las hidrotermales submarinas a las heces fecales experimentales para mostrar cómo el microbioma redefine las fronteras del individuo. Una de las mejores piezas recientes de divulgación científica.", descriptionAi: true },
    { title: "Mi novia se cayó en un pozo ciego", author: "Diego Delfino", category: "Crónica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1383667250i/18631743.jpg", status: "read", rating: 4, description: "Antología de columnas y relatos breves escritos en clave de humor sobre el absurdo cotidiano, las relaciones contemporáneas, el periodismo argentino y la vida después de internet. La prosa pasa con facilidad del chiste a la melancolía y del paseo por Buenos Aires a la reflexión sobre la amistad. Un libro de mesita de noche, perfecto para leer una pieza por noche.", descriptionAi: true },
    { title: "Cien años de soledad", author: "Gabriel García Márquez", category: "Novela", coverId: 12627383, status: "read", rating: 4, description: "*Cien años de soledad* es una novela del escritor colombiano Gabriel García Márquez, ganador del Premio Nobel de Literatura en 1982. Es considerada una obra maestra de la literatura hispanoamericana y universal, cumbre del denominado \"realismo mágico\". Es asimismo una de las obras más traducidas y leídas en español. Narra la historia de la familia Buendía a lo largo de siete generaciones en el pueblo ficticio de Macondo.\n\n*Cien años de soledad* is considered the best work of García Márquez. A novel that narrates the vicisitudes of Aureliano Buendía in the mythic Macondo, a town in some unknown region of Colombia. This novel was written in the magic realism (\"realismo mágico\"), a style that mix together amazing elements taken by fiction and reality." },
    { title: "¿Existe la suerte?", author: "Nassim Nicholas Taleb", category: "Filosofía", coverId: 12344622, status: "read", rating: 5, description: "Primera entrega del Incerto: una arremetida contra la confusión entre habilidad y casualidad en los mercados, los deportes, la política y la ciencia. Recurre a la historia de la probabilidad, a los antiguos griegos y a anécdotas de operadores de bolsa para mostrar cómo las falacias narrativas hacen que veamos talento donde solo hubo ruido. Un manifiesto epistemológico para escépticos del éxito.", descriptionAi: true },
    { title: "El infinito en un junco", author: "Irene Vallejo", category: "Ensayo", coverId: 9689877, status: "read", rating: 5, description: "Este es un libro sobre la historia de los libros. Un recorrido por la vida de ese fascinante artefacto que inventamos para que las palabras pudieran viajar en el espacio y en el tiempo. La historia de su fabricación, de todos los tipos que hemos ensayado a lo largo de casi treinta siglos: libros de humo, de piedra, de arcilla, de juncos, de seda, de piel, de árboles y, los últimos llegados, de plástico y luz.\n\nEs, además, un libro de viajes. Una ruta con escalas en los campos de batalla de Alejandro y en la Villa de los Papiros bajo la erupción del Vesubio, en los palacios de Cleopatra y en el escenario del crimen de Hipatia, en las primeras librerías conocidas y en los talleres de copia manuscrita, en las hogueras donde ardieron códices prohibidos, en el gulag, en la biblioteca de Sarajevo y en el laberinto subterráneo de Oxford en el año 2000. Un hilo que une a los clásicos con el vertiginoso mundo contemporáneo, conectándolos con debates actuales: Aristófanes y los procesos judiciales contra humoristas, Safo y la voz literaria de las mujeres, Tito Livio y el fenómeno fan, Séneca y la posverdad…\n\nPero, sobre todo, esta es una fabulosa aventura colectiva protagonizada por miles de" },
    { title: "Sustainable Food Systems for All", author: "Varios autores", category: "Sostenibilidad", coverId: 14421251, description: "Compendium of policies, technologies and social arrangements required to transition food systems toward sustainability while keeping them inclusive for smallholders and the global poor. Covers agroecology, nutrition transitions, public procurement, fisheries and policy coherence across ministries. Aimed at decision-makers, researchers and civil-society networks working on the food crisis.", descriptionAi: true },
    { title: "La democracia en América", author: "Alexis de Tocqueville", category: "Política", coverId: 13556872, description: "Resultado de un viaje de nueve meses por Estados Unidos en 1831: una observación atenta y desencantada de la igualdad de condiciones, la cultura política, las asociaciones civiles y los hábitos religiosos de la joven república. Analiza con visión profética las fortalezas del sistema y sus riesgos —entre ellos la «tiranía de la mayoría» y el conformismo social— y se convierte en una obra fundacional de la ciencia política moderna.", descriptionAi: true },
    { title: "El movimiento cooperativo en Costa Rica", author: "Óscar Aguilar Bulgarelli y Carlos Luis Fallas Monge", category: "Historia económica", description: "Estudio histórico sobre el origen y desarrollo del cooperativismo costarricense desde fines del siglo XIX hasta el segundo tercio del XX. Recorre los marcos legales que lo posibilitaron, las cooperativas pioneras —café, vivienda, ahorro y crédito— y su papel como pilar de la economía nacional y de la integración social del campesinado. Un documento de referencia para entender un componente fundamental del modelo costarricense.", descriptionAi: true },
    { title: "Momentos estelares de la humanidad", author: "Stefan Zweig", category: "Historia", coverId: 13226425, status: "read", rating: 4, description: "Catorce instantes históricos en los que el destino del mundo se decidió en cuestión de horas o de minutos: la caída de Constantinopla, el descubrimiento del Pacífico, la huida de Napoleón de Elba, la rendición de Lenin tras volver a Rusia en tren. Cada estampa está narrada con la economía y el pulso de un relato breve, casi un drama corto.", descriptionAi: true },
    { title: "Anna Karenina", author: "Lev Tolstói", category: "Novela clásica", coverId: 12327215, description: "Novela monumental sobre la pasión adúltera entre Anna y el conde Vronski, paralela a la vida rural y reflexiva de Kostia Levin. El contraste entre las dos historias dibuja un retrato monumental de la sociedad rusa del siglo XIX —ciudad y campo, aristocracia y servidumbre, fe y secularización— y abre una de las novelas más leídas y discutidas de la literatura universal.", descriptionAi: true },
    { title: "Ilíada", author: "Homero", category: "Épica clásica", coverId: 10540134, description: "Poema épico que narra unos pocos días decisivos del décimo año del asedio aqueo a Troya, centrados en la cólera de Aquiles tras una ofensa de Agamenón y en el destino del príncipe troyano Héctor. El verso alternancia escenas de furia, ternura familiar e intervenciones divinas, con un sentido trágico del honor, el destino y la guerra. Texto fundacional de la literatura occidental, leído y reescrito durante casi tres mil años.", descriptionAi: true },
    { title: "Dioses y héroes: Leyendas de la antigüedad clásica", author: "Gustav Schwab", category: "Mitología", coverId: 997804, description: "Antología clásica de mitos griegos publicada en alemán a mediados del XIX y traducida a casi todas las lenguas: la creación del mundo, los doce trabajos de Heracles, los Argonautas, la guerra de Troya y el regreso de Odiseo. Ordena las leyendas en un hilo narrativo continuo y las cuenta con una claridad pensada para acompañar tanto al lector adulto como al juvenil. Una puerta de entrada al imaginario clásico que sigue siendo de referencia.", descriptionAi: true },
    { title: "Wild Rituals", author: "Caitlin O'Connell", category: "Naturaleza", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1606865252i/56133074.jpg", description: "Decades of fieldwork with elephants, baboons, wolves and other social mammals are condensed into ten rituals that humans share with other species: greetings, courtship, grief, play, gift-giving, group decisions, conflict resolution. Watching animals perform these rituals casts familiar human ceremonies in a new light and suggests how much of «culture» predates language.", descriptionAi: true },
    { title: "Cometas en el cielo", author: "Khaled Hosseini", category: "Novela", coverId: 12328138, status: "to-read", description: "Amistad rota entre Amir y Hassan en el Kabul previo a la invasión soviética; la culpa de una traición infantil persigue al protagonista hasta su exilio en California y lo lleva, ya adulto, a regresar a un Afganistán bajo el dominio talibán. La novela cuenta la historia reciente de un país a través de un duelo personal por la pureza perdida.", descriptionAi: true },
    { title: "Stillness Is the Key", author: "Ryan Holiday", category: "Filosofía / Estoicismo", coverId: 10203119, description: "Third in a popular series on Stoic virtues, devoted to stillness as the underlying capacity that lets every other excellence flourish. The book moves from the mind to the soul to the body, drawing on Marcus Aurelius, Anne Frank, Tiger Woods and Mr. Rogers to argue that disciplined inner quiet is the precondition for clear judgement and meaningful work.", descriptionAi: true },
    { title: "The Obstacle Is the Way", author: "Ryan Holiday", category: "Filosofía / Estoicismo", coverId: 14428233, status: "read", rating: 5, description: "Modern adaptation of the Stoic doctrine that what stands in the way becomes the way. Through historical case studies —John D. Rockefeller, Ulysses Grant, Demosthenes, Steve Jobs— the book teaches how to perceive obstacles accurately, act on them without flinching and convert adversity into propulsion. A short, punchy manual that helped popularize Stoicism for a new generation.", descriptionAi: true },
    { title: "El corazón de las tinieblas", author: "Joseph Conrad", category: "Novela clásica", coverId: 12325082, status: "read", rating: 4, description: "El marinero Charlie Marlow recuerda ante sus compañeros un viaje por el río Congo en busca del enigmático agente comercial Kurtz. La travesía río arriba se transforma en un descenso a los abismos del colonialismo europeo, en una crítica feroz a la civilización «iluminada» y en una pregunta inquietante sobre la condición humana. Una novela corta que cabe en un día de lectura y se queda en la memoria para siempre.", descriptionAi: true },
    { title: "Decidido", author: "Robert Sapolsky", category: "Neurociencia", coverId: 14049171, status: "read", rating: 5, description: "Síntesis de neurobiología, genética y filosofía para argumentar, paso a paso, que no existe el libre albedrío en el sentido que solemos darle a la expresión. La consecuencia ética y social de aceptarlo —dejar de odiar al otro como si pudiera haber elegido otra cosa— se vuelve el eje del libro. Una continuación natural y radical de la obra previa sobre estrés y comportamiento.", descriptionAi: true },
    { title: "Diferentes", author: "Frans de Waal", category: "Etología", coverId: 14128514, status: "read", rating: 5, description: "Revisión de décadas de etología de primates para mostrar que las diferencias entre sexos en los humanos son más matizadas, plásticas y dependientes del contexto de lo que sugiere el binario cultural. Mezcla observaciones de bonobos, chimpancés y humanos con un humor amable y una clara intención política: separar los datos biológicos de los estereotipos de género.", descriptionAi: true },
    { title: "En agosto nos vemos", author: "Gabriel García Márquez", category: "Novela", coverId: 14636533, status: "read", rating: 5, description: "Cada mes de agosto, Ana Magdalena Bach toma el transbordador hasta la isla donde está enterrada su madre para visitar la tumba en la que yace. Esos viajes acaban suponiendo una irresistible invitación a convertirse en una persona distinta durante una noche al año.\n\nEscrita en el inconfundible y fascinante estilo de García Márquez, *En agosto nos vemos* es un canto a la\nvida, a la resistencia del goce, a despecho del paso del tiempo y al deseo femenino. Un regalo inesperado de uno de los escritores más queridos de nuestra lengua." },
    { title: "Humor, Seriously", author: "Jennifer Aaker y Naomi Bagdonas", category: "Negocios", coverId: 10389344, status: "read", rating: 5, description: "Four years of Stanford research distilled into a guide to why humor builds power, trust and resilience at work, and to how anyone can use it skillfully without becoming a class clown. Covers the four humor styles, the science behind funny, and how to deploy levity in meetings, presentations and tough conversations. Funny by design.", descriptionAi: true },
    { title: "Una tierra prometida", author: "Barack Obama", category: "Memorias", coverId: 10449357, status: "to-read", description: "Primer tomo de unas memorias presidenciales que abarcan la transición de Illinois al Senado nacional, las primarias del 2008, la victoria histórica y la primera mitad del mandato hasta la operación contra Bin Laden. Más que un libro de logros, es una crónica honesta de las contradicciones del poder, de la ambición que lo lleva a uno hasta la Casa Blanca y de los costos personales y políticos de gobernar en un país profundamente polarizado.", descriptionAi: true },
    { title: "El gen", author: "Siddhartha Mukherjee", category: "Divulgación científica", coverId: 11320163, status: "to-read", description: "La historia íntima del concepto de gen, desde los experimentos con guisantes en el siglo XIX hasta la edición del genoma con CRISPR. Entrelaza memoria familiar (con una saga de enfermedad mental como hilo conductor), historia de la ciencia y reflexión bioética para preguntar quiénes somos cuando podemos rescribirnos a nivel molecular. Una obra ambiciosa, narrada con la prosa de un médico que es también un escritor de raza.", descriptionAi: true },
    { title: "La transformación de la mente moderna", author: "Jonathan Haidt y Greg Lukianoff", category: "Psicología social", coverId: 10138103, status: "read", rating: 5, description: "Diagnóstico sobre cómo tres «grandes falsedades» —que somos frágiles, que las emociones siempre dicen la verdad y que la vida es una guerra entre buenos y malos— se han instalado en las universidades estadounidenses y han empeorado el debate público y la salud mental de los jóvenes. Propone, en clave estoica y liberal, antídotos pedagógicos basados en la terapia cognitiva, el desacuerdo civil y la antifragilidad.", descriptionAi: true },
    { title: "Monje y robot", author: "Becky Chambers", category: "Ciencia ficción", coverId: 10476616, status: "read", rating: 5, description: "Edición conjunta de dos novelas cortas. En un planeta donde la tecnología y la naturaleza alcanzaron hace siglos un pacto, un monje del té dedicado a escuchar a los humanos y un robot construido a la naturaleza recorren bosques y aldeas preguntándose qué necesita la gente cuando ya no necesita nada material. Solarpunk gentil y filosóficamente serio.", descriptionAi: true },
    { title: "En deuda: Una historia alternativa de la economía", author: "David Graeber", category: "Economía / Antropología", coverId: 6299464, status: "read", rating: 5, description: "Cinco mil años de historia de la deuda demuestran que el crédito antecede al dinero y al trueque, que las economías humanas se organizan tanto sobre la obligación como sobre el intercambio y que los grandes ciclos políticos han pivotado sobre la cancelación o la perpetuación de las deudas. Un argumento antropológico que desmonta el relato ortodoxo de los economistas y replantea qué es realmente una economía.", descriptionAi: true },
    { title: "El futuro por decidir", author: "Christiana Figueres y Tom Rivett-Carnac", category: "Medio ambiente", coverId: 9296919, status: "to-read", description: "Escrito por dos arquitectos del Acuerdo de París, contrapone dos escenarios climáticos posibles para 2050 —la inacción y la transformación— y propone una hoja de ruta práctica de acciones individuales y colectivas. Combina datos científicos rigurosos con un tono deliberadamente esperanzado: no porque la crisis sea menor, sino porque la desesperación es una mala estrategia política frente a la emergencia.", descriptionAi: true },
    { title: "Contra el estado", author: "James C. Scott", category: "Política / Antropología", coverId: 10381520, status: "read", rating: 5, description: "Los primeros Estados de Mesopotamia y de otras regiones se construyeron sobre la coerción, la esclavitud, el monocultivo del cereal y los registros tributarios. La tesis propone una historia alternativa de la civilización en la que los siglos en los que «no había Estado» no eran de barbarie sino de libertad, salud y diversidad alimentaria. Una sacudida a los relatos heredados sobre la civilización.", descriptionAi: true },
    { title: "The Matter with Things, Vol. II: What Then Is True?", author: "Iain McGilchrist", category: "Filosofía", coverId: 13219680, status: "to-read", description: "Second volume of a sequel to The Master and His Emissary. Building on the brain hemispheres and the structure of attention developed in volume one, it argues for a metaphysics that takes seriously matter, life, value, time, space and even the divine. A demanding but rewarding synthesis of neuroscience, philosophy of science and contemplative thought.", descriptionAi: true },
    { title: "The Matter with Things, Vol. I: The Ways to Truth", author: "Iain McGilchrist", category: "Filosofía", coverId: 13219680, status: "to-read", description: "First volume of an exhaustive two-volume project on perception, attention, judgment and reasoning. The book argues that the brain's two hemispheres attend to the world in genuinely different ways and that the modern overreliance on the left hemisphere has narrowed our access to truth. Long, careful and unusually well-illustrated.", descriptionAi: true },
    { title: "Material World", author: "Ed Conway", category: "Divulgación / Materiales", coverId: 14591884, status: "to-read", description: "Tells the story of the six raw materials that built the modern world —sand, salt, iron, copper, oil and lithium— and the immense extractive networks hidden behind everyday objects. The narrative travels from desert sand pits to lithium triangles in the Andes and reveals just how dependent the supposedly weightless digital economy still is on physical stuff.", descriptionAi: true },
    { title: "White Hot Hate", author: "Dick Lehr", category: "Crónica / Periodismo", coverId: 14424872, description: "Pulitzer-winning investigation of a 2016 plot by a Kansas militia, the Crusaders, to bomb an apartment building of Somali refugees the day after the U.S. presidential election. The reporting traces how three middle-aged men were radicalized into white supremacy in rural America and how the FBI used a paid informant to bring the plot down without bloodshed.", descriptionAi: true },
    { title: "Jerks at Work", author: "Tessa West", category: "Psicología organizacional", coverId: 12603134, status: "read", rating: 4, description: "A NYU social psychologist classifies the seven kinds of toxic colleagues you are likely to meet —the kiss-up/kick-down, the credit stealer, the gaslighter, the micromanager— and offers research-backed tactics to defuse each. The framework helps the reader stop blaming themselves for office friction and start running smarter experiments at work.", descriptionAi: true },
    { title: "Trabajos de mierda", author: "David Graeber", category: "Antropología", coverId: 8798647, status: "read", rating: 5, description: "Diagnóstico antropológico de una paradoja contemporánea: una parte enorme del empleo en oficinas, consultoras, burocracias y plataformas no aporta valor a quienes lo realizan ni a la sociedad y produce sufrimiento psíquico. El libro tipologiza —«lacayos», «tachatuercas», «taimados»— y propone, en el final, ideas para reducir el peso moral del trabajo inútil. Una crítica al productivismo desde la izquierda libertaria.", descriptionAi: true },
    { title: "El amanecer de todo: Una nueva historia de la humanidad", author: "David Graeber y David Wengrow", category: "Antropología / Historia", coverId: 11359192, status: "read", rating: 5, description: "Revisa, con la arqueología más reciente, los relatos lineales sobre el origen de la civilización y muestra que las sociedades prehistóricas fueron mucho más variadas, igualitarias y conscientes políticamente de lo que la versión Hobbes-Rousseau supone. Propone que la humanidad ensayó durante decenas de miles de años regímenes sociales muy distintos —con autoridad y sin ella— y que las jaulas del Estado y la propiedad no eran inevitables.", descriptionAi: true },
    { title: "El estrecho sendero entre deseos", author: "Patrick Rothfuss", category: "Fantasía", coverId: 7309640, status: "to-read", description: "Novela breve ambientada en la Cuatro Esquinas: durante un solo día, Bast, el aprendiz fae de Kvothe, recorre el pueblo concediendo favores en clave de cuento de hadas a los niños que sepan pagarlos con secretos. La prosa tiene la misma cadencia musical de la trilogía mayor y aprovecha la economía de las pocas páginas para explorar la moralidad enrevesada de los seres mágicos que no son ni buenos ni malos.", descriptionAi: true },
    { title: "80 Tools for Participatory Development", author: "Frans Geilfus", category: "Desarrollo participativo", coverUrl: "https://repositorio.iica.int/server/api/core/bitstreams/53681510-c8b7-4e6f-8510-9d50b56b3daf/content", description: "Field-tested manual gathering eighty participatory tools —maps, matrices, transect walks, calendars, ranking exercises, problem trees— for community-based rural development across Latin America. Each tool is presented with materials, time required, step-by-step instructions and tips for handling group dynamics. A staple of extension workers' shelves.", descriptionAi: true },
    { title: "A Little Princess", author: "Frances Hodgson Burnett", category: "Literatura juvenil", coverId: 2328315, description: "Sara Crewe is the spoiled but bookish daughter of a wealthy British captain in colonial India when she is sent to a London boarding school. After her father's sudden death and bankruptcy, she is reduced to scullery maid in the same school where she once reigned. The novel insists, with quiet defiance, that nobility of character is independent of circumstance.", descriptionAi: true },
    { title: "Los ensayos (Tomo I)", author: "Michel de Montaigne", category: "Ensayo clásico", coverId: 13482735, status: "read", rating: 5, description: "Primer tomo de los Essais, escritos en el último tercio del XVI: el género del ensayo personal nace aquí como diálogo del autor consigo mismo. Recorre la educación, la amistad, la muerte, la curiosidad y los hábitos del cuerpo con una mezcla inconfundible de cita clásica, anécdota y autoanálisis. La frase «¿Qué sé yo?» se vuelve método y permite empezar a leer literatura moderna como exploración de la propia interioridad.", descriptionAi: true },
    { title: "Los ensayos (Tomo II)", author: "Michel de Montaigne", category: "Ensayo clásico", coverId: 13482735, status: "read", rating: 5, description: "Segundo tomo de los Essais, donde el autor extiende sus reflexiones a la prudencia, los hábitos, la conciencia y la apología de Raimundo Sabunde —el ensayo más largo y filosófico de la obra—. Discute la educación de los hijos, la guerra, la imaginación y la presunción humana con una mezcla de escepticismo y compasión que solo madura con la edad. Una lectura ideal para acompañar varias estaciones.", descriptionAi: true },
    { title: "Los ensayos (Tomo III)", author: "Michel de Montaigne", category: "Ensayo clásico", coverId: 13482735, status: "read", rating: 5, description: "Tercer tomo de los Essais. Ya maduro y enfermo, el ensayista escribe sobre la vejez, la experiencia, el cuerpo, la fragilidad y la diplomacia en una prosa más íntima y libre que en los volúmenes previos. La célebre frase final —«Toda moral se aplica a una vida común y sin esplendor»— condensa el espíritu de la obra y la convierte en el mejor manual antiguo sobre cómo envejecer con elegancia.", descriptionAi: true },
    { title: "One Piece, vols. 1-2-3 (East Blue)", author: "Eiichiro Oda", category: "Manga", coverId: 1020563, description: "Opening volumes of the epic pirate manga. Monkey D. Luffy —who gained rubber powers from a forbidden fruit— sets sail in the East Blue chasing his dream of becoming the King of the Pirates and finding the legendary treasure One Piece. Along the way he begins to gather a misfit crew that includes the swordsman Roronoa Zoro and the master thief Nami.", descriptionAi: true },
    { title: "One Piece, vols. 4-5-6 (East Blue)", author: "Eiichiro Oda", category: "Manga", coverId: 9485994, description: "The Straw Hats face Captain Kuro at Syrup Village and Don Krieg on the floating Baratie restaurant, where Sanji the chef joins the crew and the swordsman Dracule Mihawk puts Zoro brutally in his place. Foundational early arcs that establish the manga's mix of slapstick, tragedy and over-the-top action.", descriptionAi: true },
    { title: "One Piece, vols. 7-8-9 (East Blue)", author: "Eiichiro Oda", category: "Manga", coverId: 1020569, description: "Arlong Park arc. Luffy and his crew take on the fishman pirate who has enslaved Nami's home village under a cruel tribute scheme. One of the most beloved early arcs, where the manga first reveals the depth of its emotional reach and Nami's backstory pays off in a roar.", descriptionAi: true },
    { title: "One Piece, vols. 10-11-12 (East Blue)", author: "Eiichiro Oda", category: "Manga", coverId: 1020698, description: "Closing volumes of the East Blue saga. The crew clashes with the marine captain Smoker in Loguetown, the city where Gold Roger was executed, picks up a new ship and a new dreamer, then sails through Reverse Mountain into the Grand Line in pursuit of the One Piece.", descriptionAi: true },
    { title: "One Piece, vols. 13-14-15 (Baroque Works)", author: "Eiichiro Oda", category: "Manga", coverId: 3122735, description: "Opening of the Alabasta saga. The crew lands on Whiskey Peak, meets princess Vivi, encounters the assassin Mister 9 and uncovers a plot by the criminal organization Baroque Works to overthrow the desert kingdom of Alabasta. Their newest member, the warrior reindeer doctor Tony Tony Chopper, joins the journey.", descriptionAi: true },
    { title: "One Piece, vols. 16-17-18 (Baroque Works)", author: "Eiichiro Oda", category: "Manga", coverId: 1020703, description: "Middle of the Alabasta saga. The Straw Hats race through the desert toward Alubarna to stop the Warlord Crocodile from seizing power, dodging sandstorms, dance ribbon mountains and a parade of Baroque Works officers whose codenames go from Mister 1 to Miss Doublefinger.", descriptionAi: true },
    { title: "Veronika decide morir", author: "Paulo Coelho", category: "Novela", coverId: 4926517, description: "Una joven eslovena de veinticuatro años sobrevive a su intento de suicidio y despierta en Villete, un sanatorio mental en Liubliana donde le anuncian que su corazón está dañado y que solo le quedan unos días de vida. En ese plazo descubre, por primera vez, intensidades que la vida acomodada nunca le había dado. Una novela breve sobre la cordura, la locura y el deseo de existir.", descriptionAi: true },
    { title: "Mamita Yunai", author: "Carlos Luis Fallas", category: "Novela", coverId: 13864196, description: "Crónica novelada de las brutales condiciones de los peones bananeros del Caribe costarricense bajo la United Fruit Company a comienzos del siglo XX. La voz narradora —un trabajador veterano— recorre el bosque, los campamentos, las elecciones manipuladas y los crímenes invisibilizados con una prosa exacta y desolada. Un clásico de la literatura social latinoamericana.", descriptionAi: true },
    { title: "El principito", author: "Antoine de Saint-Exupéry", category: "Literatura", coverId: 13499066, description: "Un aviador caído en el desierto del Sahara conoce a un niño venido de un asteroide, B-612, que cuida una rosa y se pregunta por el sentido de los adultos. Bajo el ropaje de cuento, una meditación poética sobre la amistad, el amor, la pérdida y la mirada que los adultos olvidan en su empeño por ser «serios». Quizá el libro más traducido y leído del siglo XX, y siempre distinto en cada relectura.", descriptionAi: true },
    { title: "Don Quijote de la Mancha (I)", author: "Miguel de Cervantes", category: "Novela clásica", coverId: 14428305, status: "read", rating: 4, description: "Primera parte publicada en 1605. Un hidalgo manchego enloquecido por las novelas de caballería se hace caballero andante con el nombre de Don Quijote, sale al mundo en busca de aventuras y se hace acompañar por un labrador llamado Sancho Panza. Cada episodio —los molinos, la venta, los galeotes, Dulcinea— se cuenta con humor, ternura y una distancia irónica que inaugura la novela moderna.", descriptionAi: true },
    { title: "Don Quijote de la Mancha (II)", author: "Miguel de Cervantes", category: "Novela clásica", coverId: 14428305, status: "read", rating: 5, description: "Segunda parte publicada en 1615. Don Quijote y Sancho viven nuevas aventuras, esta vez conscientes de su fama literaria: los personajes que se cruzan ya han leído el primer tomo y juegan con ellos. La novela se vuelve más reflexiva y melancólica, dialoga con el plagiario Avellaneda y se acerca, en la cabalgata final, a una de las muertes más conmovedoras de la literatura.", descriptionAi: true },
    { title: "Los anarquistas", author: "Roderick Kedward", category: "Historia política", coverId: 6383480, description: "Síntesis histórica del anarquismo europeo del siglo XIX a través de sus principales pensadores —Bakunin, Kropotkin, Proudhon— y de las acciones que marcaron a la opinión pública: la Comuna de París, los atentados de fin de siglo, las internacionales obreras. Un balance equilibrado de las ideas y de su práctica, que rastrea por qué este movimiento siguió siendo influyente mucho después de su derrota política frente al marxismo organizado.", descriptionAi: true },
    { title: "Sandy: Leyendas a la tica", author: "Roger Bolaños", category: "Folclor", description: "Recopilación de leyendas y tradiciones populares costarricenses adaptadas con humor tico y un toque didáctico. El Cadejos, la Tulivieja, la Llorona, el carretón sin bueyes y otros personajes del imaginario popular aparecen ordenados por regiones y acompañados de breves contextos históricos. Pensado para el público infantil y juvenil.", descriptionAi: true },
    { title: "Serpientes, venenos y ofidismo en Centroamérica", author: "Varios autores", category: "Biología", description: "Tratado técnico de herpetología y toxinología que describe las especies venenosas de la región, sus hábitos, los mecanismos de inoculación, las composiciones bioquímicas de cada veneno y los protocolos médicos de atención. Pensado tanto para naturalistas como para personal sanitario rural, sirve también de catálogo identificador con láminas y claves taxonómicas.", descriptionAi: true },
    { title: "Quién es quién en la pintura de Goya", author: "Pedro Jesús Fernández", category: "Arte", coverId: 12717205, description: "Identifica a los personajes históricos retratados por Francisco de Goya y reconstruye el contexto político y social de la corte española de finales del XVIII y principios del XIX. Quién es la duquesa de Alba, quién Cabarrús, quién aparece de espaldas en los Caprichos: cada cuadro se vuelve una pequeña intriga cortesana cuando se sabe leer a sus protagonistas.", descriptionAi: true },
    { title: "Guía de Razonamiento Lógico Matemático", author: "AMP", category: "Matemáticas", description: "Manual de preparación para pruebas universitarias y de admisión: lógica proposicional, secuencias, razonamiento abstracto, probabilidad básica y problemas de planteamiento. Cada tema viene con teoría breve, ejercicios resueltos y baterías de práctica diseñadas para entrenar la velocidad y la precisión en el examen. Material clásico de la AMP para bachilleres costarricenses.", descriptionAi: true },
    { title: "Breve historia contemporánea de Costa Rica", author: "Héctor Pérez Brignoli", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1677794976i/3684777.jpg", description: "Síntesis crítica de la formación del Estado costarricense, la consolidación de la democracia, el modelo agroexportador y los desafíos del siglo XX. Tres tomos del Fondo de Cultura Económica condensados en una lectura accesible que da cuenta de las transformaciones económicas, demográficas y culturales del país en relación con la región centroamericana.", descriptionAi: true },
    { title: "El monje que vendió su Ferrari", author: "Robin S. Sharma", category: "Autoayuda", coverId: 48817, description: "Fábula sobre un abogado millonario que sufre un infarto durante un juicio, vende todas sus posesiones y se retira a los Himalayas; regresa años después, ya convertido en sabio, con siete lecciones sobre disciplina, propósito y paz interior. Un libro de autoayuda contado como cuento iniciático que se ha leído por millones en todo el mundo.", descriptionAi: true },
    { title: "Cómo ganar amigos e influir sobre las personas", author: "Dale Carnegie", category: "Autoayuda", coverId: 13195013, description: "Clásico de 1936 que recopila principios para ganar simpatía, persuadir y liderar a partir de historias reales —Lincoln, Edison, Rockefeller— y de reglas prácticas de trato con la gente. La premisa es simple y radical: la mayoría de los conflictos no se resuelven con razones sino con escucha, reconocimiento y atención sincera al interés ajeno. Casi un siglo después sigue siendo lectura obligatoria de la cultura corporativa.", descriptionAi: true },
    { title: "Memorias de un primate", author: "Robert Sapolsky", category: "Memorias / Ciencia", coverId: 12329605, status: "read", rating: 5, description: "Recuerdo de los veranos de juventud estudiando una tropa de babuinos en el Serengeti: las jerarquías, las amistades inesperadas, los celos, los duelos y la política primate. El libro alterna ciencia y memoir, retrata a personajes con nombres propios y traza, en paralelo, el aprendizaje del joven investigador cuyo trabajo posterior sobre el estrés humano nació allí.", descriptionAi: true },
    { title: "El nombre de la rosa", author: "Umberto Eco", category: "Novela histórica", coverId: 8598263, status: "read", rating: 5, description: "Ambientada en una abadía benedictina del norte de Italia en 1327, una serie de muertes envuelve a la comunidad y el franciscano Guillermo de Baskerville llega para investigar con su novicio Adso de Melk. La novela mezcla intriga policial, semiótica, debate teológico y un laberinto bibliotecario para conjurar el espíritu de un medievo que se aleja del cliché. Uno de los best-sellers culturales del siglo XX que jamás traicionó la inteligencia del lector.", descriptionAi: true },
    { title: "Don't Sleep, There Are Snakes", author: "Daniel L. Everett", category: "Lingüística / Antropología", coverId: 9833943, status: "read", rating: 5, description: "Decades among the Pirahã of the Amazon, an isolated group whose language has no numbers, no color terms and no recursive sentences, push a missionary turned linguist to question Noam Chomsky's universal grammar and his own faith. A memoir of fieldwork, conversion and de-conversion that became one of the most discussed books in cognitive science in years.", descriptionAi: true },
    { title: "Las ventajas de ser un marginado", author: "Stephen Chbosky", category: "Novela juvenil", coverId: 13556024, status: "read", rating: 5, description: "Novela epistolar protagonizada por Charlie, un adolescente introvertido que escribe cartas a un destinatario anónimo durante su primer año de secundaria. Las cartas relatan amistades intensas con dos compañeros mayores, descubrimientos literarios y musicales, una historia familiar atravesada por el abuso y un duelo no resuelto. Lectura adolescente convertida en clásico moderno.", descriptionAi: true },
    { title: "Todo está jodido", author: "Mark Manson", category: "Ensayo", coverId: 8231990, status: "read", rating: 5, description: "Crítica del optimismo terapéutico y la cultura de la autoayuda contemporánea: la sociedad de la abundancia material ha producido una crisis de esperanza que solo puede repararse aceptando lo trágico de la condición humana. Mezcla a Nietzsche, Becker y el estoicismo con anécdotas personales para proponer una ética del límite y del esfuerzo digno frente a la promesa de felicidad ilimitada.", descriptionAi: true },
    { title: "Circe", author: "Madeline Miller", category: "Mitología / Novela", coverId: 8739376, status: "read", rating: 5, description: "Retelling of Greek myth from the perspective of the witch of Aeaea, the minor goddess banished to the island where Odysseus will eventually land. The novel follows her from a slighted nymph in her father's palace through Daedalus, the Minotaur, Medea and Penelope to a slow self-creation as the most powerful woman in the cosmos. Lyrical, feminist and gripping.", descriptionAi: true },
    { title: "The Ultimate Hitchhiker's Guide to the Galaxy", author: "Douglas Adams", category: "Ciencia ficción", coverId: 12986869, status: "read", rating: 5, description: "Single-volume omnibus of the five Hitchhiker novels. Arthur Dent's increasingly absurd intergalactic travels after Earth is demolished to make way for a hyperspace bypass: the answer is forty-two, the question is missing, the dolphins have left, and Marvin the Paranoid Android complains for billions of years. Comedy as cosmology.", descriptionAi: true },
    { title: "Gilgamesh", author: "Anónimo", category: "Épica clásica", coverId: 474300, description: "El poema épico babilónico más antiguo conocido, escrito en tablillas de arcilla hace más de cuatro mil años. El rey de Uruk, dos terceras partes divino y un tercio humano, emprende con su amigo Enkidu hazañas heroicas; tras la muerte de éste, parte solo en busca de la inmortalidad y se enfrenta, al borde del río de la muerte, a la dura verdad del límite humano. Texto raíz de la literatura universal.", descriptionAi: true },
    { title: "El conde de Montecristo", author: "Alejandro Dumas", category: "Novela clásica", coverId: 14566908, status: "read", rating: 5, description: "Edmond Dantès, joven marino a punto de casarse y de ascender a capitán, es traicionado por la envidia de sus rivales y encerrado durante catorce años en el castillo de If. Al escapar y heredar el tesoro de un sabio compañero de celda, regresa convertido en conde para ejecutar una venganza minuciosa y aristocrática contra quienes lo destruyeron. Folletín perfecto sobre el peso del tiempo, la justicia y la imposibilidad del olvido.", descriptionAi: true },
    { title: "The Broken Ladder", author: "Keith Payne", category: "Psicología social", coverId: 8814832, status: "read", rating: 5, description: "How economic inequality —not just poverty in the abstract— affects health, happiness, parenting, voting and even risk taking. Drawing on social psychology experiments and natural data, the book shows that humans constantly compare and that gaps as much as absolute levels shape behaviour. Persuasive, with policy implications across the political spectrum.", descriptionAi: true },
    { title: "Orgullo y prejuicio", author: "Jane Austen", category: "Novela clásica", coverId: 13498988, status: "to-read", description: "El amor inicialmente hostil entre la inteligente Elizabeth Bennet y el reservado señor Darcy en la Inglaterra rural del XIX. La novela disecciona, con ironía y un oído imbatible para el diálogo, el sistema matrimonial, la herencia, el cotilleo y los modales de una sociedad donde una mujer solo podía asegurar su futuro casándose bien. Una comedia de costumbres convertida en clásico universal.", descriptionAi: true },
    { title: "Las leyes del Serengeti", author: "Sean B. Carroll", category: "Biología", coverId: 8881359, description: "El ecosistema de la sabana africana es la mejor escuela para entender cómo se regulan las poblaciones de seres vivos: del fitoplancton al león, los mismos principios de regulación —no de abundancia— sostienen la vida. La narración pasa de los grandes mamíferos al colesterol y al cáncer para mostrar que las células de nuestro cuerpo obedecen las mismas leyes que las cebras y los ñus en migración.", descriptionAi: true },
    { title: "Frankenstein", author: "Mary Shelley", category: "Novela clásica", coverId: 12356249, status: "read", rating: 3, description: "Subtitled The Modern Prometheus and first published anonymously in 1818. A young Genevese scientist obsessed with the secret of life assembles a being from corpses and animates it, then recoils in horror from his creation. The «creature», intelligent and miserable, embarks on a haunting confrontation with its maker that ranges from the Alps to the Arctic. A foundational text of science fiction.", descriptionAi: true },
    { title: "Dictadores", author: "Frank Dikötter", category: "Historia política", coverId: 10869587, description: "Estudio comparativo de ocho dictadores del siglo XX —Mussolini, Hitler, Stalin, Mao, Kim Il-sung, Ceauşescu, Duvalier y Mengistu— a través del culto a la personalidad que cada uno construyó para sostenerse en el poder. El libro examina las técnicas comunes: producir miedo, fabricar adulación pública y desconfianza privada, y reescribir la historia a su medida.", descriptionAi: true },
    { title: "Charlatanes", author: "Moisés Naím y Quico Toro", category: "Política", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1738639001i/225819376.jpg", status: "reading", description: "Anatomía de los políticos contemporáneos que utilizan la mentira sistemática como herramienta para acumular y conservar poder en la era de las redes sociales. Desde Trump y Bolsonaro hasta Maduro y Petro, el libro identifica patrones comunes —la victimización, la conspiración, el ataque a la prensa— y propone defensas institucionales para evitar que la mentira se vuelva ley.", descriptionAi: true },
    { title: "La sociedad de la transparencia", author: "Byung-Chul Han", category: "Filosofía", coverId: 8083811, description: "Crítica filosófica del imperativo contemporáneo de la transparencia total: lo que parece un avance democrático opera como una nueva forma de control, en la que la intimidad, la distancia y el misterio quedan abolidos. Una sociedad sin secretos es también una sociedad sin Eros, sin lo otro y sin posibilidad de pensamiento propio. Breve ensayo que abrió la serie corta del filósofo coreano-alemán.", descriptionAi: true },
    { title: "Si mi biblioteca ardiera esta noche", author: "Aldous Huxley", category: "Ensayo", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1289005233i/9649980.jpg", status: "to-read", description: "Selección breve de textos en los que el ensayista británico reflexiona sobre los libros que han marcado su vida y sobre la práctica de la lectura como forma de pensamiento. La pregunta del título es a la vez una hipótesis y una declaración: ¿qué quedaría en la cabeza si todas las páginas se perdieran? Una pieza pequeña y cálida sobre el oficio de leer.", descriptionAi: true },
    { title: "Cartas a Lucilio", author: "Lucio Anneo Séneca", category: "Filosofía clásica", coverId: 8256111, description: "Ciento veinticuatro cartas dirigidas a un discípulo durante los últimos años de vida del filósofo, en las que se conversa con franqueza sobre la amistad, la muerte, la riqueza, el tiempo y la libertad interior. Cada epístola es a la vez ejercicio espiritual y consejo práctico; juntas componen el manual estoico más entrañable y leído de la Antigüedad.", descriptionAi: true },
    { title: "La guerra no tiene rostro de mujer", author: "Svetlana Alexiévich", category: "Crónica", coverId: 13135723, description: "Testimonios de cientos de mujeres soviéticas que combatieron en la Segunda Guerra Mundial como francotiradoras, enfermeras, cocineras, mecánicas o tanquistas, junto a relatos de la vida en el frente y del regreso silencioso a casa. La obra restituye una memoria invisibilizada por la versión oficial heroica y masculina, con una atención obsesiva al detalle físico y emocional. Una de las obras maestras del periodismo literario del siglo XX.", descriptionAi: true },
    { title: "El lecho de Procusto", author: "Nassim Nicholas Taleb", category: "Filosofía", coverId: 14156240, status: "read", rating: 5, description: "Aforismos breves que destilan en pocas palabras las ideas centrales de un proyecto filosófico más amplio: la asimetría del conocimiento, la fragilidad de los expertos, la sabiduría de las prácticas tradicionales y los peligros de la abstracción contemporánea. Cada entrada es una provocación pulida y cada sección invita a meditarse despacio, como manual de bolsillo para mirar el mundo con escepticismo activo.", descriptionAi: true },
    { title: "Cuentos imprescindibles del siglo XX de América Latina", author: "Varios autores", category: "Antología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1753467428i/238970160.jpg", description: "Antología que reúne piezas canónicas del relato breve latinoamericano del XX: cuentos rurales, fantásticos, urbanos, políticos, eróticos y absurdos. Permite leer de un tirón a Borges, Cortázar, Rulfo, Onetti, García Márquez, Bombal o Lispector, y notar las afinidades subterráneas que conectan tradiciones nacionales muy distintas en una conversación literaria continental.", descriptionAi: true },
    { title: "How to Diagnose and Fix Everything Electronic", author: "Michael Jay Geier", category: "Electrónica", coverId: 9594813, description: "Hands-on guide that teaches hobbyists and technicians to troubleshoot and repair almost any consumer electronic device. Covers the right tools, basic measurements with a multimeter and oscilloscope, how to read schematics, and a methodical fault-tracing process that works whether the broken item is a power supply, a guitar amp or a vintage VCR.", descriptionAi: true },
    { title: "El arte de no ser gobernados", author: "James C. Scott", category: "Antropología política", coverId: 6289268, status: "read", rating: 4, description: "Historia de Zomia, la inmensa región montañosa del sureste asiático que durante siglos sirvió de refugio a pueblos que escogieron la marginalidad estatal frente al sometimiento. La tesis es contraintuitiva: la agricultura migratoria, los sistemas de escritura efímeros y las jerarquías difusas no son rezagos de la barbarie sino estrategias deliberadas para evitar el control de los reinos del valle. Repensar la historia desde quienes huyen.", descriptionAi: true },
    { title: "Meditaciones", author: "Marco Aurelio", category: "Filosofía clásica", coverId: 10469464, status: "read", rating: 5, description: "Cuaderno privado del emperador romano: doce libros de ejercicios espirituales escritos en griego durante las campañas militares en la frontera del Danubio. No fue concebido para publicarse, lo que explica su tono íntimo y reiterativo: aplicar los principios estoicos al juicio, la ira, la muerte y el deber del cargo. Un texto que sigue siendo manual de conducta para lectores muy distintos.", descriptionAi: true },
    { title: "Dominio", author: "Tom Holland", category: "Historia", coverId: 13458584, status: "read", rating: 4, description: "Tesis ambiciosa: los valores morales occidentales contemporáneos —incluidos los más laicos como la igualdad, los derechos humanos o la separación entre Iglesia y Estado— están profundamente moldeados por dos mil años de cristianismo. La historia recorre los Padres de la Iglesia, las cruzadas, la Reforma, la Ilustración y el feminismo para mostrar cómo la herencia cristiana atraviesa incluso a quienes se creen ajenos a ella.", descriptionAi: true },
    { title: "Miradas sobre la desigualdad", author: "Branko Milanović", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1715966942i/206801504.jpg", description: "Tres siglos de teoría económica sobre la desigualdad, desde Quesnay y Smith hasta Marx, Pareto, Kuznets y Piketty. Cada autor recibe un capítulo que cruza biografía, método y datos, y muestra cómo la pregunta por «quién recibe qué y por qué» ha sido siempre central a la economía y la política. Un libro a la altura de su autor, gran especialista en desigualdad global.", descriptionAi: true },
    { title: "Historia de Costa Rica", author: "Iván Molina y Steven Palmer", category: "Historia", coverId: 12286807, description: "Síntesis crítica de la historia del país desde la conquista hasta el siglo XXI, atenta tanto a los grandes procesos económicos y demográficos —caficultura, banano, café, urbanización— como a las transformaciones culturales, religiosas y políticas. Una historiografía rigurosa y legible, escrita para no especialistas.", descriptionAi: true },
    { title: "Hacia las estrellas", author: "Mary Robinette Kowal", category: "Ciencia ficción", coverId: 8290909, status: "to-read", description: "Primera novela de la serie Lady Astronaut. En 1952, un meteorito devasta el planeta y la humanidad acelera la carrera espacial para asegurar la supervivencia en otros mundos. Elma York, matemática y aviadora durante la Segunda Guerra Mundial, lucha por ser la primera astronauta en una NASA dispuesta a usar sus cálculos pero no a verla volar. Ciencia ficción dura con conciencia de género y clase.", descriptionAi: true },
    { title: "Matadero Cinco", author: "Kurt Vonnegut", category: "Novela", coverId: 12727001, status: "read", rating: 5, description: "Billy Pilgrim, soldado estadounidense superviviente del bombardeo de Dresde, queda «desencajado del tiempo» y rememora episodios de su vida en cualquier orden: la guerra, su matrimonio, la abducción extraterrestre, su muerte. La novela —fragmentada, irónica, antibelicista— se ha convertido en uno de los textos centrales del posmodernismo estadounidense.", descriptionAi: true },
    { title: "Las mil y una noches (Tomo I)", author: "Anónimo", category: "Literatura clásica", coverId: 12339547, description: "Primer volumen del ciclo árabe en el que la astuta Sherezade aplaza su ejecución contándole al rey Shahriar un cuento cada noche. Reúne historias de Aladino, los siete viajes de Simbad y otras leyendas del mundo islámico medieval, con su mezcla característica de magia, viajes mercantiles y deseo. Una obra abierta que ha crecido durante mil años con cada nuevo traductor.", descriptionAi: true },
    { title: "Las mil y una noches (Tomo II)", author: "Anónimo", category: "Literatura clásica", coverId: 12339547, description: "Segundo volumen del ciclo. Continúan las historias que Sherezade narra al sultán para conservar la vida: viajes a tierras remotas, amores desmesurados, demonios encerrados en lámparas, sultanes destronados y ciudades fantasmas en el desierto. Una geografía imaginaria que va de Bagdad a Cantón y que sigue alimentando la fantasía universal.", descriptionAi: true },
    { title: "The 48 Laws of Power", author: "Robert Greene", category: "Estrategia", coverId: 6424160, status: "to-read", description: "Compendium of laws distilled from three thousand years of history, ranging from Sun Tzu to Talleyrand to Hollywood power players. Each law is stated as an aphorism («Never outshine the master», «Win through your actions, never through argument») and illustrated with parallel historical anecdotes, observances and transgressions. A cynical, instructive book that is simultaneously a manual and a warning.", descriptionAi: true },
    { title: "The Subtle Art of Not Giving a F*ck", author: "Mark Manson", category: "Autoayuda", coverId: 8231990, status: "read", rating: 5, description: "Pop-philosophy bestseller arguing that the secret to a good life is choosing carefully what to care about. Mixes blunt language, autobiographical anecdotes and threads of Stoicism and Buddhist thought to push back against the cult of relentless positivity. A short, punchy book that became a global counter-cultural phenomenon.", descriptionAi: true },
    { title: "The Daily Stoic", author: "Ryan Holiday y Stephen Hanselman", category: "Filosofía / Estoicismo", coverId: 10302294, description: "366 daily meditations on Stoic philosophy: one passage per day from Marcus Aurelius, Seneca, Epictetus or others, paired with a contemporary commentary and a daily theme. Built as a structured year-long practice for readers who want to internalize Stoic principles rather than just read about them. A bedside-table classic of the modern Stoic revival.", descriptionAi: true },
    { title: "Seres sintientes", author: "Jackie Higgins", category: "Biología", coverId: 12657268, description: "Trece sentidos animales —el olfato del salmón que vuelve al río, el campo magnético del petirrojo, el oído del búho, la visión ultravioleta de la mantis camaronera— iluminan capacidades sensoriales humanas que no sabíamos tener. Un viaje a la fenomenología comparada de la percepción que cambia la idea de lo que significa estar vivo.", descriptionAi: true },
    { title: "Final de partida", author: "Peter Turchin", category: "Historia / Sociología", coverId: 13790624, description: "Aplicación de la cliodinámica al ciclo histórico de auge y crisis de las élites para argumentar, con modelos cuantitativos, que Estados Unidos se acerca a un período de inestabilidad estructural similar al de las décadas previas a las guerras civiles del XIX. Un análisis frío y polémico de la política contemporánea desde la historia comparada.", descriptionAi: true },
    { title: "Anarquía relacional", author: "JC Pérez Cortés", category: "Sociología", coverId: 10371434, status: "to-read", description: "Introducción a la propuesta de relaciones afectivas sin jerarquías ni etiquetas predefinidas, en la que cada vínculo se construye según los acuerdos de los participantes y no según un guion social. Discute la pareja, la familia, la amistad y los celos a la luz de la teoría queer y del activismo no monógamo. Un manual para pensar cómo nos relacionamos cuando los moldes heredados ya no nos sirven.", descriptionAi: true },
    { title: "Modos de existir", author: "James Bridle", category: "Filosofía / Tecnología", coverId: 14435859, status: "to-read", description: "Defensa de una ecología expandida de inteligencias —animales, vegetales, microbianas, computacionales y geológicas— que dilata la noción occidental de qué significa pensar y existir. El libro alterna ensayo, manifiesto y poema en prosa para reorganizar la jerarquía habitual del «yo» y de «el otro».", descriptionAi: true },
    { title: "Ilustración pirata", author: "David Graeber", category: "Antropología", coverId: 14407897, status: "read", rating: 4, description: "Las repúblicas piratas del siglo XVIII en Madagascar, lejos de ser bandas de criminales aislados, organizaron formas radicales de igualdad, asambleas en cubierta y reparto del botín que prefiguraron las ideas democráticas que después circularían por Europa. Esta investigación antropológica e histórica recompone esos experimentos políticos como un capítulo perdido de la Ilustración global.", descriptionAi: true },
    { title: "El camino a la realidad", author: "Roger Penrose", category: "Física / Matemáticas", coverId: 8427776, status: "to-read", description: "Guía exhaustiva a las matemáticas y la física teóricas que sustentan nuestra comprensión actual del universo: de los números reales y complejos a la teoría de la relatividad y la gravedad cuántica, sin saltarse las herramientas. Un tratado ambicioso, mil quinientas páginas para construir, paso a paso, una imagen coherente del mundo a la altura del estado del arte.", descriptionAi: true },
    { title: "La desaparición de los rituales", author: "Byung-Chul Han", category: "Filosofía", coverId: 13291480, description: "Diagnostica la liquidación contemporánea de los rituales y de las formas comunitarias que estructuraban la experiencia humana, sustituidos por la producción individualizada y el consumo continuo. Sin rituales no hay tiempo común, no hay duelo y no hay verdadera fiesta; queda una vida llena de eventos. Otro de los breves ensayos críticos sobre la subjetividad neoliberal del filósofo coreano-alemán.", descriptionAi: true },
    { title: "Nudge", author: "Richard H. Thaler y Cass R. Sunstein", category: "Economía conductual", coverId: 6402116, status: "read", rating: 4, description: "Argues that the way choices are framed —the «choice architecture»— powerfully shapes decisions in retirement plans, organ donation, school cafeterias and credit cards. Behavioral economics is used to design «nudges» that preserve freedom of choice while pushing people toward better outcomes. A defining text of «libertarian paternalism» as a policy approach.", descriptionAi: true },
    { title: "La revancha de los poderosos", author: "Moisés Naím", category: "Política", coverId: 14250134, status: "read", rating: 5, description: "Anatomía del ascenso global de los líderes autoritarios contemporáneos —de Putin a Trump, de Orbán a Bukele— mediante la tríada populismo, polarización y posverdad. Mostrar cómo esa combinación ataca simultáneamente a partidos, prensa, judicatura y memoria, y enumera las defensas democráticas posibles. Lectura imprescindible para entender la política de los últimos veinte años.", descriptionAi: true },
    { title: "Historia de la economía", author: "John Kenneth Galbraith", category: "Economía", coverId: 10633764, description: "Historia accesible y elegante del pensamiento económico desde Aristóteles hasta el monetarismo, atenta a las circunstancias políticas que hicieron posible cada teoría. Conecta la filosofía moral, las grandes crisis y la historia del comercio para mostrar que la economía nunca ha sido una ciencia neutral sino el resultado de batallas intelectuales por explicar la riqueza y el poder.", descriptionAi: true },
    { title: "La disciplina marcará tu destino", author: "Ryan Holiday", category: "Filosofía / Estoicismo", coverId: 13153179, description: "Segunda entrega de la tetralogía sobre las virtudes cardinales estoicas, dedicada a la disciplina como hábito que distingue a quienes logran sus metas de quienes ceden a la inercia. Mezcla biografías históricas —Eisenhower, Lou Gehrig, Marina Abramović— con principios estoicos y rutinas concretas para entrenar el autocontrol y el orden interior en una época de distracción permanente.", descriptionAi: true },
    { title: "Mirar", author: "John Berger", category: "Arte / Ensayo", coverId: 13252940, description: "Ensayos sobre el acto de mirar: los animales en los zoológicos, las fotografías de guerra, la pintura clásica, las puertas y las naturalezas muertas. Cada texto es un ejercicio breve de atención política y estética; juntos forman uno de los grandes libros de teoría visual del siglo XX.", descriptionAi: true },
    { title: "Cuentos de amor, de locura y de muerte", author: "Horacio Quiroga", category: "Cuento", coverId: 99816, status: "read", rating: 4, description: "Dieciocho relatos publicados en 1917 en los que la selva misionera, la enfermedad mental y la fragilidad del cuerpo se entretejen en un realismo sombrío y de filo. Cuentos como «El almohadón de plumas» o «La gallina degollada» se han vuelto piezas canónicas del relato breve hispanoamericano, con una crueldad seca que cuesta olvidar.", descriptionAi: true },
    { title: "Popol Vuh", author: "Anónimo", category: "Mitología", coverId: 584099, description: "Libro sagrado de los mayas k'iche': la creación del mundo, los intentos fallidos de los dioses por modelar a la humanidad, las luchas de los héroes gemelos Hunahpú e Ixbalanqué contra los señores de Xibalbá y las migraciones de los pueblos del altiplano de Guatemala. Texto cosmogónico fundamental de la literatura mesoamericana.", descriptionAi: true },
    { title: "How AI Will Change Your Life", author: "Patrick Dixon", category: "Tecnología", coverUrl: "https://profilebooks.com/wp-content/uploads/2024/07/9781805222576.jpg", description: "Concise survey of the near-term impact of artificial intelligence on work, health, education, war and creativity. Mixes technical context with concrete forecasts of how customer service, drug discovery, music composition or military decision-making will be reshaped within a decade. Written by a futurist with thirty years of corporate consulting under his belt.", descriptionAi: true },
    { title: "1984", author: "George Orwell", category: "Novela distópica", coverId: 14351142, status: "read", rating: 4, description: "Winston Smith works at the Ministry of Truth in Oceania, where his job is to rewrite history so that the Party's version is always accurate. He keeps a forbidden diary, falls into an even more forbidden affair with Julia, and is eventually broken in Room 101. The novel introduced Big Brother, doublethink, Newspeak and the boot stamping on a human face into the world's political vocabulary.", descriptionAi: true },
    { title: "En busca del tiempo perdido (Tomo 1)", author: "Marcel Proust", category: "Novela clásica", coverId: 10153245, status: "to-read", description: "Por el camino de Swann: el narrador rememora desde la adultez sus veranos infantiles en Combray —la magdalena mojada en té y la duermevela maternal— y reconstruye la pasión de Charles Swann por la cortesana Odette. La primera novela abre el ciclo y fija sus obsesiones: la memoria involuntaria, los celos, la mundanidad y la búsqueda del tiempo que aparentemente se ha perdido.", descriptionAi: true },
    { title: "En busca del tiempo perdido (Tomo 2)", author: "Marcel Proust", category: "Novela clásica", coverId: 10153245, status: "to-read", description: "A la sombra de las muchachas en flor: el narrador, ya adolescente, descubre el amor en Balbec ante un grupo de jovencitas en flor —entre ellas Albertine— mientras entra en los salones literarios de París. La novela describe la transformación de la sensibilidad estética y amorosa con una prosa larguísima, demorada y siempre dispuesta al hallazgo.", descriptionAi: true },
    { title: "En busca del tiempo perdido (Tomo 3)", author: "Marcel Proust", category: "Novela clásica", coverId: 10153245, status: "to-read", description: "El mundo de Guermantes: el narrador es admitido en la alta sociedad del faubourg Saint-Germain, frecuenta el círculo de la duquesa de Guermantes y observa, con ojo despiadado, los rituales del mundo aristocrático. El caso Dreyfus sacude París mientras la novela disecciona la mundanidad como un arte casi militar.", descriptionAi: true },
    { title: "La crisis de la narración", author: "Byung-Chul Han", category: "Filosofía", coverId: 14576033, description: "Diagnóstico del ruido informativo del presente como una crisis de las narraciones que dan sentido a la vida. Lo que llamamos información no es contar: son fragmentos sin tiempo, sin demora y sin escucha. Propone recuperar el contar como acto comunitario, lento y poético, capaz de devolverle al lenguaje su capacidad de estructurar la experiencia.", descriptionAi: true },
    { title: "Zen en el arte del tiro con arco", author: "Eugen Herrigel", category: "Filosofía oriental", coverId: 3346542, status: "to-read", description: "Crónica de seis años de aprendizaje del kyudo en Japón como vía de iniciación al zen. La práctica disuelve la voluntad del tirador hasta que la flecha se dispara sola; el ego deja de interponerse entre el arquero y el blanco. Un libro breve, profundamente ético, que abrió a muchas lectoras occidentales el camino del zen contemporáneo.", descriptionAi: true },
    { title: "Hijos de la Bruma I: El Imperio Final", author: "Brandon Sanderson", category: "Fantasía", coverId: 14658160, status: "read", rating: 5, description: "Apertura de la trilogía Mistborn. En un mundo cubierto de ceniza y vigilado por la Inquisición, una banda de ladrones encabezada por Kelsier planea derrocar al Señor Tenebroso, un dios-emperador inmortal que ha gobernado durante mil años. La joven huérfana Vin descubre, en mitad del plan, que es una nacida de la bruma con poderes alománticos. Fantasía épica con sistema mágico claro y trama de heist.", descriptionAi: true },
    { title: "Hijos de la Bruma II: El Pozo de la Ascensión", author: "Brandon Sanderson", category: "Fantasía", coverId: 14658341, status: "read", rating: 5, description: "Segundo volumen de la trilogía Mistborn. Tras la caída del Señor Tenebroso, Vin y Elend deben sostener el frágil reino que crearon mientras una niebla mortal se extiende, ejércitos rivales sitian la capital y profecías antiguas reclaman a un Héroe de las Eras. La trama gana en política, intriga y revelaciones sobre la verdadera naturaleza del mundo.", descriptionAi: true },
    { title: "Hijos de la Bruma III: El Héroe de las Eras", author: "Brandon Sanderson", category: "Fantasía", coverId: 14658094, status: "read", rating: 5, description: "Cierre de la trilogía Mistborn. El Pozo de la Ascensión ha liberado a un poder antiguo que amenaza con destruir el mundo: la ceniza cubre el cielo, las plantas mueren y solo Vin descubre, página a página, el verdadero significado del Héroe de las Eras. Un final con todas las piezas del puzzle encajando con la habilidad meticulosa de la fantasía épica contemporánea.", descriptionAi: true },
    { title: "Mito y significado", author: "Claude Lévi-Strauss", category: "Antropología", coverId: 8695485, status: "to-read", description: "Cinco conferencias radiofónicas en las que el antropólogo francés explica con claridad sus tesis sobre el mito como pensamiento estructurado, la oposición entre ciencia y mito y el papel del estructuralismo. Una excelente puerta de entrada a una obra que en otros formatos puede resultar más exigente.", descriptionAi: true },
    { title: "Thinking In Systems: A Primer", author: "Donella H. Meadows", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1390169859l/3828902.jpg", status: "read", rating: 5, description: "Posthumous introduction to systems thinking by one of the field's pioneers. Stocks, flows, feedback loops, delays, and the famous «system traps» (drift to low performance, escalation, success to the successful) are explained with the patience of a teacher who actually wants you to use the tools. Indispensable for anyone trying to change a complex organization or a complex policy.", descriptionAi: true, owned: false },
    { title: "Astrophysics for People in a Hurry", author: "Neil deGrasse Tyson", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1562761669l/32191710.jpg", status: "read", rating: 4, description: "Modern cosmology distilled into a short, brisk tour: the Big Bang, dark matter, dark energy, the cosmic microwave background, exoplanets and the chemistry of the stars. Written for readers with no science background, with a tone that is at once humble before the universe and patient with the reader.", descriptionAi: true, owned: false },
    { title: "One Day, Everyone Will Have Always Been Against This", author: "Omar El Akkad", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1764097849l/213870084.jpg", status: "read", rating: 5, description: "Sharp essay on the Western response to the war in Gaza and on how official narratives are rewritten once atrocities can no longer be denied. Mixing personal memoir, history of the literary novel and political analysis, it offers a meditation on complicity, on language, and on what it costs to speak clearly while events are still unfolding.", descriptionAi: true, owned: false },
    { title: "Switch: How to Change Things When Change Is Hard", author: "Chip Heath", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1422839688l/6570502.jpg", status: "read", rating: 4, description: "Practical framework for personal and organizational change built on a single metaphor: the rational rider on top of an emotional elephant on a path. To make change stick you have to direct the rider, motivate the elephant and shape the path. Each principle is illustrated with case studies from medicine, marketing and social policy.", descriptionAi: true, owned: false },
    { title: "La conquista de la felicidad", author: "Bertrand Russell", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1327274673l/2604877.jpg", status: "read", rating: 5, description: "Ensayo claro y empírico de 1930 que diagnostica las causas modernas de la infelicidad —celos, fatiga, miedo a la opinión pública, persecución del éxito— y propone, en contrapartida, condiciones racionales para vivir bien. Mezcla observación social, sentido común y una prosa luminosa que envejece sorprendentemente bien.", descriptionAi: true, owned: false },
    { title: "Ownership: Reinventing Companies, Capitalism, and Who Owns What", author: "Corey Rosen", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1642987531l/59891628.jpg", status: "read", rating: 4, description: "Argues that broad-based employee share schemes are a proven and underused way to make capitalism work for workers, strengthen firms and reduce inequality at the same time. Surveys decades of research, profiles successful ESOPs and proposes specific policy and tax changes to scale them up. A constructive manifesto from inside the corporate-finance world.", descriptionAi: true, owned: false },
    { title: "The Price is Wrong: Why Capitalism Won't Save the Planet", author: "Brett Christophers", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1686005184l/165937650.jpg", status: "read", rating: 4, description: "Cheap renewables, even when they outcompete fossil fuels on a per-megawatt basis, are not being deployed at the scale and speed required by the climate crisis because private investors demand returns that the technology cannot provide. The argument is that public investment, public ownership and public planning are unavoidable if decarbonization is to happen on time.", descriptionAi: true, owned: false },
    { title: "How the World Made the West: A 4,000 Year History", author: "Josephine Quinn", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1717437075l/203956660.jpg", status: "read", rating: 4, description: "Dismantles the standard story of a singular Western civilization that runs from Athens through Rome to today's Atlantic powers. Four millennia of cultural exchange across the Mediterranean and beyond are reconstructed to show that what we call «the West» is a recent rebranding of a long history of borrowing, mixing and forgetting.", descriptionAi: true, owned: false },
    { title: "Dune Messiah", author: "Frank Herbert", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1577043824l/44492285.jpg", status: "read", rating: 4, description: "Sequel to Dune. Twelve years after the jihad, Paul Atreides is Emperor of the universe and his Fremen disciples have killed billions in his name. Trapped in his own prescient vision and surrounded by a conspiracy that includes the Bene Gesserit, the Tleilaxu and the Spacing Guild, he must decide what to sacrifice to escape the religion he became. Shorter and darker than the original.", descriptionAi: true, owned: false },
    { title: "The Fabric of Civilization: How Textiles Made the World", author: "Virginia Postrel", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1601345373l/52686790.jpg", status: "read", rating: 5, description: "Argues that fiber, thread, dye and cloth are not background details of history but engines of it. Each chapter follows a different aspect of textiles —the domestication of silkworms, the chemistry of indigo, the math behind weaving, the politics of fashion— and shows how textiles drove global trade, technological innovation and inequality.", descriptionAi: true, owned: false },
    { title: "The Poppy War", author: "R.F. Kuang", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1515691735l/35068705.jpg", status: "read", rating: 3, description: "Debut grimdark fantasy. War-orphan Rin tests into an elite military academy in a country modeled on early-twentieth-century China, only to discover shamanic powers as a brutal imperial war erupts. Inspired by the second Sino-Japanese war and especially by the Rape of Nanjing, the novel makes no concessions about what war does to those who survive it.", descriptionAi: true, owned: false },
    { title: "Siddhartha", author: "Hermann Hesse", category: "Mitología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1629378189l/52036.jpg", status: "read", rating: 5, description: "A young Brahmin in ancient India leaves his comfortable life to seek enlightenment. He passes through ascetic discipline, lust, wealth, fatherhood and despair before discovering wisdom by the side of a river. A short, lyrical novel that synthesizes European Bildungsroman with Buddhist and Hindu thought and became a touchstone for the twentieth-century search for inner life.", descriptionAi: true, owned: false },
    { title: "El Cerebro Dividido: Maneras de prestar atención y construir el mundo Edition)", author: "Iain McGilchrist", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1721732753l/216672197.jpg", status: "read", rating: 5, description: "Los dos hemisferios cerebrales atienden el mundo de maneras complementarias: uno totalmente disponible para lo nuevo, lo lateral y lo encarnado; el otro especializado en lo conocido, lo abstracto y lo controlado. La dominancia progresiva del hemisferio izquierdo configura buena parte de la cultura occidental moderna, su exactitud y su empobrecimiento sensorial. Un tratado interdisciplinario que cruza neurociencia, filosofía e historia del arte.", descriptionAi: true, owned: false },
    { title: "A Beautifully Foolish Endeavor", author: "Hank Green", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1576697804l/49003616.jpg", status: "read", rating: 5, description: "Sequel to An Absolutely Remarkable Thing. With April May presumed dead, her friends and the alien Carls' game return; the world has changed and the dream sequences become a battleground. The novel ramps up the satire of online fame, identity politics and the temptations of being a Voice for a generation.", descriptionAi: true, owned: false },
    { title: "An Absolutely Remarkable Thing", author: "Hank Green", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1520026196l/24233708.jpg", status: "read", rating: 5, description: "Twenty-three-year-old April May stumbles upon a giant alien statue in midtown Manhattan, posts a video and wakes up famous. Soon identical Carls appear in cities around the world and humanity has to decide what to do with them while April rides the cyclone of online attention. A novel about influence, friendship and what it costs to become a brand.", descriptionAi: true, owned: false },
    { title: "Dune", author: "Frank Herbert", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1555447414l/44767458.jpg", status: "read", rating: 4, description: "Set on the desert planet Arrakis, the story of the boy Paul Atreides, heir to a noble family tasked with ruling an inhospitable world where the only thing of value is the «spice» melange. Betrayal, prescience, ecology and religion fuse into a sweeping science-fiction epic that invented modern world-building.", descriptionAi: true, owned: false },
    { title: "Super Agers: An Evidence-Based Approach to Longevity", author: "Eric Topol", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1730640080l/220160337.jpg", status: "read", rating: 4, description: "Synthesizes the data on what actually extends healthy lifespan: diet, exercise, sleep, social ties, immune resilience and the new tools of AI-assisted medicine for personalizing prevention. Written by a cardiologist who has spent a career questioning unproven medical fads, it refuses both panic and snake oil.", descriptionAi: true, owned: false },
    { title: "Central America's Forgotten History: Revolution, Violence, and the Roots of Migration", author: "Aviva Chomsky", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1601938710l/54815903.jpg", status: "read", description: "Traces five hundred years of U.S. intervention in Central America —from filibusters to banana republics to Cold War-era counterinsurgency— to explain the contemporary crises that drive Salvadoran, Guatemalan and Honduran migration north. A counter-history that puts displacement at the center of any honest immigration debate.", descriptionAi: true, owned: false },
    { title: "Other People's Money: The Real Business of Finance", author: "John Kay", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1712505194l/24612279.jpg", status: "read", rating: 4, description: "Modern finance, the argument goes, has stopped serving the real economy and instead devotes itself to trading other people's money among traders. Surveys what financial intermediaries are supposed to do —payments, capital allocation, insurance, savings management— and shows how the industry has drifted away from each of these functions while extracting enormous rents.", descriptionAi: true, owned: false },
    { title: "Finance and the Good Society", author: "Robert J. Shiller", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1348262894l/13384575.jpg", status: "read", rating: 4, description: "Defends finance as a powerful social technology and proposes ways it can be redesigned to address inequality and human well-being rather than merely amplify private wealth. Topics include insurance, mortgages, philanthropy, social impact bonds and the political legitimacy of financial innovation. A constructive answer to the post-2008 mood.", descriptionAi: true, owned: false },
    { title: "We Are What We Pretend To Be: The First and Last Works", author: "Kurt Vonnegut Jr.", category: "Cuentos", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1340327859l/15716409.jpg", status: "read", rating: 4, description: "A posthumous volume pairing an unpublished first novel, Basic Training, with the unfinished If God Were Alive Today, bookending a career obsessed with kindness, war, absurdity and the limits of decency. The result is less a tidy collection than an honest framing of a writer at his beginning and his end.", descriptionAi: true, owned: false },
    { title: "Obliquity: Why Our Goals Are Best Achieved Indirectly", author: "John Kay", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1347801679l/7888001.jpg", status: "read", rating: 4, description: "Through case studies from business strategy, economics, war and personal happiness, the book argues that complex goals are most reliably reached by indirect routes; direct optimization usually defeats itself. The lesson for managers, policy makers and individuals is to plan for adaptation rather than for control.", descriptionAi: true, owned: false },
    { title: "Los ensayos (según la edición de 1595 de Marie de Gournay)", author: "Michel de Montaigne", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1411400457l/3232646.jpg", status: "read", rating: 5, description: "Reedición integral de los Essais basada en la última versión póstuma que preparó la «hija de alianza» del ensayista. Es la edición canónica del corpus, con los añadidos y reformulaciones que dejan ver la última cabeza del autor. Lectura obligada para quien quiera entender el texto en su forma definitiva.", descriptionAi: true, owned: false },
    { title: "Farenheit 451", author: "Ray Bradbury", category: "Novela clásica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1608059811l/56302573.jpg", status: "read", rating: 4, description: "En una sociedad futura donde los libros están prohibidos, el bombero Guy Montag tiene como oficio quemarlos hasta que, una mañana, se queda con uno. La distopía pasa del entretenimiento televisivo y la prisa permanente al silencio de los libros escondidos en el bosque. Un clásico breve sobre la lectura, la censura y la memoria.", descriptionAi: true, owned: false },
    { title: "The Wise Man's Fear", author: "Patrick Rothfuss", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1452624392l/1215032.jpg", status: "read", rating: 5, description: "Second volume of the Kingkiller Chronicle. Kvothe continues his story for the Chronicler: more adventures at the University in Imre, an embassy to the court of the Maer Alveron, a hunt for bandits in the forest of Eld, an erotic education with Felurian among the Fae and a martial education with the Adem. A long, immersive middle book.", descriptionAi: true, owned: false },
    { title: "Culture: The surprising connections and influences between civilisations.", author: "Martin Puchner", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1675867915l/106209313.jpg", status: "read", rating: 5, description: "Human culture is fundamental remix. Through fifteen historical episodes —from Nefertiti's bust to Hokusai's prints, the Book of the Dead to the printing of the Don Quixote— the book shows how supposedly pure civilizations have always been hybrids and how their reach depends on transmission, translation and theft.", descriptionAi: true, owned: false },
    { title: "Race, Monogamy, and Other Lies They Told You: Busting Myths about Human Nature", author: "Agustín Fuentes", category: "Antropología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1342036184l/12933643.jpg", status: "read", rating: 3, description: "Uses biology, archaeology and the social sciences to dismantle three popular myths: that race is biological, that monogamy is natural and that aggression is encoded in human genes. Each chapter walks through the evidence and shows how cultural narratives masquerade as nature when convenient.", descriptionAi: true, owned: false },
    { title: "Birds, Sex and Beauty: The Extraordinary Implications of Charles Darwin's Strangest Idea", author: "Matt Ridley", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1739375971l/216269105.jpg", status: "read", rating: 4, description: "Rehabilitates the most controversial idea in The Descent of Man —that female birds choose mates for sheer beauty— and traces its consequences for evolutionary theory and the origins of art. Mixes bird-watching, philosophy and history of science with characteristic relish.", descriptionAi: true, owned: false },
    { title: "The Logic of Scientific Discovery", author: "Karl Popper", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1405192590l/61550.jpg", status: "read", rating: 4, description: "Foundational work of twentieth-century philosophy of science. Replaces verification with falsification as the demarcation criterion for science: a theory is scientific to the extent that it forbids events, and corroborated only as long as no observation has refuted it. Dense but enormously influential, especially for working scientists who feel that statistical induction never quite tells the whole story.", descriptionAi: true, owned: false },
    { title: "Your Life Is Manufactured: How We Make Things, Why It Matters and How We Can Do It Better", author: "Tim Minshall", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1730911521l/221193153.jpg", status: "read", rating: 4, description: "A walk through the global manufacturing systems behind everyday objects: the smartphone, the cup of coffee, the bicycle, the t-shirt. Each chapter explains the supply chains, the engineering disciplines and the geopolitics involved, then argues that understanding how things are made is essential to building a sustainable future.", descriptionAi: true, owned: false },
    { title: "Life, the Universe and Everything", author: "Douglas Adams", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1333577589l/8694.jpg", status: "read", rating: 4, description: "Third installment of the Hitchhiker series. Arthur Dent, Ford Prefect and Slartibartfast must save the universe from the planet Krikkit, whose inhabitants want to obliterate everything that is not Krikkit. Cricket, time travel, talking mattresses on Squornshellous Zeta and the answer to the meaning of life are again at stake.", descriptionAi: true, owned: false },
    { title: "Mother Night", author: "Kurt Vonnegut Jr.", category: "Novela clásica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1344621657l/9592.jpg", status: "read", rating: 5, description: "Howard W. Campbell Jr., an American playwright who was the Voice of Nazi Propaganda during the Second World War —and a simultaneous Allied spy embedding coded messages in his broadcasts— awaits trial in an Israeli jail and writes his confession. A short, brilliant novel about the impossibility of standing outside the masks one chooses to wear.", descriptionAi: true, owned: false },
    { title: "How We Learn: Why Brains Learn Better Than Any Machine . . . for Now", author: "Stanislas Dehaene", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1562573168l/46064083.jpg", status: "read", rating: 4, description: "Cognitive neuroscience meets pedagogy. Four pillars of learning —attention, active engagement, error feedback and consolidation— are exposed in detail, with implications for school classrooms, parenting and even the design of artificial intelligence systems. A rigorous bridge between lab and practice.", descriptionAi: true, owned: false },
    { title: "Education for Critical Consciousness (Impacts)", author: "Paulo Freire", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1388657657l/169949.jpg", status: "read", rating: 4, description: "Twin essays that lay out the political pedagogy of critical consciousness: education as practice of freedom rather than reproduction of the existing social order. Drawing on adult-literacy campaigns in Brazil, the text proposes a dialogic method that treats the learner as a co-investigator of the world. A founding document of liberation pedagogy.", descriptionAi: true, owned: false },
    { title: "The Restaurant at the End of the Universe", author: "Douglas Adams", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1521213881l/8695.jpg", status: "read", rating: 5, description: "Second installment of the Hitchhiker series. After the Heart of Gold survives the previous adventures, Arthur, Ford, Zaphod, Trillian and Marvin pursue dinner at the Restaurant at the End of the Universe —the only restaurant that watches the End of Everything between courses— and uncover the secret of who really runs the universe.", descriptionAi: true, owned: false },
    { title: "Wool", author: "Hugh Howey", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1327889474l/12287209.jpg", status: "read", rating: 4, description: "Self-published debut that became a cult phenomenon. In a post-apocalyptic future, what remains of humanity lives inside an immense underground silo whose only sin is to wish to go outside —a wish that is punished with «cleaning», an exile to the toxic surface where the condemned scrub the camera lenses before they die. The plot expands the small original story into a sweeping resistance saga.", descriptionAi: true, owned: false },
    { title: "Chaos Kings: How Wall Street Traders Make Billions in the New Age of Crisis", author: "Scott Patterson", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1686093170l/62918551.jpg", status: "read", rating: 4, description: "Profiles the «crisis hunters» —Nassim Taleb, Mark Spitznagel, Universa— who built funds designed to win exactly when markets break, and traces their influence on twenty-first-century finance. Reads as an intellectual thriller about how a small group of contrarians took advantage of every market crash since 1987.", descriptionAi: true, owned: false },
    { title: "The Social Brain: The Psychology of Successful Groups", author: "Tracey Camilleri", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1677852282l/60438875.jpg", status: "read", rating: 3, description: "Combines evolutionary psychology with management research to identify what makes small groups thrive and why almost no organization tolerates the size —around 150 active relationships— that the human brain prefers. Suggests practical ways to structure teams for connection rather than scale.", descriptionAi: true, owned: false },
    { title: "Doctors by Nature: How Ants, Apes, and Other Animals Heal Themselves", author: "Jaap de Roode", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1726572153l/218059153.jpg", status: "read", rating: 4, description: "Catalog of the surprising medical behaviors observed in nonhuman animals: monkeys eating clay, bees lining nests with antimicrobial resin, sparrows weaving cigarette butts into their nests, dolphins rubbing on antibacterial corals. The argument is that medicine predates humanity and that we have a lot to learn by watching.", descriptionAi: true, owned: false },
    { title: "Everything Is Tuberculosis: The History and Persistence of Our Deadliest Infection", author: "John  Green", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1729825992l/220341389.jpg", status: "read", rating: 5, description: "A history of tuberculosis from prehistoric times to today's drug-resistant strains, with a special focus on the lived experience of patients in sub-Saharan Africa. The book mixes science, advocacy and personal memoir to make a passionate case that we already have the tools to end the deadliest infectious disease in human history.", descriptionAi: true, owned: false },
    { title: "The Illusion of Choice: 16 ½ psychological biases that influence what we buy", author: "Richard Shotton", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1669667548l/60784553.jpg", status: "read", rating: 3, description: "Walks through sixteen and a half cognitive biases that shape consumer decisions —the anchoring effect, the labour illusion, the keenness for round numbers, social proof— and shows marketers how to put them to work ethically. Studded with hundreds of small experiments and brand stories.", descriptionAi: true, owned: false },
    { title: "From Chaos to Stability: How the Brain Invents Our Conscious Worlds (The New Neuroscience)", author: "Israel Rosenfield", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1719010231l/213584333.jpg", status: "read", rating: 4, description: "Consciousness is a continuous construction, an act of organizing perception against chaos that draws on memory, body and language. The argument moves from clinical cases of disordered consciousness to philosophical reflection on what it means to be a self, in a tradition that runs through William James and Oliver Sacks.", descriptionAi: true, owned: false },
    { title: "Foundation and Earth", author: "Isaac Asimov", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1389759320l/29582.jpg", status: "read", rating: 5, description: "Golan Trevize, Janov Pelorat, Bliss go looking for earth.", owned: false },
    { title: "Foundation's Edge", author: "Isaac Asimov", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1442311409l/76683.jpg", status: "read", rating: 5, description: "After the defeat of the Mule by the Second Foundation, Terminus enjoys a period of prosperity and stability which is publicly attributed to the Seldon Plan, but which some feel is the work of the Second Foundation.  A search is begun to determine if the Second Foundation still exists.  Meanwhile, the Second Foundation finds that there is evidence of an independent force acting against the Mule to protect the Seldon Plan.  A search is launched to determine what this force is and if it is a threat.  The end result is a search for Earth (Terminus being the last planet settled by the galactic empire and Earth being the metaphoric opposite of first human planet settled).  A final three way confrontation results in a fateful decision and an open question.", owned: false },
    { title: "The Wayfinders: Why Ancient Wisdom Matters in the Modern World (CBC Massey Lecture)", author: "Wade Davis", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1395458406l/6373455.jpg", status: "read", rating: 4, description: "\"Many of us are alarmed by the accelerating rates of extinction of plants and animals. But how many of us know that human cultures are going extinct at an even more shocking rate? While biologists estimate that 18 percent of mammals and 11 percent of birds are threatened, and botanists anticipate the loss of 8 percent of flora, anthropologists predict that fully 50 percent of the 7,000 languages spoken around the world today will disappear within our lifetimes. And languages are merely the canaries in the coal mine: what of the knowledge, stories, songs, and ways of seeing encoded in these voices?\" \"In The Wayfinders, Wade Davis offers a gripping and enlightening account of this urgent crisis. He leads us on a fascinating tour through a handful of indigenous cultures, describing the worldviews they represent and reminding us of the encroaching danger to humankind's survival should they vanish.\"--Jacket.", owned: false },
    { title: "Mindwandering: How Your Constant Mental Drift Can Improve Your Mood and Boost Your Creativity", author: "Moshe Bar", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1721438129l/58293283.jpg", status: "read", rating: 4, description: "Cognitive scientist Moshe Bar reframes daydreaming as essential to creativity, problem-solving and mood regulation rather than as a productivity bug to be fixed.", owned: false },
    { title: "Belonging: The Science of Creating Connection and Bridging Divides", author: "Geoffrey L. Cohen", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1656129594l/60165404.jpg", status: "read", rating: 4, description: "Stanford psychologist Geoffrey Cohen synthesizes decades of research on belonging — in schools, workplaces and politics — and offers concrete interventions that reduce loneliness and prejudice.", owned: false },
    { title: "The Epic of Gilgamesh", author: "Anonymous", category: "Novela clásica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1388287904l/19351.jpg", status: "read", rating: 5, description: "A great king, strong as the stars in Heaven. Enkidu, a wild and mighty hero, is created by the gods to challenge the arrogant King Gilgamesh. But instead of killing each other, the two become friends. Travelling together to the Cedar Forest, they fight and slay the evil monster Humbaba. But when Enkidu is killed, his death haunts and breaks the mighty Gilgamesh. Terrified of mortality, he resolves to find the secret of eternal life.", owned: false },
    { title: "Why Zebras Don&apos;t Get Ulcers", author: "Robert M. Sapolsky", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1441955030l/327.jpg", status: "read", rating: 5, description: "Robert Sapolsky's classic explains why chronic psychological stress damages bodies built for short bursts of physical threat, and what we know about preventing the diseases that follow.", owned: false },
    { title: "The Education of a British-Protected Child: Essays", author: "Chinua Achebe", category: "Ensayo", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1436379772l/6406840.jpg", status: "read", rating: 5, description: "From the celebrated author of Things Fall Apart and winner of the Man Booker International Prize comes a new collection of autobiographical essays--his first new book in more than twenty years.Chinua Achebe's characteristically measured and nuanced voice is everywhere present in these seventeen beautifully written pieces. In a preface, he discusses his historic visit to his Nigerian homeland on the occasion of the fiftieth anniversary of the publication of Things Fall Apart, the story of his tragic car accident nearly twenty years ago, and the potent symbolism of President Obama's election. In \"The Education of a British-Protected Child,\" Achebe gives us a vivid portrait of growing up in colonial Nigeria and inhabiting its \"middle ground,\" recalling both his happy memories of reading novels in secondary school and the harsher truths of colonial rule. In \"Spelling Our Proper Name,\" Achebe considers the African-American diaspora, meeting and reading Langston Hughes and James Baldwin, and learning what it means not to know \"from whence he came.\" The complex politics and history of Africa figure in \"What Is Nigeria to Me?,\" \"Africa's Tarnished Name,\" and \"Politics and Politicians of La", owned: false },
    { title: "Fluke: Chance, Chaos, and Why Everything We Do Matters", author: "Brian Klaas", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1686591877l/177058906.jpg", status: "read", rating: 5, description: "*PUBLISHER'S SUMMARY*\n\nThis “captivating illustration of the follies of trying to model and forecast the unpredictable world” (Financial Times) is both “empowering” (The New Statesman, UK) and “compelling” (New Scientist) as it challenges our most fundamental assumptions—by social scientist and Atlantic writer Brian Klaas.\nIf you could rewind your life to the very beginning and then press play, would everything turn out the same? Or could making an accidental phone call or missing an exit off the highway change not just your life, but history itself?\n\nIn Fluke, myth-shattering social scientist Brian Klaas takes a deep-dive into the phenomenon of random chance and the chaos it can sow, taking aim at most people’s neat and tidy version of reality. The book’s argument is that we willfully ignore a bewildering truth: but for a few small changes, our lives—and our societies—could be radically different.\n\nOffering an entirely new lens, Fluke explores how our world really works, driven by strange interactions and apparently random events. How did one couple’s vacation cause 100,000 people to die? Does our decision to hit the snooze button in the morning radically alter the trajectory of o", owned: false },
    { title: "The People vs. Democracy: Why Our Freedom Is in Danger and How to Save It", author: "Yascha Mounk", category: "Política", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1514781968l/36738610.jpg", status: "read", rating: 5, description: "From India to Turkey, from Poland to the United States, authoritarian populists have seized power. Two core components of liberal democracy--individual rights and the popular will--are at war, putting democracy itself at risk. In plain language, Yascha Mounk describes how we got here, where we need to go, and why there is little time left to waste.--", owned: false },
    { title: "The Hidden World: How Insects Sustain Life on Earth Today and Will Shape Our Lives Tomorrow", author: "George McGavin", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1681584006l/121141757.jpg", status: "read", rating: 4, description: "Entomologist George McGavin makes the case for insects as the planet's silent infrastructure — pollinators, recyclers, food — and warns about the consequences of their global decline.", owned: false },
    { title: "Poverty for Profit: How Corporations Get Rich off America’s Poor", author: "Anne    Kim", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1709762400l/195473593.jpg", status: "read", rating: 5, description: "Anne Kim documents the industries — payday loans, prison telecoms, dialysis chains, charter management — that extract wealth from the U.S. poor while being subsidized by public dollars.", owned: false },
    { title: "Win Every Argument: The Art of Debating, Persuading, and Public Speaking", author: "Mehdi Hasan", category: "Autoayuda", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1648416732l/60505565.jpg", status: "read", rating: 5, description: "MSNBC anchor Mehdi Hasan distills lessons from competitive debate and broadcast interviews into a practical guide for arguing more effectively in public and private life.", owned: false },
    { title: "Anger and Forgiveness: Resentment, Generosity, Justice", author: "Martha C. Nussbaum", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1450647202l/26721206.jpg", status: "read", rating: 4, description: "Philosopher Martha Nussbaum argues that anger is almost always either incoherent or normatively wrong, and that constructive politics requires turning toward generosity and forward-looking justice instead.", owned: false },
    { title: "The Vital Question: Energy, Evolution, and the Origins of Complex Life", author: "Nick Lane", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1444265552l/26530386.jpg", status: "read", rating: 5, description: "A biochemist, building on the pillars of evolutionary theory and drawing on cutting-edge research into the link between energy and genes, argues that the evolution of multicellular life was the result of a single event.", owned: false },
    { title: "Los cuatro acuerdos: Una guía practica para la libertad personal", author: "Miguel Ruiz", category: "Autoayuda", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1348256973l/6600.jpg", status: "read", rating: 5, description: "Cuatro principios extraídos de la sabiduría tolteca: ser impecable con la palabra, no tomarse nada personal, no hacer suposiciones y hacer siempre lo mejor. Cada uno se propone como un acuerdo voluntario con uno mismo capaz de liberar a la persona de los pactos automáticos que aprendió de niña. Un manual breve de psicología práctica con resonancias espirituales.", descriptionAi: true, owned: false },
    { title: "The Earth Transformed: An Untold History", author: "Peter Frankopan", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1677838656l/61965394.jpg", status: "read", rating: 4, description: "Historian Peter Frankopan retells global history through climate and environmental change, tracing how shifts in rainfall, temperature and ecology shaped civilizations from Mesopotamia to today.", owned: false },
    { title: "The Serviceberry: Abundance and Reciprocity in the Natural World", author: "Robin Wall Kimmerer", category: "Biología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1760641870l/208840291.jpg", status: "read", rating: 4, description: "From the #1 New York Times bestselling author of Braiding Sweetgrass, a bold and inspiring vision for how to orient our lives around gratitude, reciprocity, and community, based on the lessons of the natural world.\n\nAs Indigenous scientist and author of Braiding Sweetgrass Robin Wall Kimmerer harvests serviceberries alongside the birds, she considers the ethic of reciprocity that lies at the heart of the gift economy. How, she asks, can we learn from Indigenous wisdom and the plant world to reimagine what we value most? Our economy is rooted in scarcity, competition, and the hoarding of resources, and we have surrendered our values to a system that actively harms what we love. Meanwhile, the serviceberry’s relationship with the natural world is an embodiment of reciprocity, interconnectedness, and gratitude. The tree distributes its wealth—its abundance of sweet, juicy berries—to meet the needs of its natural community. And this distribution ensures its own survival. As Kimmerer explains, “Serviceberries show us another model, one based upon reciprocity, where wealth comes from the quality of your relationships, not from the illusion of self-sufficiency.”\n\nAs Elizabeth Gilbert writ", owned: false },
    { title: "Second Foundation", author: "Isaac Asimov", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1661015922l/29580.jpg", status: "read", rating: 5, description: "After years of struggle, the Foundation lay in ruins -- destroyed by the mutant mind power of the Mule. But it was rumored that there was a Second Foundation hidden somewhere at the end of the Galaxy, established to preserve the knowledge of mankind through the long centuries of barbarism. The Mule had failed to find it the first time -- but now he was certain he knew where it lay.\n\nThe fate of the Foundation rests on young Arkady Darell, only fourteen years old and burdened with a terrible secret. As its scientists girded for a final showdown with the Mule, the survivors of the First Foundation began their desperate search. They too wanted the Second Foundation destroyed... before it destroyed them.", owned: false },
    { title: "POPOL VUH: español", author: "MAYAS QUICHES", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1573412274l/48747828.jpg", status: "read", rating: 4, description: "Edición en español del libro sagrado de los mayas k'iche': la creación del mundo, los intentos fallidos de los dioses por modelar a la humanidad, las hazañas de los héroes gemelos Hunahpú e Ixbalanqué contra los señores de Xibalbá y las migraciones de los pueblos del altiplano guatemalteco. Texto cosmogónico fundamental de la literatura mesoamericana.", descriptionAi: true, owned: false },
    { title: "A Prayer for the Crown-Shy", author: "Becky Chambers", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1733422002l/40864030.jpg", status: "read", rating: 5, description: "Sequel to A Psalm for the Wild-Built. Tea monk Dex and the robot Mosscap continue their slow road trip across Panga, asking what people need now that the planet has rewilded.", owned: false },
    { title: "El señor presidente", author: "Miguel Ángel Asturias", category: "Política", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1376424137l/327281.jpg", status: "read", rating: 4, description: "\"...La larga gestación de El Señor Presidente, por encima de su condición de novela-denuncia, trasciende los ecos surgidos de la memoria colectiva a partir de la resonancia natural de las palabras y las fantasías oníricas asimiladas de manera gradual por la realidad de la vida...\"", owned: false },
    { title: "Foundation and Empire", author: "Isaac Asimov", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1391454612l/29581.jpg", status: "read", rating: 5, description: "Led by its founding father, the great psychohistorian Hari Seldon, and taking advantage of its superior science and technology, the Foundation has survived the greed and barbarism of its neighboring warrior-planets. Yet now it must face the Empire still the mightiest force in the Galaxy even in its death throes. When an ambitious general determined to restore the Empire's glory turns the vast Imperial fleet toward the Foundation, the only hope for the small planet of scholars and scientists lies in the prophecies of Hari Seldon.", owned: false },
    { title: "Foundation", author: "Isaac Asimov", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1417900846l/29579.jpg", status: "read", description: "After years of struggle, the Foundation lay in ruins -- destroyed by the mutant mind power of the Mule. But it was rumored that there was a Second Foundation hidden somewhere at the end of the Galaxy, established to preserve the knowledge of mankind through the long centuries of barbarism. The Mule had failed to find it the first time -- but now he was certain he knew where it lay.\n\nThe fate of the Foundation rests on young Arkady Darell, only fourteen years old and burdened with a terrible secret. As its scientists girded for a final showdown with the Mule, the survivors of the First Foundation began their desperate search. They too wanted the Second Foundation destroyed... before it destroyed them.", owned: false },
    { title: "Migrants: The Story of Us All", author: "Sam Miller", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1668096353l/63270981.jpg", status: "read", rating: 5, description: "Sam Miller offers a sweeping global history of human migration that argues moving — not staying put — is the default human condition; he places contemporary migrations in deep time.", owned: false },
    { title: "An Immense World: How Animal Senses Reveal the Hidden Realms Around Us", author: "Ed Yong", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1652105350l/59575939.jpg", status: "read", rating: 5, description: "Pulitzer-winning science writer Ed Yong takes the reader inside the umwelten of dozens of species, showing how electric, magnetic, infrared and ultrasonic perception reshape what we mean by «the world».", owned: false },
    { title: "Las venas abiertas de América Latina (Edición conmemorativa)", author: "Eduardo Galeano", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1687936571l/123749149.jpg", status: "read", rating: 4, description: "Crónica feroz y poética de cinco siglos de extracción colonial y neocolonial en América Latina, desde el oro de Potosí hasta las dictaduras del siglo XX. Combina datos económicos, retratos de personajes y prosa de fuego para denunciar el saqueo continental. Una obra militante que sigue siendo lectura iniciática de la izquierda latinoamericana.", descriptionAi: true, owned: false },
    { title: "The Ultimate Hidden Truth of the World", author: "David Graeber", category: "Política", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1706474365l/205363978.jpg", status: "read", rating: 5, description: "Posthumous essay collection from David Graeber, edited by Nika Dubrovsky and Rebecca Solnit, gathering his most-cited essays on bureaucracy, debt, value and play.", owned: false },
    { title: "Pedro Páramo", author: "Juan Rulfo", category: "Novela clásica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1697799709l/136160907.jpg", status: "read", rating: 4, description: "Dentro de su brevedad -determinada por el rigor y la concentración expresiva-, *Pedro Páramo* sintetiza la mayor parte de los temas que han interesado -y afligido- siempre a los mexicanos: ese misterio nacional que el talento de Juan Rulfo ha sabido condensar por medio rural del sur de Jalisco -de Comala en particular, región inscrita ya en la mitología literia universal-; sus personajes muertos que \"evasivos, reticentes, convierten en secreto el aire mismo, y se vuelven elocuentes como consecuencia de callarse.\"", owned: false },
    { title: "Dust", author: "Hugh Howey", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1436806122l/18866705.jpg", status: "read", rating: 4, description: "Armed with secret knowledge, Juliette, now mayor of Silo 18 and her crew set out to rescue a world she hates but now understands better -- the world of the Silos with its rigid rules and terrible consequences for disobedience.", owned: false },
    { title: "Shift", author: "Hugh Howey", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1379003176l/17306293.jpg", status: "read", rating: 4, description: "In a future less than 50 years away, the world is still as we know it. Time continues to tick by. The truth is that it is ticking away. A powerful few know what lies ahead. They are preparing for it. They are trying to protect us. They are setting us on a path from which we can never return. A path that will lead to destruction; a path that will take us below ground. The history of the silo is about to be written. Our future is about to begin.", owned: false },
    { title: "A Man for All Markets: From Las Vegas to Wall Street, How I Beat the Dealer and the Market", author: "Edward O. Thorp", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1471282417l/25733505.jpg", status: "read", rating: 5, description: "Traces the author's experiences as a mathematics wizard, author, inventor, hedge-fund manager, and card-counter who revealed casino-beating strategies, invented the first wearable computer, and launched a Wall Street revolution.", owned: false },
    { title: "The Mosquito: A Human History of Our Deadliest Predator", author: "Timothy C. Winegard", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1544102229l/42983957.jpg", status: "read", rating: 4, description: "A pioneering and groundbreaking work of narrative nonfiction that offers a dramatic new perspective on the history of humankind, this text shows how through millennia, the mosquito has been the single most powerful force in determining humanity's fate.", owned: false },
    { title: "Are We Smart Enough to Know How Smart Animals Are?", author: "Frans de Waal", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1490975607l/30231743.jpg", status: "read", rating: 4, description: "Hailed as a classic, Are We Smart Enough to Know How Smart Animals Are? explores the oddities and complexities of animal cognition―in crows, dolphins, parrots, sheep, wasps, bats, chimpanzees, and bonobos―to reveal how smart animals really are, and how we’ve underestimated their abilities for too long. Did you know that octopuses use coconut shells as tools, that elephants classify humans by gender and language, and that there is a young male chimpanzee at Kyoto University whose flash memory puts that of humans to shame? Fascinating, entertaining, and deeply informed, de Waal’s landmark work will convince you to rethink everything you thought you knew about animal―and human―intelligence.", owned: false },
    { title: "The Anthropocene Reviewed: Essays on a Human-Centered Planet", author: "John  Green", category: "Ensayo", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1616514130l/55145261.jpg", status: "read", rating: 4, description: "The Anthropocene is the current geologic age, in which humans have profoundly reshaped the planet and its biodiversity. In this remarkable symphony of essays adapted and expanded from his groundbreaking podcast, bestselling author John Green reviews different facets of the human-centered planet on a five-star scale—from the QWERTY keyboard and sunsets to Canada geese and Penguins of Madagascar.\n\nFunny, complex, and rich with detail, the reviews chart the contradictions of contemporary humanity. As a species, we are both far too powerful and not nearly powerful enough, a paradox that came into sharp focus as we faced a global pandemic that both separated us and bound us together.\n\nJohn Green’s gift for storytelling shines throughout this masterful collection. The Anthropocene Reviewed is a open-hearted exploration of the paths we forge and an unironic celebration of falling in love with the world.", owned: false },
    { title: "The Righteous Mind: Why Good People Are Divided by Politics and Religion", author: "Jonathan Haidt", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1534528902l/11324722.jpg", status: "read", rating: 4, description: "A groundbreaking investigation into the origins of morality, which turns out to be the basis for religion and politics. The book explains the American culture wars and refutes the \"New Atheists.\"", owned: false },
    { title: "El fin de la muerte", author: "Liu Cixin", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1538051959l/32827109.jpg", status: "read", rating: 4, description: "Cierre de la trilogía de los Tres Cuerpos. La humanidad y los Trisolarianos llegan a un equilibrio basado en la disuasión cósmica; cuando este se rompe, el universo entero revela sus reglas oscuras y la teoría del «bosque oscuro» adquiere su sentido más radical. Una de las cumbres recientes de la ciencia ficción.", descriptionAi: true, owned: false },
    { title: "El bosque oscuro", author: "Liu Cixin", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1508781967l/32827084.jpg", status: "read", rating: 4, description: "Segunda parte de la trilogía. La humanidad descubre la teoría del bosque oscuro —cada civilización debe ocultarse o ser destruida— y selecciona a cuatro Wallfacers para enfrentar a la inminente flota trisolariana. La novela cruza el thriller geopolítico con la metafísica fría del cosmos, todo a escala de siglos.", descriptionAi: true, owned: false },
    { title: "El problema de los tres cuerpos", author: "Liu Cixin", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1511909569l/28487182.jpg", status: "read", rating: 5, description: "Inicio de la trilogía de ciencia ficción. Durante la Revolución Cultural, una astrofísica china traumatizada envía una señal al espacio que despierta la atención de una civilización agonizante en Alfa Centauri. Décadas después, una serie de suicidios entre científicos pone en marcha una investigación que conecta la física fundamental con una invasión que llegará en cuatro siglos.", descriptionAi: true, owned: false },
    { title: "Through a Glass Brightly: Using Science to See Our Species as We Really Are", author: "David Philip Barash", category: "Biología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1515277902l/36794097.jpg", status: "read", rating: 4, description: "Evolutionary biologist David Barash uses contemporary biology to dismantle several flattering self-images — exceptionalism, free will, perfectibility — and to argue for a more honest humanism.", owned: false },
    { title: "Greed Is Dead", author: "Paul Collier", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1597161167l/52692578.jpg", status: "read", rating: 4, description: "Paul Collier and John Kay argue that the «homo economicus» model is empirically wrong; cooperation, mutual obligation and shared identity drive prosperous societies, and policy should be redesigned accordingly.", owned: false },
    { title: "Other Minds", author: "Peter Godfrey-Smith", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1606353700l/28116739.jpg", status: "read", rating: 4, description: "\"Peter Godfrey-Smith is a leading philosopher of science. He is also a scuba diver whose underwater videos of warring octopuses have attracted wide notice. In this book, he brings his parallel careers together to tell a bold new story of how nature became aware of itself. Mammals and birds are widely seen as the smartest creatures on earth. But one other branch of the tree of life has also sprouted surprising intelligence: the cephalopods, consisting of the squid, the cuttlefish, and above all the octopus. New research shows that these marvelous creatures display remarkable gifts. What does it mean that intelligence on earth has evolved not once but twice? And that the mind of the octopus is nonetheless so different from our own? Combining science and philosophy with firsthand accounts of his cephalopod encounters, Godfrey-Smith shows how primitive organisms bobbing in the ocean began sending signals to each other and how these early forms of communication gave rise to the advanced nervous systems that permit cephalopods to change colors and human beings to speak. By tracing the problem of consciousness back to its roots and comparing the human brain to its most alien and perhaps m", owned: false },
    { title: "Thinking with Your Hands: The Surprising Science Behind How Gestures Shape Our Thoughts", author: "Susan Goldin-Meadow", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1681110534l/62874262.jpg", status: "read", rating: 4, description: "Psycholinguist Susan Goldin-Meadow reviews decades of work showing that gesture is not decoration: it shapes how we learn, reason and explain ideas to others.", owned: false },
    { title: "Orientalism", author: "Edward W. Said", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1704228087l/355190.jpg", status: "read", rating: 4, description: "Orientalism is a 1978 book by Edward W. Said, in which the author discusses Orientalism, defined as the West's patronizing representations of \"The East\"—the societies and peoples who inhabit the places of Asia, North Africa, and the Middle East. According to Said, orientalism (the Western scholarship about the Eastern World) is inextricably tied to the imperialist societies who produced it, which makes much Orientalist work inherently political and servile to power.\n\nAccording to Said, in the Middle East, the social, economic, and cultural practices of the ruling Arab elites indicate they are imperial satraps who have internalized the romanticized \"Arab Culture\" created by French, British and, later, American Orientalists; the examples include critical analyses of the colonial literature of Joseph Conrad, which conflates a people, a time, and a place into a narrative of incident and adventure in an exotic land.\n\nThe critical application of post-structuralism in the scholarship of Orientalism influenced the development of literary theory, cultural criticism, and the field of Middle Eastern studies, especially regarding how academics practice their intellectual inquiry when examining", owned: false },
    { title: "Virtue Signaling: Essays on Darwinian Politics & Free Speech", author: "Geoffrey Miller", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1568843294l/50885372.jpg", status: "read", rating: 3, description: "Geoffrey Miller collects essays arguing that political behavior often functions as costly signaling of moral fitness, and defends robust free-speech norms as a counterweight.", owned: false },
    { title: "Shame: The Politics and Power of an Emotion", author: "David Keen", category: "Política", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1680892443l/126249451.jpg", status: "read", rating: 3, description: "Politics professor David Keen examines how shame and humiliation drive politics — from genocide to populism — and the conditions under which collective shame can fuel reform or backlash.", owned: false },
    { title: "The Histories", author: "Herodotus", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1399225547l/1362.jpg", status: "read", rating: 5, description: "Herodotus's foundational work of Greek history (5th century BCE): an inquiry into the causes of the Persian Wars that doubles as a sprawling ethnography of the known world.", owned: false },
    { title: "Brains Through Time: A Natural History of Vertebrates", author: "Georg F. Striedter", category: "Neurociencia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1577850440l/50234145.jpg", status: "read", rating: 4, description: "Georg Striedter and R. Glenn Northcutt reconstruct half a billion years of brain evolution across vertebrates, organ by organ, showing how new structures piggyback on ancient ones.", owned: false },
    { title: "How to Grow Old: Ancient Wisdom for the Second Half of Life (Ancient Wisdom for Modern Readers)", author: "Marcus Tullius Cicero", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1445789371l/26597350.jpg", status: "read", rating: 5, description: "Princeton's translation of Cicero's De Senectute: short, lucid arguments from the Roman orator on why old age is not the catastrophe it is made out to be.", owned: false },
    { title: "Becoming Earth: How Our Planet Came to Life", author: "Ferris Jabr", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1705955968l/200634712.jpg", status: "read", rating: 5, description: "Science writer Ferris Jabr traces the co-evolution of life and the planet itself, arguing that Earth is best understood as a single, evolving organism shaped by the organisms that inhabit it.", owned: false },
    { title: "Why We Remember: Unlocking Memory's Power to Hold on to What Matters", author: "Charan Ranganath", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1699034966l/157981712.jpg", status: "read", rating: 5, description: "Neuroscientist Charan Ranganath reframes memory as future-facing: we remember selectively in order to navigate, and the bugs we complain about are usually features.", owned: false },
    { title: "Writing to Persuade: How to Bring People Over to Your Side", author: "Trish Hall", category: "Lingüística", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1556344923l/41817516.jpg", status: "read", rating: 3, description: "Trish Hall, longtime op-ed editor at The New York Times, distills the craft of persuasive writing: how to find a fresh argument, structure it, and survive the editing.", owned: false },
    { title: "Skin in the Game: The Hidden Asymmetries in Daily Life", author: "Nassim Nicholas Taleb", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1510319798l/36064445.jpg", status: "read", rating: 4, description: "The phrase \"skin in the game\" is one we have often heard but have rarely stopped to truly dissect. It is the backbone of risk management, but it's also an astonishingly complex worldview that, as Nassim Nicholas Taleb shows in this book, applies to literally all aspects of our lives. In his inimitable style, Taleb pulls on everything from Antaeus the Giant to Hammurabi to Donald Trump to Seneca to the ethics of disagreement to create a jaw-dropping tapestry for understanding our world in a brand new way.\n\nThe phrase \"skin in the game\" means that you do not pay attention to what people say, only to what they do, and to how much of their necks they are putting on the line. This willingness to accept one's own risks is an essential attribute of people in all walks of life. Taleb challenges long-held beliefs about those who control our military, finances, religions, and so much more-- and shows how \"skin in the game\" applies to all aspects of our lives.", owned: false },
    { title: "Pedagogy of the Oppressed", author: "Paulo Freire", category: "Autobiografía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1388180018l/72657.jpg", status: "read", rating: 5, description: "\"First published in Portuguese in 1968, [this book] was translated and published in English in 1970. Paulo Freire's work has helped to empower countless people throughout the world and continues to possess a special urgency as the creation of a permanent underclass among the underprivileged and minorities in urban centers around the world continues. The 50th anniversary edition includes a new introduction by Donaldo Macedo, an afterword by Ira Shor, and interviews with Marina Aparicio Barber�an, Noam Chomsky, Gustavo E. Fischman, Ram�on Flecha, Ronald David Glass, Valerie Kinloch, peter Mayo, Peter McLaren, and Margo Okazawa-Rey to inspire a new generation of educators, students, and general readers for years to come.\"--Page [4] of cover.", owned: false },
    { title: "Cultish: The Language of Fanaticism", author: "Amanda Montell", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1762247387l/55338982.jpg", status: "read", rating: 4, description: "Linguist Amanda Montell decodes how cult-like groups — from heaven's-gate sects to multilevel marketing to fitness studios — use language to bind members and silence dissent.", owned: false },
    { title: "High Conflict: Why We Get Trapped and How We Get Out", author: "Amanda Ripley", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1611497693l/55711592.jpg", status: "read", rating: 5, description: "Journalist Amanda Ripley distinguishes healthy good conflict from the corrosive «high conflict» of identity wars, and tells stories of mediators who help groups escape it.", owned: false },
    { title: "El poder de las historias: O cómo han cautivado al ser humano, de la Ilíada a Harry Potter", author: "Martin Puchner", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1551230468l/44149042.jpg", status: "read", rating: 5, description: "Dieciséis textos fundacionales —de Gilgamesh y la Ilíada al Quijote, los Manifiestos comunistas y Harry Potter— sirven para mostrar cómo las narraciones han forjado culturas, religiones, revoluciones y formas de leer. Cada capítulo combina historia material del libro y análisis literario para argumentar que las grandes historias siempre han sido también vehículos de poder.", descriptionAi: true, owned: false },
    { title: "Co-Intelligence: Living and Working with AI", author: "Ethan Mollick", category: "Tecnología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1709537279l/198678736.jpg", status: "read", rating: 5, description: "Something new entered our world in November 2022 — the first general purpose AI that could pass for a human and do the kinds of creative, innovative work that only humans could do previously. After millions of years on our own, humans had developed a kind of co-intelligence that could augment, or even replace, human thinking. \nThrough his writing, speaking, and teaching, Mollick has become one of the most prominent and provocative explainers of AI, focusing on the practical aspects of how these new tools for thought can transform our world.", owned: false },
    { title: "Plunder: Private Equity's Plan to Pillage America", author: "Brendan Ballou", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1667340956l/62874267.jpg", status: "read", rating: 4, description: "Former government attorney Brendan Ballou documents how the private equity industry has extracted wealth from retail, healthcare, housing and prisons, with detailed case studies and policy fixes.", owned: false },
    { title: "A Beautifully Foolish Endeavor", author: "Hank Green", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1594920502l/49039441.jpg", status: "read", rating: 5, description: "Sequel to An Absolutely Remarkable Thing. With April May presumed dead, her friends and the alien Carls' game return, and Hank Green ramps up his satire of online fame, identity and political polarization.", owned: false },
    { title: "The Utopia of Rules: On Technology, Stupidity, and the Secret Joys of Bureaucracy", author: "David Graeber", category: "Política", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1417415465l/22245334.jpg", status: "read", rating: 5, description: "\"Where does the desire for endless rules, regulations, and bureaucracy come from? How did we come to spend so much of our time filling out forms? And is it really a cipher for state violence? To answer these questions, anthropologist David Graeber ... traces the peculiar and unexpected ways we relate to bureaucracy today, and reveals how it shapes our lives in ways we may not even notice\"--Jacket.", owned: false },
    { title: "The Paradox of Choice: Why More Is Less", author: "Barry Schwartz", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1410138134l/10639.jpg", status: "read", rating: 4, description: "In the spirit of [Alvin Toffler](/authors/OL433058A)’s [*Future Shock*](/works/OL2869043W), a social critique of our obsession with choice, and how it contributes to anxiety, dissatisfaction and regret. This paperback includes a new P.S. section with author interviews, insights, features, suggested readings, and more.Whether we’re buying a pair of jeans, ordering a cup of coffee, selecting a long-distance carrier, applying to college, choosing a doctor, or setting up a 401(k), everyday decisions--both big and small--have become increasingly complex due to the overwhelming abundance of choice with which we are presented.We assume that more choice means better options and greater satisfaction. But beware of excessive choice: choice overload can make you question the decisions you make before you even make them, it can set you up for unrealistically high expectations, and it can make you blame yourself for any and all failures. In the long run, this can lead to decision-making paralysis, anxiety, and perpetual stress. And, in a culture that tells us that there is no excuse for falling short of perfection when your options are limitless, too much choice can lead to clinical depression.", owned: false },
    { title: "Order without Design: How Markets Shape Cities", author: "Alain Bertaud", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1544515502l/39644188.jpg", status: "read", rating: 4, description: "\"This book emerges from a 55-year career in urban planning, and is illustrated by the author's real-world experience. Without understanding how markets work, urban planners are likely to design infrastructure and regulations that will adversely impact the functioning of cities. By contrast, urban economists review decisions and outcomes after the fact, often publishing their conclusions in specialized journals that fail to influence decision making. This book is a call for qualitative urban planners and quantitative urban economists to come together. Specifically, the book calls for urban economists to take a larger role in the process of operational urban planning. For example, land prices decrease the further away one gets from a city center. When land prices are high, households and firms consume less land; that is, they live in smaller homes and work in smaller offices. Population density then increases because the city is still a desirable place to be, and you can fit more people in smaller spaces. While urban planning often tries to limit densities, it is almost impossible to do so when the price of land is high. Without understanding the factors that lead to high prices, urb", owned: false },
    { title: "Change: How Organizations Achieve Hard-to-Imagine Results in Uncertain and Volatile Times", author: "John P. Kotter", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1620291553l/57961293.jpg", status: "read", rating: 2, description: "What will it take to bring your organization successfully into the twenty-first century? The world's foremost expert on business leadership distills twenty-five years of experience and wisdom based on lessons he has learned from scores of organizations and businesses to write this visionary guide. The result is a very personal book that is at once inspiring, clear-headed, and filled with important implications for the future. The pressures on organizations to change will only increase over the next decades. Yet the methods managers have used in the attempt to transform their companies into stronger competitors -- total quality management, reengineering, right sizing, restructuring, cultural change, and turnarounds -- routinely fall short, says Kotter, because they fail to alter behavior. Emphasizing again and again the critical need for leadership to make change happen, Leading Change provides the vicarious experience and positive role models for leaders to emulate. The book identifies an eight-step process that every company must go through to achieve its goal, and shows where and how people -- good people -- often derail. Reading this highly personal book is like spending a day w", owned: false },
    { title: "The Playbook: How to Deny Science, Sell Lies, and Make a Killing in the Corporate World", author: "Jennifer Jacquet", category: "Política", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1659191480l/60044520.jpg", status: "read", rating: 4, description: "Jennifer Jacquet identifies the recurring tactics — manufacturing doubt, attacking the scientists, blaming consumers — that corporations use to delay regulation, and proposes ways to fight back.", owned: false },
    { title: "Technopoly: The Surrender of Culture to Technology", author: "Neil Postman", category: "Tecnología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1388365812l/79678.jpg", status: "read", rating: 5, description: "With characteristic wit and candor, Neil Postman, our most astute and engaging cultural critic, launches a trenchant--and harrowing--warning against the tyranny of machines over man in the late twentieth century.  We live in a time when physical well-being is determined by CAT scan results.  Facts need the substantiation of statistical study.  The human mind needs \"deprogramming\" while computers catch devastating \"viruses.\"  We live, then, in a Technopoly -- a self-justifying, self-perpetuating system wherein technology of every kind is cheerfully granted sovereignty over social institutions and national life.\n\nIn this provocative work, the author of *Amusing Ourselves to Death* chronicles our transformation from a society that uses technology to one that is shaped by it, as he traces its effects upon what we mean by politics, intellect, religion, history--even privacy and truth.  But if *Technopoly* is disturbing, it is also a passionate rallying cry filled with a humane rationalism as it asserts the manifold means by which technology, placed within the context of our larger human goals and social values, is an invaluable instrument for furthering the most worthy human endeavors. ", owned: false },
    { title: "Saving Normal: An Insider's Revolt Against Out-Of-Control Psychiatric Diagnosis, DSM-5, Big Pharma, and the Medicalization of Ordinary Life", author: "Allen Frances", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1364850431l/16248231.jpg", status: "read", rating: 5, description: "Frances argues that the new edition of the Diagnostic and Statistical Manual of Mental Disorders threatens to destroy what is considered normal and that grief, sorrow, stress, disappointment, and other feelings are part of life, not a psychiatric disease.", owned: false },
    { title: "Mind in Motion: How Action Shapes Thought", author: "Barbara Tversky", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1557350633l/42118411.jpg", status: "read", rating: 4, description: "Cognitive psychologist Barbara Tversky argues that thought is built from spatial cognition: we think with our bodies first and abstract ideas later, inheriting the structures of physical action.", owned: false },
    { title: "The Open Society and Its Enemies", author: "Karl Popper", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1417985695l/240592.jpg", status: "read", rating: 5, description: "An open society provides its citizens with a mechanism for changing government; a closed society doesn't, forcing its citizens to rely on extra-legal revolution.  Popper analyzes the open-closed society debate using three exemplars of closed-society advocacy: Plato, Hegel (and wow, does Popper hate on Hegel), and Marx.  The main analytical viewpoints are historicist (backward-looking, utopian) motivations for closed societies and rational (forward-looking, empirical) motivations for open societies.", owned: false },
    { title: "Same as Ever: A Guide to What Never Changes", author: "Morgan Housel", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1680687321l/125116554.jpg", status: "read", rating: 5, description: "Morgan Housel collects twenty-three short essays on the recurring patterns in human behavior — risk, story, envy, surprise — that endure even as technology and markets keep changing.", owned: false },
    { title: "Getting the Love You Want: A Guide for Couples", author: "Harville Hendrix", category: "Autoayuda", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1388871224l/46188.jpg", status: "read", rating: 4, description: "Harville Hendrix's classic introduces «imago» therapy: a structured method for couples to recognize how childhood wounds shape adult conflict and to use the relationship for healing.", owned: false },
    { title: "Narrative Economics: How Stories Go Viral and Drive Major Economic Events", author: "Robert J. Shiller", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1565785098l/44526017.jpg", status: "read", rating: 5, description: "Nobel laureate Robert Shiller argues that economic shifts are driven not just by data but by the contagious narratives people share about the economy, and shows how to model them.", owned: false },
    { title: "Enzymes: A Very Short Introduction", author: "Paul  Engel", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1594055893l/52049776.jpg", status: "read", rating: 4, description: "Paul Engel offers a concise overview of enzymes — what they are, how they catalyze life's chemistry, and how biotechnology, medicine and industry use them.", owned: false },
    { title: "Isaac Newton", author: "James Gleick", category: "Biografía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1386745732l/17098.jpg", status: "read", rating: 5, description: "\"In this biography, James Gleick moves between a comprehensive historical portrait and a dramatic focus on Newton's significant letters and unpublished notebooks to illuminate the real importance of his work in physics, in optics, and in calculus. He makes us see the old intuitive, alchemical universe out of which Newton's mathematics first arose and shows us how Newton's ideas have altered all forms of understanding from history to philosophy. And he gives us an account of the conflicting impulses that pulled at this man's heart: his quiet longings, his rage, his secrecy, the extraordinary subtleties of personality that were mirrored in the invisible forces he first identified as the building blocks of science. More than biography, more than history, more than science, Isaac Newton tells us how, through the mind of one man, we have come to know our place in the cosmos.\"--BOOK JACKET", owned: false },
    { title: "Two Cheers for Anarchism: Six Easy Pieces on Autonomy, Dignity and Meaningful Work and Play", author: "James C. Scott", category: "Política", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1384020718l/14891877.jpg", status: "read", rating: 5, description: "**Two Cheers for Anarchism: Six Easy Pieces on Autonomy, Dignity, and Meaningful Work and Play** is a 2012 book-length defense of the anarchist perspective, written by anthropologist James C. Scott and published by Princeton University Press. \n\n(Source: [Wikipedia](https://en.wikipedia.org/wiki/Two_Cheers_for_Anarchism))", owned: false },
    { title: "The Master and His Emissary: The Divided Brain and the Making of the Western World", author: "Iain McGilchrist", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1328826802l/6968772.jpg", status: "read", rating: 5, description: "\"Now available in a larger format, a fascinating exploration of the differences between the brain's right and left hemispheres and their effects on society, history, and culture.\"--Publisher description.", owned: false },
    { title: "Systems Thinking For Social Change: A Practical Guide to Solving Complex Problems, Avoiding Unintended Consequences, and Achieving Lasting Results", author: "David Peter Stroh", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1444660467l/26089423.jpg", status: "read", rating: 4, description: "David Peter Stroh adapts systems-thinking tools — causal loops, leverage points — for nonprofits and social-change leaders trying to break stuck patterns.", owned: false },
    { title: "Amusing Ourselves to Death: Public Discourse in the Age of Show Business", author: "Neil Postman", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1568871230l/74034.jpg", status: "read", rating: 5, description: "Amusing Ourselves to Death is a prophetic look at what happens when politics, journalism, education, and even religion become subject to the demands of  entertainment. It is also a blueprint for regaining control of our media, so that they can serve our highest goals.", owned: false },
    { title: "Evolutionary Ideas: Unlocking ancient innovation to solve tomorrow’s challenges", author: "Sam Tatam", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1644339048l/60316858.jpg", status: "read", rating: 5, description: "Behavioral scientist Sam Tatam reframes innovation as natural selection on ideas, with case studies from advertising, public health and product design.", owned: false },
    { title: "Attention!: The power of simple decisions in a distracted world", author: "Rob  Hatch", category: "Audiobook", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1601939137l/55575388.jpg", status: "read", rating: 3, description: "Rob Hatch makes the case for small, repeatable decisions as the high-leverage move in a noisy economy where attention has become the scarcest resource.", owned: false },
    { title: "Hidden Potential: The Science of Achieving Greater Things", author: "Adam M. Grant", category: "Autoayuda", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1689111352l/157095669.jpg", status: "read", rating: 5, description: "Adam Grant argues that what we call talent often masks character traits and structural luck, and shows research-backed ways to build the skills that compound over time.", owned: false },
    { title: "The Narrow Road Between Desires", author: "Patrick Rothfuss", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1716011662l/157265081.jpg", status: "read", rating: 5, description: "Patrick Rothfuss's expanded reissue of the Bast novella «The Lightning Tree»: a single day in the life of Kvothe's mischievous apprentice, granting favors and trading in secrets.", owned: false },
    { title: "A Hunter-Gatherer's Guide to the 21st Century: Evolution and the Challenges of Modern Life", author: "Heather E. Heying", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1611977225l/56883406.jpg", status: "read", rating: 5, description: "Evolutionary biologists Heather Heying and Bret Weinstein argue that many modern ills — diet, parenting, education — stem from mismatches between our hunter-gatherer adaptations and contemporary life.", owned: false },
    { title: "The Lightning Tree", author: "Patrick Rothfuss", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1659900457l/55262194.jpg", status: "read", rating: 5, description: "Patrick Rothfuss's short story in the Rogues anthology: a single day with Bast, who concedes favors and trades in secrets in a sleepy village.", owned: false },
    { title: "Wanting: The Power of Mimetic Desire in Everyday Life", author: "Luke  Burgis", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1615240502l/54860444.jpg", status: "read", rating: 4, description: "Entrepreneur and Girard scholar Luke Burgis brings René Girard's theory of imitative desire into the world of work and tech: most of our wants are borrowed from models we rarely notice.", owned: false },
    { title: "God: An Anatomy", author: "Francesca Stavrakopoulou", category: "Espiritualidad", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1619419541l/57282028.jpg", status: "read", rating: 4, description: "Biblical scholar Francesca Stavrakopoulou reconstructs the corporeal Yahweh of the ancient Israelites — his feet, hands, genitals and face — to show how a richly embodied god became the disembodied God of monotheism.", owned: false },
    { title: "Gut: The Inside Story of Our Body's Most Underrated Organ", author: "Giulia Enders", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1435168687l/23013953.jpg", status: "read", rating: 5, description: "Giulia Enders, a young German microbiologist, writes a witty popular tour of the digestive tract and the microbiome, mixing science with everyday health advice.", owned: false },
    { title: "Understanding Complexity", author: "Scott E. Page", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1654077152l/46138936.jpg", status: "read", rating: 4, description: "Scott E. Page distills complexity science — agents, networks, emergence, adaptation — into a brisk primer for readers who want to think more clearly about social and economic systems.", owned: false },
    { title: "Bernoulli's Fallacy: Statistical Illogic and the Crisis of Modern Science", author: "Aubrey Clayton", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1622419217l/55825328.jpg", status: "read", rating: 5, description: "There is a logical flaw in the statistical methods used across experimental science. This fault is not a minor academic quibble: it underlies a reproducibility crisis now threatening entire disciplines. In an increasingly statistics-reliant society, this same deeply rooted error shapes decisions in medicine, law, and public policy with profound consequences. The foundation of the problem is a misunderstanding of probability and its role in making inferences from observations.\n\nAubrey Clayton traces the history of how statistics went astray, beginning with the groundbreaking work of the seventeenth-century mathematician Jacob Bernoulli and winding through gambling, astronomy, and genetics. Clayton recounts the feuds among rival schools of statistics, exploring the surprisingly human problems that gave rise to the discipline and the all-too-human shortcomings that derailed it. He highlights how influential nineteenth- and twentieth-century figures developed a statistical methodology they claimed was purely objective in order to silence critics of their political agendas, including eugenics.\n\nClayton provides a clear account of the mathematics and logic of probability, conveying compl", owned: false },
    { title: "How to Be an Antiracist", author: "Ibram X. Kendi", category: "Misterio", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1560163756l/40265832.jpg", status: "read", rating: 5, description: "Antiracism is a transformative concept that reorients and reenergizes the conversation about racism—and, even more fundamentally, points us toward liberating new ways of thinking about ourselves and each other. At its core, racism is a powerful system that creates false hierarchies of human value; its warped logic extends beyond race, from the way we regard people of different ethnicities or skin colors to the way we treat people of different sexes, gender identities, and body types. Racism intersects with class and culture and geography and even changes the way we see and value ourselves. In How to Be an Antiracist, Kendi takes readers through a widening circle of antiracist ideas—from the most basic concepts to visionary possibilities—that will help readers see all forms of racism clearly, understand their poisonous consequences, and work to oppose them in our systems and in ourselves.\n\nKendi weaves an electrifying combination of ethics, history, law, and science with his own personal story of awakening to antiracism. This is an essential work for anyone who wants to go beyond the awareness of racism to the next step: contributing to the formation of a just and equitable society.", owned: false },
    { title: "One Day All This Will Be Yours", author: "Adrian Tchaikovsky", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1593355556l/54303485.jpg", status: "read", rating: 5, description: "Adrian Tchaikovsky's short novel: the last survivor of the Time War lives alone at the very end of history and murders anyone who shows up, until visitors arrive who refuse to leave.", owned: false },
    { title: "Walking to Aldebaran", author: "Adrian Tchaikovsky", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1539510199l/42201505.jpg", status: "read", rating: 4, description: "Tchaikovsky novella: astronaut Gary Rendell wanders lost through an alien artifact in the outer solar system, narrating his slow transformation into something other than human.", owned: false },
    { title: "Autopilot: The Art & Science of Doing Nothing", author: "Andrew  Smart", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1399494666l/18053732.jpg", status: "read", rating: 4, description: "Andrew Smart argues that idleness is essential to creativity and decision-making, drawing on neuroscience to defend daydreaming, slowness and unstructured time.", owned: false },
    { title: "Against Method", author: "Paul Karl Feyerabend", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1373999202l/137979.jpg", status: "read", rating: 5, description: "**Against Method: Outline of an Anarchistic Theory of Knowledge** is a 1975 book about the philosophy of science by Paul Feyerabend, in which the author argues that science is an anarchic enterprise, not a nomic (customary) one. In the context of this work, the term anarchy refers to epistemological anarchy.\n\n(Source: [Wikipedia](https://en.wikipedia.org/wiki/Against_Method))", owned: false },
    { title: "The Story of the Human Body: Evolution, Health, and Disease", author: "Daniel E. Lieberman", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1375545961l/17736859.jpg", status: "read", rating: 5, description: "In this landmark book of popular science, Daniel E. Lieberman—chair of the department of human evolutionary biology at Harvard University and a leader in the field—gives us a lucid and engaging account of how the human body evolved over millions of years, even as it shows how the increasing disparity between the jumble of adaptations in our Stone Age bodies and advancements in the modern world is occasioning this paradox: greater longevity but increased chronic disease.\n \nThe Story of the Human Body brilliantly illuminates as never before the major transformations that contributed key adaptations to the body: the rise of bipedalism; the shift to a non-fruit-based diet; the advent of hunting and gathering, leading to our superlative endurance athleticism; the development of a very large brain; and the incipience of cultural proficiencies. Lieberman also elucidates how cultural evolution differs from biological evolution, and how our bodies were further transformed during the Agricultural and Industrial Revolutions.\n \nWhile these ongoing changes have brought about many benefits, they have also created conditions to which our bodies are not entirely adapted, Lieberman argues, resultin", owned: false },
    { title: "Life on the Edge: The Coming of Age of Quantum Biology", author: "Johnjoe McFadden", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1429821731l/24040194.jpg", status: "read", rating: 5, description: "Life is the most extraordinary phenomenon in the known universe; but how does it work? It is remarkable that in this age of cloning and even synthetic biology, nobody has ever made anything living entirely out of dead material. Life remains the only way to make life. Are we missing a vital ingredient in its creation? Like Richard Dawkins' The Selfish Gene which provided a new perspective on evolution by shifting the focus of natural selection from organisms to genes, Life On The Edge alters our understanding of life from cells or biomolecules to the fundamental particles that drive life's dynamics. From this new perspective, life makes more sense as its missing ingredient is revealed to be quantum mechanics and the strange phenomena that lie at the heart of this most mysterious of sciences.", owned: false },
    { title: "Lives of the Stoics: The Art of Living from Zeno to Marcus Aurelius", author: "Ryan Holiday", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1594616854l/50484473.jpg", status: "read", rating: 5, description: "Nearly 2,300 years after a ruined merchant named Zeno first established a school on the Stoa Poikile of Athens, Stoicism has found a new audience among those who seek greatness, from athletes to politicians and everyone in between. It's no wonder; the philosophy and its embrace of self-mastery, virtue, and indifference to that which we cannot control is as urgent today as it was in the chaos of the Roman Empire.\n\nIn Lives of the Stoics, Holiday and Hanselman present the fascinating lives of the men and women who strove to live by the timeless Stoic virtues of Courage. Justice. Temperance. Wisdom. Organized in digestible, mini-biographies of all the well-known--and not so well-known--Stoics, this book vividly brings home what Stoicism was like for the people who loved it and lived it, dusting off powerful lessons to be learned from their struggles and successes.\n\nMore than a mere history book, every example in these pages, from Epictetus to Marcus Aurelius--slaves to emperors--is designed to help the reader apply philosophy in their own lives. Holiday and Hanselman unveil the core values and ideas that unite figures from Seneca to Cato to Cicero across the centuries. Among them are ", owned: false },
    { title: "Why We Work (TED Books)", author: "Barry Schwartz", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1440993087l/23280225.jpg", status: "read", rating: 5, description: "Psychologist Barry Schwartz argues against Adam Smith's view that people work only for money and surveys the conditions — meaning, autonomy, mastery — that make work flourish.", owned: false },
    { title: "Stumbling on Happiness", author: "Daniel Todd Gilbert", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1327947323l/56627.jpg", status: "read", rating: 5, description: "A smart and funny book by a prominent Harvard psychologist, which uses groundbreaking research and (often hilarious) anecdotes to show us why we're so lousy at predicting what will make us happy -- and what we can do about it.Most of us spend our lives steering ourselves toward the best of all possible futures, only to find that tomorrow rarely turns out as we had expected. Why? As Harvard psychologist Daniel Gilbert explains, when people try to imagine what the future will hold, they make some basic and consistent mistakes. Just as memory plays tricks on us when we try to look backward in time, so does imagination play tricks when we try to look forward. Using cutting-edge research, much of it original, Gilbert shakes, cajoles, persuades, tricks and jokes us into accepting the fact that happiness is not really what or where we thought it was. Among the unexpected questions he poses: Why are conjoined twins no less happy than the general population? When you go out to eat, is it better to order your favourite dish every time, or to try something new? If Ingrid Bergman hadn't gotten on the plane at the end of Casablanca, would she and Bogey have been better off?Smart, witty, accessi", owned: false },
    { title: "Persian Fire: The First World Empire and the Battle for the West", author: "Tom Holland", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1171501730l/103749.jpg", status: "read", rating: 4, description: "In 480 B.C., Xerxes, the King of Persia, led an invasion of mainland Greece. Its success should have been a formality. For seventy years, victory--rapid, spectacular victory--had seemed the birthright of the Persian Empire. In the space of a single generation, they had swept across the Near East, shattering ancient kingdoms, storming famous cities, putting together an empire which stretched from India to the shores of the Aegean. As a result of those conquests, Xerxes ruled as the most powerful man on the planet. Yet somehow, astonishingly, against the largest expeditionary force ever assembled, the Greeks of the mainland managed to hold out. The Persians were turned back. Greece remained free. Had the Greeks been defeated in the epochal naval battle at Salamis, not only would the West have lost its first struggle for independence and survival, but it is unlikely that there would ever have been such an entity as the West at all.Tom Holland's brilliant new book describes the very first \"clash of Empires\" between East and West. As he did in the critically praised Rubicon, he has found extraordinary parallels between the ancient world and our own. There is no other popular history tha", owned: false },
    { title: "The (Mis)Behavior of Markets", author: "Benoît B. Mandelbrot", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1387705519l/665134.jpg", status: "read", rating: 5, description: "Mathematician Benoît Mandelbrot applies fractal geometry to financial markets and argues that the standard Gaussian models of risk badly underestimate the frequency of crises.", owned: false },
    { title: "The Song of the Cell: An Exploration of Medicine and the New Human", author: "Siddhartha Mukherjee", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1666198162l/60321392.jpg", status: "read", rating: 5, description: "A history of the cell, and the development of a multiplicity of subsequent cell sciences, biological and medical, with an emphasis on the human.", owned: false },
    { title: "The Denial of Death", author: "Ernest Becker", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1388432490l/2761.jpg", status: "read", rating: 3, description: "Cultural anthropologist Ernest Becker's Pulitzer-winning argument that human civilization is built atop heroic systems designed to deny mortality, and that recognizing this is the first step toward maturity.", owned: false },
    { title: "The Stranger", author: "Albert Camus", category: "Novela clásica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1738704267l/49552.jpg", status: "read", rating: 4, description: "Albert Camus's 1942 novel: Meursault, a clerk in colonial Algiers, kills an Arab on a sunlit beach and is condemned more for refusing to feign emotion than for the crime itself.", owned: false },
    { title: "This Changes Everything: Capitalism vs. The Climate", author: "Naomi Klein", category: "Política", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1418103804l/21913812.jpg", status: "read", rating: 4, description: "The most important book yet from the author of the international bestseller The Shock Doctrine, a brilliant explanation of why the climate crisis challenges us to abandon the core “free market” ideology of our time, restructure the global economy, and remake our political systems.  In short, either we embrace radical change ourselves or radical changes will be visited upon our physical world. The status quo is no longer an option.\n\nIn This Changes Everything Naomi Klein argues that climate change isn’t just another issue to be neatly filed between taxes and health care. It’s an alarm that calls us to fix an economic system that is already failing us in many ways. Klein meticulously builds the case for how massively reducing our greenhouse emissions is our best chance to simultaneously reduce gaping inequalities, re-imagine our broken democracies, and rebuild our gutted local economies. She exposes the ideological desperation of the climate-change deniers, the messianic delusions of the would-be geoengineers, and the tragic defeatism of too many mainstream green initiatives. And she demonstrates precisely why the market has not—and cannot—fix the climate crisis but will instead make", owned: false },
    { title: "The Forgetting Machine: Memory, Perception, and the \"Jennifer Aniston Neuron\"", author: "Rodrigo Quian Quiroga", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1502135343l/34196225.jpg", status: "read", rating: 4, description: "Neuroscientist Rodrigo Quian Quiroga recounts his discovery of «concept cells» — neurons that fire for a specific person or idea — and what it implies for memory, perception and the self.", owned: false },
    { title: "Mission Economy: A Moonshot Guide to Changing Capitalism", author: "Mariana Mazzucato", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1611523123l/52745048.jpg", status: "read", rating: 4, description: "Economist Mariana Mazzucato draws on the Apollo program to argue for mission-driven public investment as the way to tackle climate, inequality and digital monopolies.", owned: false },
    { title: "The Scout Mindset: Why Some People See Things Clearly and Others Don't", author: "Julia Galef", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1612196393l/42041926.jpg", status: "read", rating: 5, description: "Julia Galef contrasts «soldier» reasoning, which defends preexisting beliefs, with the «scout» mindset of seeking accurate maps, and offers practices to strengthen the latter.", owned: false },
    { title: "Galápagos", author: "Kurt Vonnegut Jr.", category: "Ciencia ficción", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1585146350l/9593.jpg", status: "read", rating: 4, description: "Crucero a las Galápagos varado durante una pandemia mundial que esteriliza al resto de la humanidad. Un narrador fantasma cuenta desde el futuro cómo, un millón de años después, los descendientes de los náufragos —ya con cabezas pequeñas y aletas— se han adaptado al océano. Una de las novelas más oscuramente cómicas sobre la inteligencia humana.", descriptionAi: true, owned: false },
    { title: "For Profit: A History of Corporations", author: "William Magnuson", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1647264648l/60568507.jpg", status: "read", rating: 5, description: "William Magnuson traces the corporation from ancient Rome through the East India Company to modern tech giants, arguing that the institution oscillates between civic and predatory missions.", owned: false },
    { title: "The Triumph of Seeds: How Grains, Nuts, Kernels, Pulses, and Pips Conquered the Plant Kingdom and Shaped Human History", author: "Thor Hanson", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1416445819l/23013818.jpg", status: "read", rating: 4, description: "We live in a world of seeds. From our morning toast to the cotton in our clothes, they are quite literally the stuff and staff of life: supporting diets, economies, and civilizations around the globe. Just as the search for nutmeg and pepper drove the Age of Discovery, coffee beans fueled the Enlightenment and cottonseed sparked the Industrial Revolution. Seeds are fundamental objects of beauty, evolutionary wonders, and simple fascinations. Yet, despite their importance, seeds are often seen as commonplace, their extraordinary natural and human histories overlooked. Thanks to this stunning new book, they can be overlooked no more. This is a book of knowledge, adventure, and wonder, spun by an award-winning writer with both the charm of a fireside story-teller and the hard-won expertise of a field biologist. A fascinating scientific adventure, it is essential reading for anyone who loves to see a plant grow.", owned: false },
    { title: "The Basic Laws of Human Stupidity", author: "Carlo M. Cipolla", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1595814345l/49348225.jpg", status: "read", rating: 5, description: "Economic historian Carlo Cipolla's deadpan classic essay: a taxonomy of intelligence and stupidity that ends with the unsettling conclusion that stupid people are the most dangerous in any society.", owned: false },
    { title: "Phishing for Phools: The Economics of Manipulation and Deception", author: "George A. Akerlof", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1431977642l/25560530.jpg", status: "read", rating: 5, description: "Akerlof and Shiller argue that markets harm as well as help us. As long as there is profit to be made, sellers will systematically exploit our psychological weaknesses and our ignorance through manipulation and deception. Based on the intuitive idea that markets both give and take away, they show how phishing affects everyone, in almost every walk of life. We spend our money up to the limit, and then worry about how to pay the next month's bills. The financial system soars, then crashes. In doing so they explain a paradox: why, at a time when we are better off than ever before in history, all too many of us are leading lives of quiet desperation.", owned: false },
    { title: "Work: A Deep History, from the Stone Age to the Age of Robots", author: "James Suzman", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1589287074l/53398570.jpg", status: "read", rating: 5, description: "Anthropologist James Suzman traces 300,000 years of human work and argues that our modern obsession with toil is a recent aberration, not a continuation of ancestral life.", owned: false },
    { title: "The Body Keeps the Score: Brain, Mind, and Body in the Healing of Trauma", author: "Bessel van der Kolk", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1594559067l/18693771.jpg", status: "read", rating: 5, description: "Trauma is a fact of life. Veterans and their families deal with the painful aftermath of combat; one in five Americans has been molested; one in four grew up with alcoholics; one in three couples have engaged in physical violence. Dr. Bessel van der Kolk, one of the world’s foremost experts on trauma, has spent over three decades working with survivors. In _The Body Keeps the Score_, he uses recent scientific advances to show how trauma literally reshapes both body and brain, compromising sufferers’ capacities for pleasure, engagement, self-control, and trust. He explores innovative treatments—from neurofeedback and meditation to sports, drama, and yoga—that offer new paths to recovery by activating the brain’s natural neuroplasticity. Based on Dr. van der Kolk’s own research and that of other leading specialists, _The Body Keeps the Score_ exposes the tremendous power of our relationships both to hurt and to heal—and offers new hope for reclaiming lives.", owned: false },
    { title: "Blindsight: The (Mostly) Hidden Ways Marketing Reshapes Our Brains", author: "Matt           Johnson", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1588033552l/52225003.jpg", status: "read", rating: 5, description: "Matt Johnson and Prince Ghuman, both marketing scholars, lay out the neuroscience of advertising — attention, emotion, memory — and how brands exploit it, with practical defenses for consumers.", owned: false },
    { title: "Strangers to Ourselves: Discovering the Adaptive Unconscious", author: "Timothy D. Wilson", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1430649296l/15658.jpg", status: "read", rating: 5, description: "\"\"Know thyself,\" a precept as old as Socrates, is still good advice. But is introspection the best path to self-knowledge? What are we trying to discover, anyway? In an eye-opening tour of the unconscious, as contemporary psychological science has redefined it, Timothy D. Wilson introduces us to a hidden mental world of judgments, feelings, and motives that introspection may never show us.\"--Jacket.", owned: false },
    { title: "Thinking: The New Science of Decision-Making, Problem-Solving, and Prediction", author: "John Brockman", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1630574310l/17349252.jpg", status: "read", rating: 5, description: "Collects the thoughts of almost two hundred of today's leading thinkers on the issue of artifical intelligence.", owned: false },
    { title: "Evolutionary Psychology: A Beginner's Guide", author: "Robin I.M. Dunbar", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1407814382l/1144140.jpg", status: "read", rating: 4, description: "Robin Dunbar's primer on the central ideas, methods and controversies of evolutionary psychology, written for general readers.", owned: false },
    { title: "The Horse, the Wheel, and Language: How Bronze-Age Riders from the Eurasian Steppes Shaped the Modern World", author: "David W. Anthony", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1619046003l/1831667.jpg", status: "read", rating: 5, description: "Archaeologist David Anthony reconstructs the migration of Indo-European-speaking horse-and-wagon cultures out of the steppe, who carried language, mythology and bronze technology across Eurasia.", owned: false },
    { title: "Capitalist Realism: Is There No Alternative?", author: "Mark Fisher", category: "Política", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1732718088l/6763725.jpg", status: "read", rating: 4, description: "It is easier to imagine the end of the world than the end of capitalism. After 1989, capitalism has successfully presented itself as the only realistic political-economic system - a situation that the bank crisis of 2008, far from ending, actually compounded. The book analyses the development and principal features of this capitalist realism as a lived ideological framework. Using examples from politics, film (Children Of Men, Jason Bourne, Supernanny), fiction (Le Guin and Kafka), work and education, it argues that capitalist realism colours all areas of contemporary experience, is anything but realistic and asks how capitalism and its inconsistencies can be challenged. It is a sharp analysis of the post-ideological malaise that suggests that the economics and politics of free market neo-liberalism are givens rather than constructions.", owned: false },
    { title: "How Religion Evolved: And Why It Endures", author: "Robin I.M. Dunbar", category: "Espiritualidad", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1633159816l/57001983.jpg", status: "read", rating: 5, description: "Robin Dunbar uses evolutionary psychology to argue that religion emerged as a way to bond ever-larger human groups, and that its enduring forms exploit the same neural systems as music and laughter.", owned: false },
    { title: "The Story Paradox: How Our Love of Storytelling Builds Societies and Tears them Down", author: "Jonathan Gottschall", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1617717672l/56643990.jpg", status: "read", rating: 5, description: "Jonathan Gottschall examines the dark side of narrative: stories can build cooperation, but they also drive conspiracy theories, tribalism and political collapse.", owned: false },
    { title: "Capital in the Twenty First Century", author: "Thomas Piketty", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1390111547l/18736925.jpg", status: "read", rating: 4, description: "Thomas Piketty's bestseller marshals two centuries of data to show that when the return on capital exceeds growth, wealth concentrates relentlessly, with destabilizing political consequences.", owned: false },
    { title: "In Search of Mycotopia: Citizen Science, Fungi Fanatics, and the Untapped Potential of Mushrooms", author: "Doug Bierend", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1611556197l/55854545.jpg", status: "read", rating: 3, description: "Journalist Doug Bierend embeds with the global community of amateur mycologists rediscovering the role of fungi in medicine, food and the imagination.", owned: false },
    { title: "Don't Think of an Elephant! Know Your Values and Frame the Debate: The Essential Guide for Progressives", author: "George Lakoff", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1429063124l/13455.jpg", status: "read", rating: 4, description: "Cognitive linguist George Lakoff's manual on framing for the U.S. political left, with case studies on tax, war, abortion and family policy.", owned: false },
    { title: "Exercised: The Science of Physical Activity, Rest and Health", author: "Daniel E. Lieberman", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1597669547l/54993634.jpg", status: "read", rating: 5, description: "\"This highly engaging landmark work, a natural history of exercise--by the author of the best seller The Story of the Human Body--seeks to answer a fundamental question: were you born to run or rest? The first three parts of Exercised roughly follow the evolutionary story of human physical activity and inactivity, even as each chapter shatters a particular myth about exercise. Because we cannot understand physical activity without understanding its absence, Part One begins with physical inactivity. What are our bodies doing when we take it easy, including when we sit or sleep? Part Two explores physical activities that require speed, strength, and power, such as sprinting, lifting, and fighting. Part Three surveys physical activities that involve endurance, such as walking, running, or dancing, as well as their effect on aging. Part Four considers how anthropological and evolutionary approaches can help us exercise better in the modern world. How can we more effectively manage to exercise, and in what ways? To what extent, how, and why do different types and durations of exercise help prevent or treat the major diseases that are likely to make us sick and kill us? --", owned: false },
    { title: "Algorithms to Live By: The Computer Science of Human Decisions", author: "Brian  Christian", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1454296875l/25666050.jpg", status: "read", rating: 5, description: "Algorithms to Live By looks at the simple, precise algorithms that computers use to solve the complex 'human' problems that we face, and discovers what they can tell us about the nature and origin of the mind.\n\nAn audiobook version can be found at [here][1]", owned: false },
    { title: "A Thousand Brains: A New Theory of Intelligence", author: "Jeff Hawkins", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1609237769l/54503521.jpg", status: "read", rating: 5, description: "Jeff Hawkins proposes that the neocortex builds intelligence by running thousands of complementary models of the world in parallel, and lays out implications for AI.", owned: false },
    { title: "The Unthinkable: Who Survives When Disaster Strikes—and Why", author: "Amanda Ripley", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1320430266l/2706211.jpg", status: "read", rating: 5, description: "It lurks in the corner of our imagination, almost beyond our ability to see it: the possibility that a tear in the fabric of life could open up without warning, upending a house, a skyscraper, or a civilization. Today, nine out of ten Americans live in places at significant risk of earthquakes, hurricanes, tornadoes, terrorism, or other disasters. Tomorrow, some of us will have to make split-second choices to save ourselves and our families. How will we react? What will it feel like? Will we be heroes or victims? Will our upbringing, our gender, our personality--anything we've ever learned, thought, or dreamed of--ultimately matter?    Amanda Ripley, an award-winning journalist for Time magazine who has covered some of the most devastating disasters of our age, set out to discover what lies beyond fear and speculation. In this magnificent work of investigative journalism, Ripley retraces the human response to some of history's epic disasters, from the explosion of the Mont Blanc munitions ship in 1917--one of the biggest explosions before the invention of the atomic bomb--to a plane crash in England in 1985 that mystified investigators for years, to the journeys of the 15,000 peopl", owned: false },
    { title: "The WEIRDest People in the World: How the West Became Psychologically Peculiar and Particularly Prosperous", author: "Joseph Henrich", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1582603169l/51710349.jpg", status: "read", rating: 3, description: "Joseph Henrich shows that Western, Educated, Industrialized, Rich, Democratic populations are psychological outliers, and traces the surprising medieval origins of those traits.", owned: false },
    { title: "Doing Good Better: How Effective Altruism Can Help You Make a Difference", author: "William MacAskill", category: "Filosofía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1414351487l/23398748.jpg", status: "read", rating: 5, description: "William MacAskill's introduction to effective altruism: how to use evidence and cost-effectiveness to choose where to donate, work and volunteer.", owned: false },
    { title: "Confronting Climate Gridlock: How Diplomacy, Technology, and Policy Can Unlock a Clean Energy Future", author: "Daniel S. Cohan", category: "Desarrollo y sostenibilidad", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1642217288l/58616824.jpg", status: "read", rating: 5, description: "Atmospheric scientist Daniel Cohan argues that breaking the climate impasse requires simultaneously pushing diplomacy, technological deployment and smart industrial policy.", owned: false },
    { title: "Hurricane Lizards and Plastic Squid: The Fraught and Fascinating Biology of Climate Change", author: "Thor Hanson", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1630955309l/56643993.jpg", status: "read", rating: 5, description: "\"As a young biologist, Hanson by his own admission watched with some detachment as our warming planet presented plants and animals with an ultimatum: change or face extinction. But his detachment turned to both concern and awe, as he observed the remarkable narratives of change playing out in each plant and animal he studied. In Hurricane Lizards and Plastic Squid, Hanson tells the story of how nature-both plants and animals, from beech trees to beetles-are meeting the challenges of rapid climate change head-on, adjusting, adapting, and sometimes noticeably evolving... As global warming transforms and restructures the ecosystems in which these animals and others live, Hanson argues, we are forced to conclude that climate change will not have just one effect: Some transformations are beneficial. Others, and perhaps most, are devastating, wiping out entire species. One thing is constant: with each change an organism undergoes, the delicate balance of interdependent ecosystems is tipped, forcing the evolution of thousands more species, including us. To understand how, collectively, these changes are shaping the natural world and the future of life, Hanson looks back through deep time,", owned: false },
    { title: "The Folly of Fools: The Logic of Deceit and Self-Deception in Human Life", author: "Robert Trivers", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1320861437l/13033022.jpg", status: "read", rating: 5, description: "Explores the author's theorized evolutionary basis for self-deception, which he says is tied to group conflict, courtship, neurophysiology, and immunology, but can be negated by awareness of it and its results.", owned: false },
    { title: "Calling Bullshit: The Art of Skepticism in a Data-Driven World", author: "Carl T. Bergstrom", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1592246867l/48889983.jpg", status: "read", rating: 4, description: "Bullshit isn’t what it used to be. Now, two science professors give us the tools to dismantle misinformation and think clearly in a world of fake news and bad data.\n  \nMisinformation, disinformation, and fake news abound and it’s increasingly difficult to know what’s true. Our media environment has become hyperpartisan. Science is conducted by press release. Startup culture elevates bullshit to high art. We are fairly well equipped to spot the sort of old-school bullshit that is based in fancy rhetoric and weasel words, but most of us don’t feel qualified to challenge the avalanche of new-school bullshit presented in the language of math, science, or statistics. In Calling Bullshit, Professors Carl Bergstrom and Jevin West give us a set of powerful tools to cut through the most intimidating data. \n\nYou don’t need a lot of technical expertise to call out problems with data. Are the numbers or results too good or too dramatic to be true? Is the claim comparing like with like? Is it confirming your personal bias? Drawing on a deep well of expertise in statistics and computational biology, Bergstrom and West exuberantly unpack examples of selection bias and muddled data visualization, ", owned: false },
    { title: "The Nature of Plants: An Introduction to How Plants Work", author: "Craig N Huegel", category: "Biología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1548823464l/41543512.jpg", status: "read", rating: 4, description: "Botanist Craig Huegel offers an accessible introduction to plant structure, physiology and ecology, aimed at gardeners and naturalists.", owned: false },
    { title: "Return to Reason: The Science of Thought", author: "Scientific American", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1536108019l/41714569.jpg", status: "read", rating: 4, description: "Scientific American special collection of essays on rationality, judgment, memory and bias — and on what the cognitive sciences are doing to improve everyday reasoning.", owned: false },
    { title: "Chaos: Making a New Science", author: "James Gleick", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1327941595l/64582.jpg", status: "read", rating: 4, description: "The author describes how scientists studying the growth of complexity in nature are discovering order and pattern in chaos. He explains concepts such as nonlinearity, the Butterfly Effect, universal constants, fractals, and strange attractors, and examines the work of scientists such as Mitchell J. Feigenbaum, Edward Lorenz, and Benoit Mandelbrot.", owned: false },
    { title: "The Science of Storytelling", author: "Will Storr", category: "Lingüística", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1544377518l/43183121.jpg", status: "read", rating: 5, description: "Will Storr blends evolutionary psychology, neuroscience and screenwriting craft to explain why stories grip us and how writers can engineer that grip on purpose.", owned: false },
    { title: "Honeybee Democracy", author: "Thomas D. Seeley", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1348651493l/8705048.jpg", status: "read", rating: 5, description: "\"Honeybees make decisions collectively---and democratically. Every year, faced with the life-or-death problem of choosing and traveling to a new home, honeybees stake everything on a process that includes collective fact-finding, vigorous debate, and consensus building. In fact, as world-renowned animal behaviorist Thomas Seeley reveals, these incredible insects have much to teach us when it comes to collective wisdom and effective decision making. A remarkable and richly illustrated account of scientific discovery, Honeybee Democracy brings together, for the first time, decades of Seeley's pioneering research to tell the amazing story of house hunting and democratic debate among the honeybees.\" \"In the late spring and early summer, as a bee colony becomes overcrowded, a third of the hive stays behind and rears a new queen, while a swarm of thousands departs with the old queen to produce a daughter colony. Seeley describes how these bees evaluate potential nest sites, advertise their discoveries to one another, engage in open deliberation, choose a final site, and navigate together---as a swirling cloud of bees---to their new home. Seeley investigates how evolution has honed the de", owned: false },
    { title: "Educated", author: "Tara Westover", category: "Memorias", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1774287363l/35133922.jpg", status: "read", rating: 5, description: "*Educated* is a 2018 memoir by the American author Tara Westover. Westover recounts overcoming her survivalist Mormon family in order to go to college, and emphasizes the importance of education in enlarging her world. She details her journey from her isolated life in the mountains of Idaho to completing a PhD program in history at Cambridge University. She started college at the age of 17 having had no formal education. She explores her struggle to reconcile her desire to learn with the world she inhabited with her father.", owned: false },
    { title: "The Book of Humans: A Brief History of Culture, Sex, War and the Evolution of Us", author: "Adam Rutherford", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1537251428l/39939050.jpg", status: "read", rating: 4, description: "Geneticist Adam Rutherford surveys the behaviors that humans share with other animals — tool use, war, sex, deception — to argue we are at once less and more exceptional than we think.", owned: false },
    { title: "The Value of Everything: Making and Taking in the Global Economy", author: "Mariana Mazzucato", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1458793853l/29502362.jpg", status: "read", rating: 4, description: "Mariana Mazzucato distinguishes the activities that create real value from those that merely extract it, and argues that modern accounting has confused us about which firms are doing which.", owned: false },
    { title: "The Evolution Of Desire: Strategies of Human Mating", author: "David M. Buss", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1348779994l/27491.jpg", status: "read", rating: 4, description: "How we choose - and lose - our mates has always been a source of fascination. This controversial book is the first to present a unified theory of human mating behavior. The Evolution of Desire is based on the most massive study of human mating ever undertaken, encompassing more than 10,000 people of all ages from thirty-seven cultures worldwide.\n\nIf we all want love, why is there so much conflict in our most cherished relationships? To answer this question, we must look into our evolutionary past, according to David M. Buss. For in attracting, keeping, or even breaking up with our mates, we are closer to our ancestral forebears than many of us think.\n\nWith examples ranging from \"love bugs\" to elephant seals, from the Yanomamo tribe of Venezuela to the characters in A Streetcar Named Desire and contemporary men and women at singles bars, the author tells what women want, what men want, and then explains why their desire differ radically. The book discusses casual sex and long-term relationships, sexual conflict, the elusive quest for harmony between the sexes, and much more.\n\nBuss's findings - which have been widely reported in both academia and the popular press - are provocative. ", owned: false },
    { title: "The Enigma of Reason", author: "Hugo Mercier", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1488567927l/32336635.jpg", status: "read", rating: 5, description: "Reason, we are told, is what makes us human, the source of our knowledge and wisdom. If reason is so useful, why didn't it also evolve in other animals? If reason is that reliable, why do we produce so much thoroughly reasoned nonsense? In their groundbreaking account of the evolution and workings of reason, Hugo Mercier and Dan Sperber set out to solve this double enigma. Reason, they argue with a compelling mix of real-life and experimental evidence, is not geared to solitary use, to arriving at better beliefs and decisions on our own. What reason does, rather, is help us justify our beliefs and actions to others, convince them through argumentation, and evaluate the justifications and arguments that others address to us. In other words, reason helps humans better exploit their uniquely rich social environment. This interactionist interpretation explains why reason may have evolved and how it fits with other cognitive mechanisms. It makes sense of strengths and weaknesses that have long puzzled philosophers and psychologists--why reason is biased in favor of what we already believe, why it may lead to terrible ideas and yet is indispensable to spreading good ones.--", owned: false },
    { title: "Remember: The Science of Memory and the Art of Forgetting", author: "Lisa Genova", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1598831596l/54895704.jpg", status: "read", rating: 5, description: "Neuroscientist Lisa Genova explains why we forget — and why we should not be alarmed by most of it — alongside lifestyle measures that keep memory robust.", owned: false },
    { title: "Atomic Habits: An Easy & Proven Way to Build Good Habits & Break Bad Ones", author: "James Clear", category: "Autoayuda", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1655988385l/40121378.jpg", status: "read", rating: 5, description: "No matter your goals, Atomic Habits offers a proven framework for improving every day. James Clear, one of the world's leading experts on habit formation, reveals practical strategies that will teach you exactly how to form good habits, break bad ones, and master the tiny behaviors that lead to remarkable results. [**Atomic Habits pdf**](https://chesserresources.com/doc/atomic-habits-by-james-clear-pdf-2/)", owned: false },
    { title: "The Storytelling Animal: How Stories Make Us Human", author: "Jonathan Gottschall", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1344670945l/12743473.jpg", status: "read", rating: 4, description: "Jonathan Gottschall draws on psychology, evolution and literary scholarship to argue that storytelling is a core adaptation that builds shared minds and social glue.", owned: false },
    { title: "Give and Take: A Revolutionary Approach to Success", author: "Adam M. Grant", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1356136579l/16158498.jpg", status: "read", rating: 4, description: "For generations, we have focused on the individual drivers of success: passion, hard work, talent, and luck. But in today's dramatically reconfigured world, success is increasingly dependent on how we interact with others. This book illuminates what effective networking, collaboration, influence, negotiation, and leadership skills have in common. The author examines the surprising forces that shape why some people rise to the top of the success ladder while others sink to the bottom. In professional interactions, it turns out that most people operate as either takers, matchers, or givers. Whereas takers strive to get as much as possible from others and matchers aim to trade evenly, givers are the rare breed of people who contribute to others without expecting anything in return. Using his own studies, the author reveals that these styles have a dramatic impact on success. Although some givers get exploited and burn out, the rest achieve extraordinary results across a wide range of industries. Combining evidence with stories, this book shows how one of America's best networkers developed his connections; why the creative genius behind one of the most popular shows in television hist", owned: false },
    { title: "Entangled Life: How Fungi Make Our Worlds, Change Our Minds & Shape Our Futures", author: "Merlin Sheldrake", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1575341220l/52668915.jpg", status: "read", rating: 5, description: "\"Living at the border between life and non-life, fungi use diverse cocktails of potent enzymes and acids to disassemble some of the most stubborn substances on the planet, turning rock into soil and wood into compost, allowing plants to grow. Fungi not only help create soil, they send out networks of tubes that enmesh roots and link plants together in the 'Wood Wide Web.' Fungi also drive many long-standing human fascinations: from yeasts that cause bread to rise and orchestrate the fermentation of sugar into alcohol; to psychedelic fungi; to the mold that produces penicillin and revolutionized modern medicine. And we can partner with fungi to heal the damage we've done to the planet. Fungi are already being used to make sustainable building materials and wearable leather, but they can do so much more. Fungi can digest many stubborn and toxic pollutants from crude oil to human-made polyurethane plastics and the explosive TNT. They can grow food from renewable sources: edible mushrooms can be grown on anything from plant waste to cigarette butts. And some fungi's antiviral compounds might be able to ease the colony collapse of bees. Merlin Sheldrake's revelatory introduction to this", owned: false },
    { title: "Speaking Peace: Connecting with Others Through Non-Violent Communication", author: "Marshall B. Rosenberg", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1347415591l/560818.jpg", status: "read", rating: 5, description: "Marshall Rosenberg's audiobook companion to his Nonviolent Communication practice: how to translate observations, feelings, needs and requests into language that avoids reactivity.", owned: false },
    { title: "The Fires of Heaven", author: "Robert Jordan", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1327866286l/13895.jpg", status: "read", rating: 5, description: "The bonds and wards that hold the Great Lord of the Dark are slowly failing, but still his fragile prison holds. The Forsaken, immortal servants of the shadow, weave their snares and tighten their grip upon the realms of men, sure in the knowledge that their master will soon break free...\nRand al' Thor, the Dragon Reborn, knows that he must strike at the Enemy, but his forces are divided by treachery and by ambition. Even the Aes Sedai, ancient guardians of the Light, are riven by civil war. Betrayed by his allies, pursued by his enemies and beset by the madness that comes to the male wielders of the One Power, Rand rides out to meet the foe.", owned: false },
    { title: "The Shadow Rising", author: "Robert Jordan", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1638239837l/9539.jpg", status: "read", rating: 5, description: "The Wheel of Time turns and Ages come and go, leaving memories that become legend. Legend fades to myth, and even myth is long forgotten when the Age that gave it birth returns again. In the Third Age, an Age of Prophecy, the World and Time themselves hang in the balance. What was, what will be, and what is, may yet fall under the Shadow.\nThe seals of Shayol Ghul are weak now, and the Dark One reaches out. The Shadow is rising to cover humankind.\nIn Tar Valon, Min sees portents of hideous doom. Will the White Tower itself be broken?\nIn the Two Rivers, the Whitecloaks ride in pursuit of a man with golden eyes, and in pursuit of the Dragon Reborn.\nIn Cantorin, among the Sea Folk, High Lady Suroth plans the return of the Seanchan armies to the mainland.\nIn the Stone of Tear, the Lord Dragon considers his next move. It will be something no one expects, not the Black Ajah, not Tairen nobles, not Aes Sedai, not Egwene or Elayne or Nynaeve.\nAgainst the Shadow rising stands the Dragon Reborn...", owned: false },
    { title: "Mastery", author: "Robert Greene", category: "Autoayuda", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1348274726l/13589182.jpg", status: "read", rating: 5, description: "Robert Greene, the \"modern Machiavelli\" debunks the prevailing mythology of success and presents a radical new way to greatness.", owned: false },
    { title: "Friends: Understanding the Power of our Most Important Relationships", author: "Robin I.M. Dunbar", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1611983671l/56883977.jpg", status: "read", rating: 4, description: "Robin Dunbar synthesizes decades of his own research on the size, structure and biology of friendship circles, including the famous Dunbar number.", owned: false },
    { title: "HBR's 10 Must Reads on Strategy", author: "Michael E. Porter", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1344703931l/9612515.jpg", status: "read", rating: 4, description: "Anthology of canonical Harvard Business Review essays on strategy — Porter on five forces, Kim and Mauborgne on blue oceans, Christensen on disruption — plus newer pieces on execution.", owned: false },
    { title: "Proust and the Squid: The Story and Science of the Reading Brain", author: "Maryanne Wolf", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1338486201l/289751.jpg", status: "read", rating: 5, description: "Cognitive scientist Maryanne Wolf traces the cultural history and neural basis of reading, and warns that the digital reading habit may be quietly rewiring the brain.", owned: false },
    { title: "The Drunkard's Walk: How Randomness Rules Our Lives", author: "Leonard Mlodinow", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1320392907l/2272880.jpg", status: "read", rating: 4, description: "In this irreverent and illuminating book, acclaimed writer and scientist Leonard Mlodinow shows us how randomness, change, and probability reveal a tremendous amount about our daily lives, and how we misunderstand the significance of everything from a casual conversation to a major financial setback.  As a result, successes and failures in life are often attributed to clear and obvious cases, when in actuality they are more profoundly influenced by chance.The rise and fall of your favorite movie star of the most reviled CEO--in fact, of all our destinies--reflects as much as planning and innate abilities.  Even the legendary Roger Maris, who beat Babe Ruth's single-season home run record, was in all likelihood not great but just lucky.  And it might be shocking to realize that you are twice as likely to be killed in a car accident on your way to buying a lottery ticket than you are to win the lottery.How could it have happened that a wine was given five out of five stars, the highest rating, in one journal and in another it was called the worst wine of the decade? Mlodinow vividly demonstrates how wine ratings, school grades, political polls, and many other things in daily life are", owned: false },
    { title: "Behave: The Biology of Humans at Our Best and Worst", author: "Robert M. Sapolsky", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1517732866l/31170723.jpg", status: "read", rating: 5, description: "Why do we do the things we do?\n\nOver a decade in the making, this game-changing book is Robert Sapolsky's genre-shattering attempt to answer that question as fully as perhaps only he could, looking at it from every angle. Sapolsky's storytelling concept is delightful but it also has a powerful intrinsic logic: he starts by looking at the factors that bear on a person's reaction in the precise moment a behavior occurs, and then hops back in time from there, in stages, ultimately ending up at the deep history of our species and its genetic inheritance.\n\nAnd so the first category of explanation is the neurobiological one. What goes on in a person's brain a second before the behavior happens? Then he pulls out to a slightly larger field of vision, a little earlier in time: What sight, sound, or smell triggers the nervous system to produce that behavior? And then, what hormones act hours to days earlier to change how responsive that individual is to the stimuli which trigger the nervous system? By now, he has increased our field of vision so that we are thinking about neurobiology and the sensory world of our environment and endocrinology in trying to explain what happened.\n\nSapolsky ke", owned: false },
    { title: "Will", author: "Will  Smith", category: "Biografía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1624126289l/58375739.jpg", status: "read", rating: 5, description: "Memoir by Will Smith, written with Mark Manson: from a difficult West Philadelphia childhood to The Fresh Prince, blockbuster fame, marriage and the personal reckonings that followed.", owned: false },
    { title: "Humankind: A Hopeful History", author: "Rutger Bregman", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1577251406l/52879286.jpg", status: "read", rating: 5, description: "Historian Rutger Bregman revisits famous experiments in cruelty and obedience and finds them flawed; he argues that humans are, by default, decent, and that institutions should be redesigned with that assumption.", owned: false },
    { title: "The Dragon Reborn", author: "Robert Jordan", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1659905781l/34897.jpg", status: "read", rating: 5, description: "The Dragon Reborn—the leader long prophesied who will save the world, but in the saving destroy it; the savior who will run mad and kill all those dearest to him—is on the run from his destiny.\n\nAble to touch the One Power, but unable to control it, and with no one to teach him how—for no man has done it in three thousand years—Rand al'Thor knows only that he must face the Dark One. But how?\n\nWinter has stopped the war—almost—yet men are dying, calling out for the Dragon. But where is he?\n\nPerrin Aybara is in pursuit with Moiraine Sedai, her Warder Lan, and Loial the Ogier. Bedeviled by dreams, Perrin is grappling with another deadly problem—how is he to escape the loss of his own humanity?\n\nEgwene, Elayne and Nynaeve are approaching Tar Valon, where Mat will be healed—if he lives until they arrive. But who will tell the Amyrlin their news—that the Black Ajah, long thought only a hideous rumor, is all too real? They cannot know that in Tar Valon far worse awaits...\n\nAhead, for all of them, in the Heart of the Stone, lies the next great test of the Dragon reborn....", owned: false },
    { title: "The Design of Everyday Things", author: "Donald A. Norman", category: "Arte", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1442460745l/840.jpg", status: "read", rating: 5, description: "Donald Norman's classic on user-centered design: why doors push when they should pull, and what good affordances, mappings and feedback look like in physical and digital objects.", owned: false },
    { title: "The Psychology of Money: Timeless Lessons on Wealth, Greed, and Happiness", author: "Morgan Housel", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1581527774l/41881472.jpg", status: "read", rating: 5, description: "Timeless lessons on wealth, greed, and happiness doing well with money isn’t necessarily about what you know. It’s about how you behave. And behavior is hard to teach, even to really smart people. How to manage money, invest it, and make business decisions are typically considered to involve a lot of mathematical calculations, where data and formulae tell us exactly what to do. But in the real world, people don’t make financial decisions on a spreadsheet. They make them at the dinner table, or in a meeting room, where personal history, your unique view of the world, ego, pride, marketing, and odd incentives are scrambled together. In the psychology of money, the author shares 19 short stories exploring the strange ways people think about money and teaches you how to make better sense of one of life’s most important matters. [**The Psychology Of Money pdf**](https://chesserresources.com/doc/the-psychology-of-money-by-morgan-housel/)", owned: false },
    { title: "A Crack in Creation: Gene Editing and the Unthinkable Power to Control Evolution", author: "Jennifer A. Doudna", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1474820838l/30971755.jpg", status: "read", rating: 4, description: "**A trailblazing biologist grapples with her role in the biggest scientific discovery of our era: a cheap, easy way of rewriting genetic code, with nearly limitless promise and peril.**\n\nNot since the atomic bomb has a technology so alarmed its inventors that they warned the world about its use. Not, that is, until the spring of 2015, when biologist Jennifer Doudna called for a worldwide moratorium on the use of the new gene-editing tool CRISPR—a revolutionary new technology that she helped create—to make heritable changes in human embryos. The cheapest, simplest, most effective way of manipulating DNA ever known, CRISPR may well give us the cure to HIV, genetic diseases, and some cancers, and will help address the world’s hunger crisis. Yet even the tiniest changes to DNA could have myriad, unforeseeable consequences—to say nothing of the ethical and societal repercussions of intentionally mutating embryos to create “better” humans.\n \nWriting with fellow researcher Samuel Sternberg, Doudna shares the thrilling story of her discovery, and passionately argues that enormous responsibility comes with the ability to rewrite the code of life. With CRISPR, she shows, we have effectively ", owned: false },
    { title: "The Great Hunt", author: "Robert Jordan", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1659905799l/233649.jpg", status: "read", rating: 5, description: "Now in development for TV!\n\nSince its debut in 1990, The Wheel of Time® by Robert Jordan has captivated millions of readers around the globe with its scope, originality, and compelling characters.\n\nThe Wheel of Time turns and Ages come and go, leaving memories that become legend. Legend fades to myth, and even myth is long forgotten when the Age that gave it birth returns again. In the Third Age, an Age of Prophecy, the World and Time themselves hang in the balance. What was, what will be, and what is, may yet fall under the Shadow.\n\nFor centuries, gleemen have told the tales of The Great Hunt of the Horn. So many tales about each of th Hunters, and so many Hunters to tell of...Now the Horn itself is found: the Horn of Valere long thought only legend, the Horn which will raise the dead heroes of the ages. And it is stolen.\n\nTV series update: \"Sony will produce along with Red Eagle Entertainment and Radar Pictures. Rafe Judkins is attached to write and executive produce. Judkins previously worked on shows such as ABC’s “Agents of SHIELD,” the Netflix series “Hemlock Grove,” and the NBC series “Chuck.” Red Eagle partners Rick Selvage and Larry Mondragon will executive produce along w", owned: false },
    { title: "Numbers Don't Lie: 71 Things You Need to Know About the World", author: "Vaclav Smil", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1666542864l/50705179.jpg", status: "read", rating: 5, description: "Vaclav Smil compiles seventy-one short data essays on energy, food, transport, environment and human well-being, written as antidotes to lazy claims about the modern world.", owned: false },
    { title: "The Eye of the World", author: "Robert Jordan", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1659905815l/228665.jpg", status: "read", rating: 5, description: "The Wheel of Time turns and Ages come and go, leaving memories that become legend. Legend fades to myth, and even myth is long forgotten when the Age that gave it birth returns again. In the Third Age, an Age of Prophecy, the World and Time themselves hang in the balance. What was, what will be, and what is, may yet fall under the Shadow.", owned: false },
    { title: "Evolution for Everyone: How Darwin's Theory Can Change the Way We Think About Our Lives", author: "David Sloan Wilson", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1320436409l/159062.jpg", status: "read", rating: 5, description: "Biologist David Sloan Wilson argues that evolutionary thinking belongs in every classroom and shows what it can offer disciplines as different as economics, religion and parenting.", owned: false },
    { title: "Models: Attract Women Through Honesty", author: "Mark Manson", category: "Autoayuda", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1375568311l/12633800.jpg", status: "read", rating: 5, description: "Models is a book on becoming an attractive man. But it does not promote tricks, techniques, and tactics to manipulate the laws of attraction. Instead, Manson encourages men to partake in self-development to attract women in an honest way.", owned: false },
    { title: "Good Economics for Hard Times: Better Answers to Our Biggest Problems", author: "Abhijit V. Banerjee", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1562348201l/51014619.jpg", status: "read", rating: 5, description: "Figuring out how to deal with today's critical economic problems is perhaps the great challenge of our time. Much greater than space travel or perhaps even the next revolutionary medical breakthrough, what is at stake is the whole idea of the good life as we have known it.", owned: false },
    { title: "The Truth About Trust: How It Determines Success in Life, Love, Learning, and More", author: "David  DeSteno", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1374638765l/18114085.jpg", status: "read", rating: 3, description: "Draws on the latest research from a diverse range of fields to consider the role of trust in success, failure, and overall well-being, discussing how to recognize cues in order to discern the trustworthiness of others.", owned: false },
    { title: "Ego Is the Enemy", author: "Ryan Holiday", category: "Autoayuda", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1459114043l/27036528.jpg", status: "read", rating: 4, description: "Many of us insist the main impediment to a full, successful life is the outside world. In fact, the most common enemy lies within: our ego. Early in our careers, it impedes learning and the cultivation of talent. With success, it can blind us to our faults and sow future problems. In failure, it magnifies each blow and makes recovery more difficult. At every stage, ego holds us back. Ego Is the Enemy draws on a vast array of stories and examples, from literature to philosophy to history. We meet fascinating figures such as George Marshall, Jackie Robinson, Katharine Graham, Bill Belichick, and Eleanor Roosevelt, who all reached the highest levels of power and success by conquering their own egos. Their strategies and tactics can be ours as well. In an era that glorifies social media, reality TV, and other forms of shameless self-promotion, the battle against ego must be fought on many fronts. Armed with the lessons in this book, as Holiday writes, \"you will be less invested in the story you tell about your own specialness, and as a result, you will be liberated to accomplish the world-changing work you've set out to achieve.\"--", owned: false },
    { title: "Conformity: The Power of Social Influences", author: "Cass R. Sunstein", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1557572989l/42832291.jpg", status: "read", rating: 4, description: "Cass Sunstein synthesizes social-psychology research on how groups generate conformity, polarization and group-think, and draws institutional lessons for committees, juries and democracies.", owned: false },
    { title: "What We Owe Each Other: A New Social Contract for a Better Society", author: "Minouche Shafik", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1613414340l/56213211.jpg", status: "read", rating: 4, description: "Economist Minouche Shafik proposes a renewed social contract that strengthens collective insurance from cradle to grave while preserving individual responsibility and political legitimacy.", owned: false },
    { title: "Collapse: How Societies Choose to Fail or Succeed", author: "Jared Diamond", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1441419222l/475.jpg", status: "read", rating: 4, description: "\"In his Pulitzer Prize-winning bestseller Guns, Germs, and Steel, Jared Diamond examined how and why Western civilizations developed the technologies and immunities that allowed them to dominate much of the world. Now, Diamond probes the other side of the equation: What caused some of the great civilizations of the past to collapse into ruin, and what can we learn from their fates?\" \"As in Guns, Germs, and Steel, Diamond weaves an all-encompassing global thesis through a series of historical-cultural narratives. Moving from the prehistoric Polynesian culture on Easter Island to the formerly flourishing Native American civilizations of the Anasazi and the Maya, the doomed medieval Viking colony on Greenland, and finally to the modern world, Diamond traces a fundamental pattern of catastrophe, spelling out what happens when we squander our resources, when we ignore the signals our environment gives us, and when we reproduce too fast or cut down too many trees. Environmental damage, climate change, rapid population growth, unstable trade partners, and pressure from enemies were all factors in the demise of the doomed societies, but other societies found solutions to those same problem", owned: false },
    { title: "Blockchain Chicken Farm: And Other Stories of Tech in China's Countryside", author: "Xiaowei Wang", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1585632441l/50403472.jpg", status: "read", rating: 5, description: "In Blockchain Chicken Farm, the technologist and writer Xiaowei Wang explores the political and social entanglements of technology in rural China. Their discoveries force them to challenge the standard idea that rural culture and people are backward, conservative, and intolerant. Instead, they find that rural China has not only adapted to rapid globalization but has actually innovated the technology we all use today.\n\nFrom pork farmers using AI to produce the perfect pig, to disruptive luxury counterfeits and the political intersections of e-commerce villages, Wang unravels the ties between globalization, technology, agriculture, and commerce in unprecedented fashion. Accompanied by humorous “Sinofuturist” recipes that frame meals as they transform under new technology, Blockchain Chicken Farm is an original and probing look into innovation, connectivity, and collaboration in the digitized rural world.", owned: false },
    { title: "The Social Instinct: How Cooperation Shaped the World", author: "Nichola Raihani", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1621844547l/56269229.jpg", status: "read", rating: 4, description: "Evolutionary biologist Nichola Raihani explains why cooperation evolves, where it breaks down, and what the answers imply for everything from fish-cleaning stations to climate negotiations.", owned: false },
    { title: "Ingredients: The Strange Chemistry of What We Put in Us and on Us", author: "George Zaidan", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1574355997l/48822623.jpg", status: "read", rating: 5, description: "Chemist George Zaidan untangles food labels, cosmetics and the everyday chemistry behind processed products, and pushes back against both blanket panic and blanket reassurance.", owned: false },
    { title: "The Demon-Haunted World: Science as a Candle in the Dark", author: "Carl Sagan", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1553691804l/17349.jpg", status: "read", rating: 5, description: "A prescient warning of a future we now inhabit, where fake news stories and Internet conspiracy theories play to a disaffected American populace\n\n“A glorious book . . . A spirited defense of science . . . From the first page to the last, this book is a manifesto for clear thought.”—Los Angeles Times\n\nHow can we make intelligent decisions about our increasingly technology-driven lives if we don’t understand the difference between the myths of pseudoscience and the testable hypotheses of science? Pulitzer Prize-winning author and distinguished astronomer Carl Sagan argues that scientific thinking is critical not only to the pursuit of truth but to the very well-being of our democratic institutions.\n\nCasting a wide net through history and culture, Sagan examines and authoritatively debunks such celebrated fallacies of the past as witchcraft, faith healing, demons, and UFOs. And yet, disturbingly, in today's so-called information age, pseudoscience is burgeoning with stories of alien abduction, channeling past lives, and communal hallucinations commanding growing attention and respect. As Sagan demonstrates with lucid eloquence, the siren song of unreason is not just a cultural wrong t", owned: false },
    { title: "Everybody Lies: Big Data, New Data, and What the Internet Can Tell Us About Who We Really Are", author: "Seth Stephens-Davidowitz", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1489069766l/28512671.jpg", status: "read", rating: 4, description: "A former Google data scientist presents an insider's look at what the vast, instantly available amounts of information from the Internet can reveal about human civilization and society.", owned: false },
    { title: "The Upside of Irrationality: The Unexpected Benefits of Defying Logic at Work and at Home", author: "Dan Ariely", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1268511997l/7815744.jpg", status: "read", rating: 4, description: "Behavioral economist Dan Ariely's follow-up to Predictably Irrational: experiments showing how emotions, motivation and adaptation distort and sometimes enrich our decisions at work and at home.", owned: false },
    { title: "Noise: A Flaw in Human Judgment", author: "Daniel Kahneman", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1617709587l/55339408.jpg", status: "read", rating: 5, description: "Kahneman, Sibony and Sunstein identify «noise» — random variability in expert judgment, from doctors to judges to forecasters — as a costly twin of bias, and propose techniques to reduce it.", owned: false },
    { title: "Complexity: The Emerging Science at the Edge of Order and Chaos", author: "M. Mitchell Waldrop", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1405259833l/337123.jpg", status: "read", rating: 5, description: "\"In a rented convent in Santa Fe, a revolution has been brewing. The activists are not anarchists, but rather Nobel Laureates in physics and economics such as Murray Gell-Mann and Kenneth Arrow, and pony-tailed graduate students, mathematicians, and computer scientists down from Los Alamos. They've formed an iconoclastic think tank called the Santa Fe Institute, and their radical idea is to create a new science called complexity.\" \"These mavericks from academe share a deep impatience with the kind of linear, reductionist thinking that has dominated science since the time of Newton. Instead, they are gathering novel ideas about interconnectedness, coevolution, chaos, structure, and order - and they're forging them into an entirely new, unified way of thinking about nature, human social behavior, life, and the universe itself.\" \"They want to know how a primordial soup of simple molecules managed to turn itself into the first living cell - and what the origin of life some four billion years ago can tell us about the process of technological innovation today. They want to know why ancient ecosystems often remained stable for millions of years, only to vanish in a geological instant - a", owned: false },
    { title: "Purple Cow: Transform Your Business by Being Remarkable", author: "Seth Godin", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1309203098l/641604.jpg", status: "read", rating: 4, description: "208 p. : 21 cm", owned: false },
    { title: "Science Fictions: How Fraud, Bias, Incompetence, and Hype Undermine the Search for Truth", author: "Stuart Ritchie", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1580203662l/52079565.jpg", status: "read", rating: 5, description: "Science is how we understand the world. Yet critical flaws in peer review, statistical methods, and publication procedures have rendered a shocking number of scientific studies useless-or worse, badly misleading. Drawing on surprising new data from \"meta-science\" (the science of how science works), Science Fictions documents the errors that have distorted our knowledge on issues as varied as cancer biology, nutrition, genetics, immigration, education, and extraterrestrial life. Stuart Ritchie's own work challenging an infamous psychology experiment helped spark what's now widely known as the \"replication crisis,\" the realization that many supposed scientific truths cannot be relied upon. Now, he reveals the very human biases, mistakes, and deceptions that undermine the scientific endeavor: from contamination in science labs to the secret vaults of failed studies that nobody gets to see; from outright cheating with fake data to the more common but still ruinous temptation to exaggerate mediocre results for a shot at scientific fame. Yet Science Fictions is far from a counsel of despair. Rather, it's a defense of the scientific method against the pressures and perverse incentives tha", owned: false },
    { title: "The Sports Gene: Inside the Science of Extraordinary Athletic Performance", author: "David   Epstein", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1378677673l/16171221.jpg", status: "read", rating: 4, description: "This book explores the roles of both genetics and training in athletic success, arguing that both are equally necessary components of athletic achievement while considering such topics as race, gender, and genetic testing.We all knew a star athlete in high school. The one who made it look so easy. He was the starting quarterback and shortstop; she was the all-state point guard and high-jumper. Naturals. Or were they? The debate is as old as physical competition. Are stars like Usain Bolt, Michael Phelps, and Serena Williams genetic freaks put on Earth to dominate their respective sports? Or are they simply normal people who overcame their biological limits through sheer force of will and obsessive training? The truth is far messier than a simple dichotomy between nature and nurture. In the decade since the sequencing of the human genome, researchers have slowly begun to uncover how the relationship between biological endowments and a competitor's training environment affects athleticism. Sports scientists have gradually entered the era of modern genetic research. In this exploration of athletic success, the author, a senior writer at Sports Illustrated magazine tackles the great na", owned: false },
    { title: "SPIN Selling: Situation Problem Implication Need-payoff", author: "Neil Rackham", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1433591836l/833015.jpg", status: "read", rating: 3, description: "Neil Rackham's research-based framework for high-value consultative selling: ask Situation, Problem, Implication and Need-payoff questions to lead buyers to articulate their needs.", owned: false },
    { title: "The Ride of a Lifetime: Lessons Learned from 15 Years as CEO of the Walt Disney Company", author: "Robert Iger", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1556036622l/44525305.jpg", status: "read", rating: 5, description: "Robert Iger shares the lessons he's learned while running Disney and leading its 200,000 employees, and he explores the principles that are necessary for true leadership.\n\nIger became CEO of the Walt Disney Company in 2005, during a difficult time. His vision for the future came down to three ideas: Recommit to the concept that quality matters; Embrace technology instead of fighting it; and Think bigger-- think globally. Here he shares the lessons he's learned while running Disney, and explores the principles that are necessary for true leadership. -- adapted from jacket", owned: false },
    { title: "The New Corporation: How \"Good\" Corporations Are Bad for Democracy", author: "Joel Bakan", category: "Política", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1590444239l/52487931.jpg", status: "read", rating: 4, description: "Joel Bakan's sequel to The Corporation argues that corporate social responsibility has become a sophisticated branding strategy that masks the same old extraction.", owned: false },
    { title: "Green Swans: The Coming Boom In Regenerative Capitalism", author: "John Elkington", category: "Desarrollo y sostenibilidad", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1585943210l/52919387.jpg", status: "read", rating: 5, description: "Sustainability strategist John Elkington proposes «green swans» as positive exponential shifts that, with the right design, could turn industries regenerative within a generation.", owned: false },
    { title: "The Structure of Scientific Revolutions", author: "Thomas S. Kuhn", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1396422530l/61539.jpg", status: "read", rating: 4, description: "Thomas S. Kuhn's classic book is now available with a new index.", owned: false },
    { title: "Looking for Alaska", author: "John  Green", category: "Novela juvenil", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1652042180l/99561.jpg", status: "read", rating: 5, description: "Before. Miles “Pudge” Halter is done with his safe life at home. His whole life has been one big non-event, and his obsession with famous last words has only made him crave “the Great Perhaps” even more (Francois Rabelais, poet). He heads off to the sometimes crazy and anything-but-boring world of Culver Creek Boarding School, and his life becomes the opposite of safe. Because down the hall is Alaska Young. The gorgeous, clever, funny, sexy, self-destructive, screwed up, and utterly fascinating Alaska Young. She is an event unto herself. She pulls Pudge into her world, launches him into the Great Perhaps, and steals his heart. Then. . . .\n \nAfter. *Nothing is ever the same.*", owned: false },
    { title: "Business Model Generation", author: "Alexander Osterwalder", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1384676138l/7723797.jpg", status: "read", rating: 4, description: "Alex Osterwalder and Yves Pigneur's illustrated workbook for designing, testing and pivoting business models using the now-ubiquitous Business Model Canvas.", owned: false },
    { title: "Ripper", author: "Isabel Allende", category: "Misterio", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1422871316l/18090150.jpg", status: "read", rating: 4, description: "Mystery novel set in present-day San Francisco. Amanda, a teenage member of an online role-playing game called Ripper, draws her detective stepfather into a string of grisly murders that may be connected to her own mother's disappearance and to a darker pattern stretching back decades. The plot weaves family secrets, esoteric clues and gamer culture into a procedural with the texture of a magical-realist family saga.", descriptionAi: true, owned: false },
    { title: "Freakonomics: A Rogue Economist Explores the Hidden Side of Everything", author: "Steven D. Levitt", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1550917827l/1202.jpg", status: "read", rating: 4, description: "Economist Steven Levitt and journalist Stephen Dubner apply microeconomic tools to sumo wrestlers, drug dealers and real-estate agents, popularizing a whole genre of pop-data writing.", owned: false },
    { title: "Peter Pan in Scarlet", author: "Geraldine McCaughrean", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1388340899l/34264.jpg", status: "read", description: "In the 1930s, all is not well. Nightmares are leaking out of Neverland. Fearing for Peter Pan's life, Wendy and the Lost Boys go back to Neverland -- with the help of the fairy Fireflyer -- only to discover their worst nightmares coming true! Peter Pan and his friends eventually restore Neverland to rights.", owned: false },
    { title: "The Alchemist", author: "Paulo Coelho", category: "Novela clásica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1483412266l/865.jpg", status: "read", rating: 3, description: "Offers an adaptation in graphic novel format of a modern classic about the globe-trotting spiritual journey of a humble shepherd boy.", owned: false },
    { title: "Turtles All the Way Down", author: "John  Green", category: "Novela juvenil", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1503002776l/35504431.jpg", status: "read", rating: 4, description: "**SIXTEEN-YEAR-OLD AZA NEVER INTENDED** to pursue the mystery of fugitive billionaire Russell Pickett, but there's a hundred-thousand-dollar reward at sake and  her Best and Most Fearless Friend, Daisy, is eager to investigate. So together, they navigate the short distance and broad divides that separate them from Russell Pickett's son, Davis.\n\nAza is trying. She is trying to be a good daughter, a good friend, a good student, and maybe even a good detective, while also living within the ever-tightening spiral of her own thoughts.\n\nIn his long-awaited return, John Green, the acclaimed, award-winning author of *Looking for Alaska* and *The Fault in Our Stars*, shares Aza's story with shattering, unflinching clarity in this brilliant novel of love, resilience, and the power of lifelong friendship.\n\nThis description comes from the publisher.", owned: false },
    { title: "The End of Power: From Boardrooms to Battlefields and Churches to States, Why Being In Charge Isn't What It Used to Be", author: "Moisés Naím", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1350395884l/16043519.jpg", status: "read", rating: 4, description: "Argues that the leaders of today actually have less power than ever before, discussing the changing nature of leadership and the modern dynamics of power.\n\n\"In The End of Power, award-winning columnist and former Foreign Policy editor Moisés Naím illuminates the struggle between once-dominant megaplayers and the new micropowers challenging them in every field of human endeavor. Drawing on provocative, original research, Naím shows how the antiestablishment drive of micropowers can topple tyrants, dislodge monopolies, and open remarkable new opportunities, but it can also lead to chaos and paralysis. Naím deftly covers the seismic changes underway in business, religion, education, within families, and in all matters of war and peace. Examples abound in all walks of life: In 1977, eighty-nine countries were ruled by autocrats while today more than half the world's population lives in democracies. CEO's are more constrained and have shorter tenures than their predecessors. Modern tools of war, cheaper and more accessible, make it possible for groups like Hezbollah to afford their own drones. In the second half of 2010, the top ten hedge funds earned more than the world's largest six b", owned: false },
    { title: "Harry Potter and the Sorcerer's Stone", author: "J.K. Rowling", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1474154022l/3.jpg", status: "read", rating: 4, description: "J.K. Rowling's first novel: orphan Harry discovers he is a wizard, leaves the Dursleys for Hogwarts and confronts the dark wizard who killed his parents.", owned: false },
    { title: "Harry Potter and the Chamber of Secrets", author: "J.K. Rowling", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1474169725l/15881.jpg", status: "read", rating: 4, description: "Throughout the summer holidays after his first year at Hogwarts School of Witchcraft and Wizardry, Harry Potter has been receiving sinister warnings from a house-elf called Dobby.\n\nNow, back at school to start his second year, Harry hears unintelligible whispers echoing through the corridors.\n\nBefore long the attacks begin: students are found as if turned to stone.\n\nDobby’s predictions seem to be coming true.\n\n[Source](https://chesserresources.com/doc/harry-potter-and-the-chamber-of-secrets-pdf/)", owned: false },
    { title: "Harry Potter and the Prisoner of Azkaban", author: "J.K. Rowling", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1630547330l/5.jpg", status: "read", rating: 5, description: "For Harry Potter, it’s the start of another far-from-ordinary year at Hogwarts when the Knight Bus crashes through the darkness and comes to an abrupt halt in front of him.\n\nIt turns out that Sirius Black, mass-murderer and follower of Lord Voldemort, has escaped – and they say he is coming after Harry.\n\nIn his first Divination class, Professor Trelawney sees an omen of death in Harry’s tea leaves.\n\nAnd perhaps most frightening of all are the Dementors patrolling the school grounds with their soul-sucking kiss – in search of fresh victims.", owned: false },
    { title: "Harry Potter and the Goblet of Fire", author: "J.K. Rowling", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1554006152l/6.jpg", status: "read", rating: 4, description: "The fourth book in the Harry Potter franchise sees Harry returning for his fourth year at Hogwarts School of Witchcraft and Wizardry, along with his friends, Ron and Hermione . There is an upcoming tournament between the three major schools of magic, with one participant selected from each school by the Goblet of Fire. When Harry's name is drawn, even though he is not eligible and is a fourth player, he must compete in the dangerous contest.\n\nContains:\n\n - [Harry Potter and the Goblet of Fire. 2/4](https://openlibrary.org/works/OL17910198W/Harry_Potter_and_the_Goblet_of_Fire._2_4)", owned: false },
    { title: "Harry Potter and the Order of the Phoenix", author: "J.K. Rowling", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1546910265l/2.jpg", status: "read", rating: 5, description: "After the Dementors’ attack on his cousin Dudley, Harry knows he is about to become Voldemort’s next target.\n\nAlthough many are denying the Dark Lord’s return, Harry is not alone, and a secret order is gathering at Grimmauld Place to fight against the Dark forces.\n\nMeanwhile, Voldemort’s savage assaults on Harry’s mind are growing stronger every day.\n\nHe must allow Professor Snape to teach him to protect himself before he runs out of time.\n\nThis work has also been published in multiple volumes. See:\n\n - [Harry Potter and the Order of the Phoenix: III](https://openlibrary.org/works/OL17937113W/Harry_Potter_and_the_Order_of_the_Phoenix_Chapters_17-23)\n - [Harry Potter and the Order of the Phoenix: IV](https://openlibrary.org/works/OL17915213W/Harry_Potter_and_the_Order_of_the_Phoenix_Chapters_24-30)", owned: false },
    { title: "Harry Potter and the Half-Blood Prince", author: "J.K. Rowling", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1587697303l/1.jpg", status: "read", rating: 5, description: "One summer night, when Dumbledore arrives at Privet Drive to collect Harry Potter, his wand hand is blackened and shriveled, but he will not reveal why.\n\nRumours and suspicion spread through the wizarding world – it feels as if even Hogwarts itself might be under threat.\n\nHarry is convinced that Malfoy bears the Dark Mark: could there be a Death Eater amongst them?\n\nHe will need powerful magic and true friends as, with the help of Dumbledore, he investigates Voldemort’s darkest secrets.\n\nPreceded by: [Harry Potter and the Order of the Phoenix][1]\nFollowed by: [Harry Potter and the Deathly Hallows][3]\n\nContains:\n[Harry Potter and the Half-Blood Prince [3/4]](https://openlibrary.org/works/OL27299760W)\n[Harry Potter and the Half-Blood Prince [4/4]](https://openlibrary.org/works/OL27294904W)", owned: false },
    { title: "Harry Potter and the Deathly Hallows", author: "J.K. Rowling", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1663805647l/136251.jpg", status: "read", rating: 5, description: "Harry Potter is leaving Privet Drive for the last time. But as he climbs into the sidecar of Hagrid’s motorbike and they take to the skies, he knows Lord Voldemort and the Death Eaters will not be far behind.\n\nThe protective charm that has kept him safe until now is broken. But the Dark Lord is breathing fear into everything he loves. And he knows he can’t keep hiding.\n\nTo stop Voldemort, Harry knows he must find the remaining Horcruxes and destroy them.\n\nHe will have to face his enemy in one final battle.\n\nSee also:\n\n - [Harry Potter and the Deathly Hallows: 2/2][2]", owned: false },
    { title: "Guns, Germs, and Steel: The Fates of Human Societies", author: "Jared Diamond", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1453215833l/1842.jpg", status: "read", rating: 5, description: "An epic detective story that offers a gripping expose on why the world is so unequal. Professor Jared Diamond traveled the globe for over 30 years trying to answer this question.", owned: false },
    { title: "Scrum: The Art of Doing Twice the Work in Half the Time", author: "Jeff Sutherland", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1393221649l/19288230.jpg", status: "read", rating: 4, description: "Introduction to agile methodology written by co-developer Jeff Sutherland.", owned: false },
    { title: "Range: Why Generalists Triumph in a Specialized World", author: "David   Epstein", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1550048292l/41795733.jpg", status: "read", rating: 5, description: "What's the most effective path to success in any domain? It's not what you think. \n\nPlenty of experts argue that anyone who wants to develop a skill, play an instrument, or lead their field should start early, focus intensely, and rack up as many hours of deliberate practice as possible. If you dabble or delay, you'll never catch up to the people who got a head start. But a closer look at research on the world's top performers, from professional athletes to Nobel laureates, shows that early specialization is the exception, not the rule.\n\nDavid Epstein examined the world's most successful athletes, artists, musicians, inventors, forecasters and scientists. He discovered that in most fields--especially those that are complex and unpredictable--generalists, not specialists, are primed to excel. Generalists often find their path late, and they juggle many interests rather than focusing on one. They're also more creative, more agile, and able to make connections their more specialized peers can't see.\n\nProvocative, rigorous, and engrossing, *Range* makes a compelling case for actively cultivating inefficiency. Failing a test is the best way to learn. Frequent quitters end up with the mo", owned: false },
    { title: "Superforecasting: The Art and Science of Prediction", author: "Philip E. Tetlock", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1435684424l/23995360.jpg", status: "read", rating: 4, description: "Everyone would benefit from seeing further into the future, whether buying stocks, crafting policy, launching a new product, or simply planning the week’s meals. Unfortunately, people tend to be terrible forecasters. As Wharton professor Philip Tetlock showed in a landmark 2005 study, even experts’ predictions are only slightly better than chance. However, an important and underreported conclusion of that study was that some experts do have real foresight, and Tetlock has spent the past decade trying to figure out why. What makes some people so good? And can this talent be taught?\n \nIn Superforecasting, Tetlock and coauthor Dan Gardner offer a masterwork on prediction, drawing on decades of research and the results of a massive, government-funded forecasting tournament. The Good Judgment Project involves tens of thousands of ordinary people—including a Brooklyn filmmaker, a retired pipe installer, and a former ballroom dancer—who set out to forecast global events. Some of the volunteers have turned out to be astonishingly good. They’ve beaten other benchmarks, competitors, and prediction markets. They’ve even beaten the collective judgment of intelligence analysts with access to cl", owned: false },
    { title: "Zero to One: Notes on Startups, or How to Build the Future", author: "Peter Thiel", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1630663027l/18050143.jpg", status: "read", rating: 5, description: "If you want to build a better future, you must believe in secrets.\n\nThe great secret of our time is that there are still uncharted frontiers to explore and new inventions to create. In Zero to One , legendary entrepreneur and investor Peter Thiel shows how we can find singular ways to create those new things. \n\nThiel begins with the contrarian premise that we live in an age of technological stagnation, even if we’re too distracted by shiny mobile devices to notice. Information technology has improved rapidly, but there is no reason why progress should be limited to computers or Silicon Valley. Progress can be achieved in any industry or area of business. It comes from the most important skill that every leader must master: learning to think for yourself.\n\nDoing what someone else already knows how to do takes the world from 1 to n, adding more of something familiar. But when you do something new, you go from 0 to 1. The next Bill Gates will not build an operating system. The next Larry Page or Sergey Brin won’t make a search engine. Tomorrow’s champions will not win by competing ruthlessly in today’s marketplace. They will escape competition altogether, because their businesses will", owned: false },
    { title: "The Algebra of Happiness: Notes on the Pursuit of Success, Love, and Meaning", author: "Scott Galloway", category: "Autoayuda", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1553767026l/42872963.jpg", status: "read", rating: 4, description: "NYU professor Scott Galloway distills his lectures on career, money and relationships into short chapters of blunt, hard-won advice.", owned: false },
    { title: "Trust Me, I'm Lying: Confessions of a Media Manipulator", author: "Ryan Holiday", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1340124369l/13542853.jpg", status: "read", rating: 4, description: "You've seen it all before. A malicious online rumor costs a company millions. A political sideshow derails the national news cycle and destroys a candidate. Some product or celebrity zooms from total obscurity to viral sensation. What you don't know is that someone is responsible for all this. Usually, someone like me. \n\nI'm a media manipulator. In a world where blogs control and distort the news, my job is to control blogs-as much as any one person can. \n\nIn today's culture... \n1) Blogs like Gawker, Buzzfeed and the Huffington Post drive the media agenda. \n2) Bloggers are slaves to money, technology, and deadlines. \n3) Manipulators wield these levers to shape everything you read, see and watch-online and off. \n\nWhy am I giving away these secrets? Because I'm tired of a world where blogs take indirect bribes, marketers help write the news, reckless journalists spread lies, and no one is accountable for any of it. I'm pulling back the curtain because I don't want anyone else to get blindsided. \n\nI'm going to explain exactly how the media really works. What you choose to do with this information is up to you.\n\nFrom the Trade Paperback edition.", owned: false },
    { title: "Northern Lights", author: "Philip Pullman", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1327235223l/70947.jpg", status: "read", rating: 4, description: "In a landmark epic of fantasy and storytelling, Philip Pullman invites readers into a world as convincing and thoroughly realized as Narnia, Earthsea, or Redwall. Here lives an orphaned ward named Lyra Belacqua, whose carefree life among the scholars at Oxford's Jordan College is shattered by the arrival of two powerful visitors. First, her fearsome uncle, Lord Asriel, appears with evidence of mystery and danger in the far North, including photographs of a mysterious celestial phenomenon called Dust and the dim outline of a city suspended in the Aurora Borealis that he suspects is part of an alternate universe. He leaves Lyra in the care of Mrs. Coulter, an enigmatic scholar and explorer who offers to give Lyra the attention her uncle has long refused her. In this multilayered narrative, however, nothing is as it seems. Lyra sets out for the top of the world in search of her kidnapped playmate, Roger, bearing a rare truth-telling instrument, the compass of the title. All around her children are disappearing—victims of so-called \"Gobblers\"—and being used as subjects in terrible experiments that separate humans from their daemons, creatures that reflect each person's inner being. And", owned: false },
    { title: "The Subtle Knife", author: "Philip Pullman", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1535965085l/41637836.jpg", status: "read", rating: 4, description: "As the boundaries between worlds begin to dissolve, Lyra and her daemon help Will Parry in his search for his father and for a powerful, magical knife.\n\nShe had asked: What is he? A friend or an enemy?\n\nThe alethiometer answered: He is a murderer.\n\nWhen she saw the answer, she relaxed at once.\n\nLyra finds herself in a shimmering, haunted otherworld – Cittàgazze, where soul-eating Spectres stalk the streets and wingbeats of distant angels sound against the sky.\n\nBut she is not without allies: twelve-year-old Will Parry, fleeing for his life after taking another's, has also stumbled into this strange new realm.\n\nOn a perilous journey from world to world, Lyra and Will uncover a deadly secret: an object of extraordinary and devastating power.\n\nAnd with every step, they move closer to an even greater threat – and the shattering truth of their own destiny.", owned: false },
    { title: "Political Risk: How Businesses and Organizations Can Anticipate Global Insecurity", author: "Condoleezza Rice", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1646318146l/36589095.jpg", status: "read", rating: 5, description: "Condoleezza Rice and Amy Zegart describe how shifting geopolitics and reputational risk affect firms, and walk through a framework for managing it.", owned: false },
    { title: "How Not to Be Wrong: The Power of Mathematical Thinking", author: "Jordan Ellenberg", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1387726285l/18693884.jpg", status: "read", rating: 4, description: "Mathematician Jordan Ellenberg shows how mathematical reasoning illuminates everyday questions — lottery tickets, elections, slime molds — without requiring formal mathematics.", owned: false },
    { title: "The Creative Spark: How Imagination Made Humans Exceptional", author: "Agustín Fuentes", category: "Divulgación científica", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1475528465l/31626670.jpg", status: "read", rating: 5, description: "Overturns widely held misconceptions about race, war and peace, and human nature itself and asserts that creativity is what has made humans so exceptional among all the species on Earth. --Publisher.", owned: false },
    { title: "Every Tool's a Hammer: Life Is What You Make It", author: "Adam Savage", category: "Biografía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1555856209l/43319933.jpg", status: "read", rating: 3, description: "MythBusters host Adam Savage offers a personal manifesto on making, building and tinkering, full of practical advice and stories from his workshop.", owned: false },
    { title: "The Choice Factory: 25 behavioural biases that influence what we buy", author: "Richard Shotton", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1518390503l/38487327.jpg", status: "read", rating: 5, description: "\"By observing a typical day of decision-making, from trivial food choices to significant work-place moves, he investigates how our behavior is shaped by psychological shortcuts. With a clear focus on the marketing potential of knowing what makes us tick, Shotton has drawn on evidence from academia, real-life ad campaigns and his own original research\"--Back cover.", owned: false },
    { title: "Alchemy: The Surprising Power of Ideas That Don't Make Sense", author: "Rory Sutherland", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1549539347l/26210508.jpg", status: "read", rating: 5, description: "Companion edition of Rory Sutherland's Alchemy: the case for psycho-logic over arithmetic in marketing, policy and design.", owned: false },
    { title: "Pre-Suasion: A Revolutionary Way to Influence and Persuade", author: "Robert B. Cialdini", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1468786982l/29238799.jpg", status: "read", rating: 4, description: "The author of the legendary bestseller *Influence*, social psychologist Robert Cialdini shines a light on effective persuasion and reveals that the secret doesn’t lie in the message itself, but in the key moment before that message is delivered.\n\nWhat separates effective communicators from truly successful persuaders? Using the same combination of rigorous scientific research and accessibility that made his *Influence* an iconic bestseller, Robert Cialdini explains how to capitalize on the essential window of time before you deliver an important message. This “privileged moment for change” prepares people to be receptive to a message before they experience it. Optimal persuasion is achieved only through optimal pre-suasion. In other words, to change “minds” a pre-suader must also change “states of mind.”\n\nHis first solo work in over thirty years, Cialdini’s *Pre-Suasion* draws on his extensive experience as the most cited social psychologist of our time and explains the techniques a person should implement to become a master persuader. Altering a listener’s attitudes, beliefs, or experiences isn’t necessary, says Cialdini—all that’s required is for a communicator to redirect the au", owned: false },
    { title: "Social Engineering", author: "Christopher Hadnagy", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1349034191l/9068044.jpg", status: "read", rating: 4, description: "Examines what social engineering is, the methods used by hackers to gather information, and ways to prevent social engineering threats.", owned: false },
    { title: "Factfulness: Ten Reasons We're Wrong About the World – and Why Things Are Better Than You Think", author: "Hans Rosling", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1544963815l/34890015.jpg", status: "read", rating: 4, description: "Statistician Hans Rosling lists ten cognitive instincts that distort our view of global development and offers data-driven antidotes for thinking like a fact-based optimist.", owned: false },
    { title: "The Honest Truth About Dishonesty: How We Lie to Everyone - Especially Ourselves", author: "Dan Ariely", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1331070373l/13426114.jpg", status: "read", rating: 4, description: "The author, a behavioral economist challenges our preconceptions about dishonesty; we all cheat, whether it is copying a paper in the classroom, or white lies on our expense accounts. He explores how unethical behavior works in the personal, professional, and political worlds, and how it affects all of use, even as we think of ourselves as having high moral standards. He explores the question of dishonesty from Washington to Wall Street, and the classroom to the workplace, to examine why cheating is so prevalent and what can be done to prevent it.", owned: false },
    { title: "Understanding Michael Porter: The Essential Guide to Competition and Strategy", author: "Joan Magretta", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1334413319l/13263934.jpg", status: "read", rating: 5, description: "Joan Magretta, a longtime collaborator, summarizes Michael Porter's core ideas — five forces, generic strategies, value chain, positioning — in a short, lucid primer.", owned: false },
    { title: "Post Corona: From Crisis to Opportunity", author: "Scott Galloway", category: "Negocios", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1600733675l/55333978.jpg", status: "read", rating: 4, description: "Scott Galloway charts the winners and losers of the COVID-19 economy and argues for policy and business strategies to use the dislocation as an opening for reform.", owned: false },
    { title: "Traffic: Why We Drive the Way We Do and What It Says About Us", author: "Tom Vanderbilt", category: "Psicología", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1320428955l/2776527.jpg", status: "read", rating: 4, description: "A New York Times Notable BookOne of the Best Books of the YearThe Washington Post  - The Cleveland Plain-Dealer  - Rocky Mountain NewsIn this brilliant, lively, and eye-opening investigation, Tom Vanderbilt examines the perceptual limits and cognitive underpinnings that make us worse drivers than we think we are. He demonstrates why plans to protect pedestrians from cars often lead to more accidents. He uncovers who is more likely to honk at whom, and why. He explains why traffic jams form, outlines the unintended consequences of our quest for safety, and even identifies the most common mistake drivers make in parking lots. Traffic is about more than driving: it's about human nature. It will change the way we see ourselves and the world around us, and it may even make us better drivers.From the Trade Paperback edition.", owned: false },
    { title: "Sapiens: A Brief History of Humankind", author: "Yuval Noah Harari", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1703329310l/23692271.jpg", status: "read", rating: 5, description: "From a renowned historian comes a groundbreaking narrative of humanity’s creation and evolution—a #1 international bestseller—that explores the ways in which biology and history have defined us and enhanced our understanding of what it means to be “human.”\n\nOne hundred thousand years ago, at least six different species of humans inhabited Earth. Yet today there is only one—homo sapiens. What happened to the others? And what may happen to us?\n\nMost books about the history of humanity pursue either a historical or a biological approach, but Dr. Yuval Noah Harari breaks the mold with this highly original book that begins about 70,000 years ago with the appearance of modern cognition. From examining the role evolving humans have played in the global ecosystem to charting the rise of empires, Sapiens integrates history and science to reconsider accepted narratives, connect past developments with contemporary concerns, and examine specific events within the context of larger ideas.\n\nDr. Harari also compels us to look ahead, because over the last few decades humans have begun to bend laws of natural selection that have governed life for the past four billion years. We are acquiring the ab", owned: false },
    { title: "Homo Deus: A History of Tomorrow", author: "Yuval Noah Harari", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1468760805l/31138556.jpg", status: "read", rating: 5, description: "Yuval Noah Harari extends the project of Sapiens into the future, asking what becomes of humanism, freedom and meaning in an age of biotech, algorithms and dataism.", owned: false },
    { title: "21 Lessons for the 21st Century", author: "Yuval Noah Harari", category: "Historia", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1564577305l/38820046.jpg", status: "read", rating: 5, description: "In a world deluged by irrelevant information, clarity is power. Censorship works not by blocking the flow of information, but rather by flooding people with disinformation and distractions. 21 Lessons for the 21st Century cuts through these muddy waters and confronts some of the most urgent questions on today’s global agenda.\n\nWhy is liberal democracy in crisis? Is God back? Is a new world war coming? What does the rise of Donald Trump signify? What can we do about the epidemic of fake news? Which civilisation dominates the world – the West, China, Islam? Should Europe keep its doors open to immigrants? Can nationalism solve the problems of inequality and climate change? What should we do about terrorism? What should we teach our kids?\n\nBillions of us can hardly afford the luxury of investigating these questions, because we have more pressing things to do: we have to go to work, take care of the kids, or look after elderly parents. Unfortunately, history makes no concessions. If the future of humanity is decided in your absence, because you are too busy feeding and clothing your kids – you and they will not be exempt from the consequences. This is very unfair; but who said history ", owned: false },
    { title: "This is Marketing: You Can't Be Seen Until You Learn To See", author: "Seth Godin", category: "", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1529247040l/40549476.jpg", status: "read", rating: 5, description: "Seth Godin's compact statement of his marketing philosophy: serve the smallest viable audience, earn their trust, and let the work spread by being worth talking about.", owned: false },
    { title: "The Invisible Life of Addie LaRue", author: "V.E. Schwab", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1584633432l/50623864.jpg", status: "read", rating: 3, description: "France, 1714: in a moment of desperation, a young woman makes a Faustian bargain to live forever and is cursed to be forgotten by everyone she meets.\n\nThus begins the extraordinary life of Addie LaRue, and a dazzling adventure that will play out across centuries and continents, across history and art, as a young woman learns how far she will go to leave her mark on the world.\n\nBut everything changes when, after nearly 300 years, Addie stumbles across a young man in a hidden bookstore and he remembers her name.", owned: false },
    { title: "The Amber Spyglass", author: "Philip Pullman", category: "Fantasía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1609381000l/5949392.jpg", status: "read", rating: 5, description: "In the astonishing finale to the His Dark Materials trilogy, Lyra and Will are in unspeakable danger. With help from Iorek Byrnison the armored bear and two tiny Gallivespian spies, they must journey to a dank and gray-lit world where no living soul has ever gone. All the while, Dr. Mary Malone builds a magnificent Amber Spyglass. An assassin hunts her down, and Lord Asriel, with a troop of shining angels, fights his mighty rebellion, in a battle of strange allies—and shocking sacrifice.\n\nAs war rages and Dust drains from the sky, the fate of the living—and the dead—finally comes to depend on two children and the simple truth of one simple story.", owned: false },
    { title: "Fooled by Randomness: The Hidden Role of Chance in Life and in the Markets", author: "Nassim Nicholas Taleb", category: "Economía", coverUrl: "https://i.gr-assets.com/images/S/compressed.photo.goodreads.com/books/1328339070l/8536015.jpg", status: "read", rating: 4, description: "\"[Taleb is] Wall Street's principal dissident. . . . [Fooled By Randomness] is to conventional Wall Street wisdom approximately what Martin Luther's ninety-nine theses were to the Catholic Church.\"--Malcolm Gladwell, The New Yorker\n\nFinally in paperback, the word-of-mouth sensation that will change the way you think about the markets and the world. This book is about luck: more precisely how we perceive luck in our personal and professional experiences.  Set against the backdrop of the most conspicuous forum in which luck is mistaken for skill--the world of business--Fooled by Randomness is an irreverent, iconoclastic, eye-opening, and endlessly entertaining exploration of one of the least understood forces in all of our lives.\n— From the Trade Paperback edition.", owned: false },
    { title: "Fruticultura tropical", author: "José María Arias Rodríguez", category: "Agricultura", description: "Manual técnico sobre los principales frutales del trópico: variedades, requerimientos climáticos y edáficos, propagación, manejo del huerto, plagas, enfermedades y postcosecha." },
    { title: "Bacterias ácido lácticas: Fundamentos y aplicaciones", author: "Drider y Rivera", category: "Biología", description: "Tratado técnico sobre la taxonomía, fisiología, metabolismo y usos industriales de las bacterias ácido lácticas. Cubre su papel en la fermentación de productos lácteos, cárnicos y vegetales, en el desarrollo de probióticos y en la conservación de alimentos. Texto de referencia para microbiólogos de la industria alimentaria y para estudiantes universitarios del área.", descriptionAi: true },
    { title: "Más allá de las apariencias", author: "Raynald Pepin", category: "Filosofía", coverId: 12329266, description: "Ensayo que invita a mirar más allá de las superficies sociales y culturales para detectar las estructuras invisibles que organizan la vida cotidiana: instituciones, hábitos, expectativas y narrativas heredadas que damos por naturales. Una invitación a la sospecha bien entendida, en clave divulgativa y con ejemplos del mundo contemporáneo.", descriptionAi: true },
    { title: "El mango", author: "Yahia", category: "Agricultura", description: "Manual agronómico del cultivo del mango: variedades comerciales, requerimientos edafoclimáticos, propagación, manejo del huerto, fertilización, riego, control de plagas y enfermedades, cosecha y postcosecha. Pensado para productores tropicales que necesitan un texto técnico y a la vez práctico.", descriptionAi: true },
    { title: "Piratería: La invasión intelectual de Gutenberg a Gates", author: "Adrian Johns", category: "Historia", coverId: 14299638, description: "Reconstrucción de la larga historia del concepto de piratería intelectual desde los albores de la imprenta hasta el copyright digital. Recorre los conflictos por el control de la copia, los gremios de impresores, los litigios shakespearianos, las patentes industriales y las leyes contemporáneas de propiedad intelectual para mostrar que copiar y proteger han sido siempre caras de la misma moneda.", descriptionAi: true },
    { title: "Botánica de laboratorio", author: "Rita Yolanda Cavero y María Luisa López", category: "Biología", coverId: 14280546, description: "Cuaderno de prácticas para identificar, describir y dibujar tejidos y órganos vegetales. Ofrece guías taxonómicas, claves dicotómicas y técnicas microscópicas básicas para cursos universitarios de botánica general y sistemática, con ejemplos centrados en flora peninsular ibérica.", descriptionAi: true },
    { title: "El frijol silvestre: Síndrome de domesticación", author: "Cecilia Beatriz Peña Valdivia, J. Rogelio Aguirre R. y V. Baruch Arroyo Peña", category: "Agricultura", description: "Estudio detallado sobre los caracteres morfológicos, fisiológicos y genéticos que distinguen al frijol silvestre del cultivado, y sobre el proceso que llevó a Phaseolus vulgaris a convertirse en alimento básico mesoamericano. Recoge resultados de campo en México y revisa la literatura sobre domesticación de leguminosas.", descriptionAi: true },
    { title: "Los tres mosqueteros", author: "Alexandre Dumas", category: "Novela clásica", coverId: 12784165, description: "Folletín ambientado en la Francia de Luis XIII. D'Artagnan, un joven gascón ambicioso, llega a París, se gana a Athos, Porthos y Aramis en tres duelos sucesivos y se enrola en la guardia del rey. Juntos defienden el honor de la reina Ana de Austria contra las intrigas del cardenal Richelieu y de la implacable Milady de Winter. Un clásico de capa y espada que no envejece.", descriptionAi: true },
    { title: "Curso básico de tarot", author: "Varios autores", category: "Espiritualidad", coverId: 14625505, description: "Manual divulgativo para iniciarse en la lectura del tarot: significado simbólico de los arcanos mayores y menores, tiradas básicas como la cruz celta, nociones de interpretación intuitiva y consejos prácticos para llevar un cuaderno de lectura. Pensado para principiantes que se acercan al tarot desde la curiosidad simbólica.", descriptionAi: true },
    { title: "Cuentos de angustias y paisajes", author: "Carlos Salazar Herrera", category: "Cuentos", coverId: 6714606, description: "Colección clásica del costarricense Carlos Salazar Herrera, publicada en 1947: cuentos breves donde el paisaje rural se entrelaza con vidas marcadas por la pasión, la culpa y la fatalidad." },
    { title: "Escepticismo", author: "Maria Lorenza Chiesara", category: "Filosofía", coverId: 8659112, description: "María Lorenza Chiesara recorre el escepticismo griego de Pirrón a Sexto Empírico y la herencia del movimiento en la filosofía moderna y contemporánea." },
    { title: "Infocracia", author: "Byung-Chul Han", category: "Filosofía / Sociedad", description: "Byung-Chul Han analiza el régimen de información digital como una nueva forma de dominación que reemplaza a la disciplina y al panóptico clásicos, y diagnostica sus efectos sobre la democracia." },
    { title: "El contrato social", author: "Jean-Jacques Rousseau", category: "Filosofía / Política", coverId: 5229289, description: "Tratado político fundacional de 1762: toda autoridad legítima nace del pacto entre individuos libres, y la voluntad general —no la voluntad de todos— es el fundamento de la soberanía popular. La argumentación recorre la propiedad, el legislador, los magistrados, la religión civil y los regímenes políticos para construir una teoría exigente de la libertad republicana. Texto matriz del pensamiento democrático moderno.", descriptionAi: true },
    { title: "¿Qué es el estoicismo?", author: "Tanner Campbell y Kai Whiting", category: "Filosofía / Estoicismo", description: "Introducción contemporánea a la filosofía estoica: sus orígenes en la Stoa Poikile ateniense, sus figuras (Zenón, Epicteto, Séneca, Marco Aurelio), sus ideas clave —la dicotomía del control, la virtud como único bien, el cosmopolitismo— y su utilidad práctica frente a los desafíos actuales del trabajo, el duelo, la incertidumbre y la política.", descriptionAi: true },
    { title: "La Odisea", author: "Homero", category: "Mitología", coverId: 13180792, description: "Poema homérico que sigue el regreso de Odiseo a Ítaca tras la caída de Troya: diez años de tormentas, cíclopes, sirenas, ninfas y dioses caprichosos antes del reencuentro con Penélope y Telémaco. La obra inaugura la novela de aventuras, la épica del retorno y el motivo de la astucia como virtud política y doméstica.", descriptionAi: true },
    { title: "El viaje de Shuna", author: "Hayao Miyazaki", category: "Manga", description: "Manga ilustrado en acuarelas suaves: un joven príncipe parte de su valle estéril, en una geografía himaláyica imaginaria, en busca de un grano dorado que pueda salvar a su pueblo del hambre. Por el camino conoce a una esclava llamada Thea y atraviesa paisajes míticos. Un cuento iniciático cargado de poesía visual y de una mitología que prefigura mucho del cine posterior del estudio Ghibli.", descriptionAi: true },
    { title: "El mito de Sísifo", author: "Albert Camus", category: "Filosofía", description: "Ensayo fundacional del absurdo. ¿Por qué seguir viviendo cuando el universo carece de sentido? La respuesta filosófica recorre el suicidio, la rebelión y el arte, y culmina en la figura mitológica de Sísifo: condenado a empujar una roca por la eternidad, encuentra su libertad en la repetición consciente del esfuerzo y en el rechazo a la consolación metafísica. Una de las cumbres del existencialismo francés.", descriptionAi: true },
    { title: "El temor de un hombre sabio", author: "Patrick Rothfuss", category: "Fantasía", description: "Segunda parte de la Crónica del asesino de reyes. Kvothe continúa narrando su biografía: la corte de Vintas, la guerra contra los bandidos en el bosque de Eld, la estancia en los Adem aprendiendo el Ketan y el encuentro con Felurian en los Fata. La voz íntima y musical de la prosa convierte cada capítulo en un poema largo y la promesa del tercer volumen sigue alimentando la paciencia de sus lectores.", descriptionAi: true },
    { title: "La música del silencio", author: "Patrick Rothfuss", category: "Fantasía", description: "Novela breve que sigue a Auri, la enigmática habitante de los túneles bajo la Universidad de la Crónica del asesino de reyes, durante siete días en los que ordena su mundo subterráneo. Sin diálogos ni casi acción, el relato avanza al ritmo de los objetos y los nombres que ella inventa, con una prosa muy cercana al poema en prosa.", descriptionAi: true },
    { title: "Rubicón", author: "Tom Holland", category: "Historia", coverId: 3324864, description: "Los últimos cincuenta años de la República romana: las guerras civiles, las ambiciones desmedidas de Sila, Pompeyo y César, y el cruce simbólico del río Rubicón que cambió la historia política de Occidente. Crónica vívida y bien documentada del momento en que una república mediterránea se transformó en imperio, escrita con narratividad y ritmo de novela.", descriptionAi: true },
    { title: "Maquinaria y mecanización agrícola", author: "Armando Alvarado Chaves", category: "Agricultura", description: "Texto técnico sobre tractores, implementos y maquinaria empleados en las distintas etapas del cultivo: preparación del suelo, siembra, fertilización, control de malezas, cosecha y poscosecha. Énfasis en la selección de equipos adecuados al trópico húmedo, su operación y su mantenimiento.", descriptionAi: true },
    { title: "Química agroindustrial I", author: "Hermes Alvarado Montero y Carlos Alberto Vega Aguilar", category: "Química / Agricultura", description: "Manual universitario que aborda los fundamentos químicos de las materias primas agrícolas y de los procesos industriales que las transforman en alimentos, fibras y otros productos. Cubre carbohidratos, lípidos, proteínas, agua y minerales como bloques constructivos del análisis bromatológico, con prácticas de laboratorio asociadas.", descriptionAi: true },
    { title: "Cartografía geológica de la Península de Nicoya: Estratigrafía y tectónica", author: "Denyer, Aguilar y Montero", category: "Geología", description: "Levantamiento geológico detallado de la península costarricense de Nicoya: secuencias estratigráficas del Cretácico al Cuaternario, fallas tectónicas activas, basamento oceánico de las terrazas marinas y la historia geológica que las formó. Texto de referencia para geólogos, ingenieros y planificadores territoriales de la región.", descriptionAi: true },
    { title: "Metodología de la investigación", author: "Hernández Sampieri, Fernández Collado y Baptista Lucio", category: "Metodología de investigación", coverId: 8076589, description: "Manual de referencia obligatoria en Iberoamérica: cubre los enfoques cuantitativo, cualitativo y mixto, los pasos del proceso de investigación —del planteamiento del problema al informe final— con ejemplos para tesis y proyectos académicos. Trae instrumentos, modelos de análisis y guías de redacción, y se usa en facultades de educación, salud y administración por igual.", descriptionAi: true },
    { title: "Las aventuras de Huckleberry Finn", author: "Mark Twain", category: "Novela clásica", coverId: 13482322, description: "Mark Twain narra el viaje de Huck y el esclavo fugitivo Jim por el Misisipi en una balsa: una novela picaresca que retrata la sociedad sureña anterior a la Guerra Civil con humor y crítica racial." },
    { title: "Sentido y sensibilidad", author: "Jane Austen", category: "Novela clásica", coverId: 10450935, description: "Primera novela publicada, ambientada en la campiña inglesa a finales del XVIII. Tras la muerte del padre, las hermanas Dashwood y su madre quedan en una situación económica difícil; Elinor (la prudente) y Marianne (la apasionada) navegan amores, decepciones y reveses sociales que ponen a prueba sus temperamentos. Comedia de costumbres con un trasfondo de crítica al destino económico de las mujeres.", descriptionAi: true }
];
